INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('7e767786-3b02-4d03-83bf-e495458d3894', 'f950982d-9491-4f30-bee4-7a3948f5aa90', 'ae96cb87-27c2-4bae-96a1-a57b380a1444', NULL, '{"summary": "Posição líder no apoio às MPEs, mas precisa acelerar transformação digital e uso de dados para escalar impacto e enfrentar novos concorrentes e avanços da IA.", "threats": [{"source": "análise de mercado", "content": "Crescimento de plataformas privadas de educação e consultoria online", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Concorrência de consultores independentes com oferta personalizada", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Aceleração da IA reduzindo valor de conteúdos genéricos do Sebrae", "confidence": "Média"}, {"source": "estimativa", "content": "Possíveis cortes em contribuições sociais afetando orçamento", "confidence": "Média"}], "strengths": [{"source": "análise de mercado", "content": "Liderança institucional no apoio às MPEs do Tocantins", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Alta credibilidade da marca Sebrae junto a órgãos públicos", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Experiência consolidada em capacitação e consultorias para MPEs", "confidence": "Média"}, {"source": "análise de mercado", "content": "Capilaridade estadual com unidades físicas e canais remotos", "confidence": "Média"}], "weaknesses": [{"source": "análise de mercado", "content": "Uso de dados ainda limitado para gestão e personalização de serviços", "confidence": "Média"}, {"source": "estimativa", "content": "Baixa velocidade para adaptar-se a novas tecnologias digitais", "confidence": "Média"}, {"source": "fato", "content": "Dependência de recursos parafiscais para financiar operações", "confidence": "Alta"}, {"source": "estimativa", "content": "Dificuldade em medir impacto e ROI das ações de apoio às MPEs", "confidence": "Baixa"}], "opportunities": [{"source": "análise de mercado", "content": "Escalar atendimento digital de baixo custo para MPEs usando IA", "confidence": "Média"}, {"source": "estimativa", "content": "Criar trilhas online segmentadas por setor e maturidade das MPEs", "confidence": "Média"}, {"source": "análise de mercado", "content": "Firmar parcerias com bancos e governo para crédito assistido", "confidence": "Média"}, {"source": "estimativa", "content": "Integrar dados públicos e internos para segmentar e priorizar MPEs", "confidence": "Média"}]}'::jsonb, '{"legal": ["Com SELIC 14.90% a.a., mudanças em crédito para MEI podem excluir MPEs sem apoio jurídico", "PIB 2.20 % pressiona revisão de incentivos fiscais a pequenos; Sebrae deve monitorar normas", "Desemprego 5.60 % acelera políticas de formalização do MEI, exigindo orientação regulatória"], "social": ["Desemprego 5.60 % incentiva empreendedorismo por necessidade, elevando demanda por apoio Sebrae", "Inflação 0.09% (12 meses) preserva poder de compra para cursos acessíveis e trilhas online", "PIB per capita 47802.02 BRL limita ticket médio; é preciso formatos de baixo custo para MEIs"], "summary": "SELIC alta, PIB moderado (2.20 %), serviços 0.60 % e baixa inflação criam janela para expandir apoio digital, barato e segmentado às MPEs do Tocantins.", "economic": ["SELIC 14.90% a.a. eleva custo de crédito; MPEs buscam gestão financeira mais sofisticada", "Serviços 0.60 % sugerem espaço moderado para novas MPEs de serviços apoiadas pelo Sebrae TO", "Comércio -0.30 % e indústria -0.40 % indicam MPEs vulneráveis, exigindo ganhos de eficiência"], "political": ["SELIC 14.90% a.a. mantém política dura, reduzindo margem para subsídios a MPEs tocantinenses", "Incerteza sobre incentivos fiscais a pequenos com PIB em 2.20 % pode frear novos programas", "Desemprego 5.60 % pressiona governos locais a ampliar políticas de apoio a MPEs formais"], "environmental": ["PIB 12m 3.20 % permite atrelar programas verdes a cadeias locais de MPEs em crescimento moderado", "Inflação 0.09% (12 meses) viabiliza linhas verdes de baixo custo se houver desenho regulatório", "Custo da construção 0.27 % facilita adequações ambientais graduais em pontos físicos de MPEs"], "technological": ["Queda no comércio -0.30 % acelera migração de MPEs para vendas digitais com suporte remoto", "Alta em serviços 0.60 % favorece soluções de consultoria online e híbrida para pequenos negócios", "Juros 14.90% a.a. tornam tecnologia de produtividade crucial para viabilizar investimentos de MPEs"]}'::jsonb, '{"summary": "Ambiente de atratividade média: liderança institucional e forte potencial de parcerias compensam ameaça alta de substitutos e disrupção por IA; sucesso exige aceleração digital e uso intensivo de dados.", "buyer_power": "Poder de barganha alto: MPEs pressionadas por comércio -0,30%, indústria -0,40% e Selic 14,90% demandam mais subsídios e serviços digitais, com risco de migração para conteúdos gratuitos.", "supplier_power": "Poder de fornecedores médio: dependência de consultores e tecnologia; Selic em 14,90% a.a. encarece soluções privadas, exigindo contratos de longo prazo e maior uso de ferramentas abertas.", "disruption_ai_data": "Disrupção por IA/dados alta: IA generativa automatiza diagnósticos e conteúdo; Sebrae TO deve usar dados próprios e públicos para personalizar jornadas digitais e proteger relevância.", "threat_substitutes": "Substitutos em alta: cursos online, comunidades empresariais e conteúdo gratuito reduzem dependência do Sebrae; com desemprego em 5,60%, empreendedores priorizam soluções de baixo custo.", "competitive_rivalry": "Rivalidade média: consultores, agências e edtechs disputam MPEs; Sebrae TO é referência, mas precisa diferenciação digital e setorial, com foco em serviços (+0,60%) e PIB (+2,20%).", "threat_new_entrants": "Ameaça média de entrantes: credibilidade e governança limitam novos players locais, mas plataformas nacionais de educação e consultoria online conseguem escalar rápido no Tocantins.", "buyer_power_intensity": "Alta", "overall_attractiveness": "Média", "strategic_implications": ["Construir jornada digital RACE integrada (portal, app e CRM) com trilhas personalizadas por setor, usando dados das MPEs e indicadores locais para aumentar alcance, conversão e engajamento.", "Formalizar alianças com bancos, prefeituras e universidades para cooferta de programas e canais, compartilhando dados (respeitando LGPD) e reduzindo custo de aquisição e atendimento.", "Criar núcleo de IA e analytics para diagnóstico automatizado de negócios, segmentação de risco/oportunidade e medição de impacto em PIB, emprego e formalização, guiando a priorização.", "Reconfigurar portfólio presencial vs. online, focando soluções de alto valor percebido e baixo custo unitário, protegendo-se de substitutos gratuitos e mantendo capilaridade no interior."], "supplier_power_intensity": "Média", "disruption_ai_data_intensity": "Alta", "threat_substitutes_intensity": "Alta", "competitive_rivalry_intensity": "Média", "power_partnerships_ecosystems": "Parcerias com bancos, prefeituras e universidades têm poder alto para ampliar alcance e engajamento, otimizando recursos num cenário de serviços +0,60% e PIB em alta de 2,20%.", "threat_new_entrants_intensity": "Média", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": "Plano de 90 dias para estruturar base digital, territorial e financeira do apoio contínuo às MPEs no Tocantins.", "plan_90_days": [{"focus": "Fundação", "month": "Mês 1", "objective": "Mapear rede territorial e modelos de atendimento híbrido integrados ao digital", "investment": "R$ 15-20 mil", "key_results": ["Regional: mapear 30 municípios-alvo para pontos de apoio híbridos", "Jurídico: aprovar 1 minuta-padrão de convênio com prefeituras", "Operações: definir 3 roteiros-piloto para núcleos móveis no interior"], "aligned_recommendation": "Fortalecer atendimento híbrido com núcleos móveis e pontos de apoio em parceria com prefeituras e entidades locais"}, {"focus": "Crescimento", "month": "Mês 2", "objective": "Desenhar e especificar a Sebrae Tocantins Digital integrada ao atendimento híbrido", "investment": "R$ 20-40 mil", "key_results": ["TI: entregar 1 blueprint da plataforma digital validado pela diretoria", "UX: mapear 5 jornadas-chave de MPEs e MEIs no ecossistema Sebrae", "PMO: priorizar backlog inicial com 20 épicos para 2 sprints de MVP"], "aligned_recommendation": "Implantar plataforma integrada Sebrae Tocantins Digital para atendimento massivo às MPEs"}, {"focus": "Consolidação", "month": "Mês 3", "objective": "Estruturar piloto do Programa de Crédito Assistido com parceiros selecionados", "investment": "R$ 25-50 mil", "key_results": ["Parcerias: assinar 3 cartas de intenção com instituições financeiras", "Jurídico: concluir 1 parecer sobre riscos do crédito assistido", "Finanças: desenhar 1 fluxo-piloto de crédito assistido para até 50 MPEs"], "aligned_recommendation": "Estruturar programa de Crédito Assistido com rede de parcerias financeiras"}], "success_metrics": ["Blueprint da Sebrae Tocantins Digital aprovado e backlog inicial priorizado", "Minuta-padrão de convênio e parecer jurídico do crédito assistido concluídos", "Rede inicial de até 10 pontos de apoio híbridos planejados ou em implantação"], "execution_phases": {"scale": {"focus": "Expansão controlada", "duration": "Meses 7-12", "objectives": ["Escalar atendimento digital e híbrido para todo o estado com eficiência", "Consolidar programa de crédito assistido com rede estável de parceiros"], "key_results": ["Disponibilizar plataforma digital para 100% dos municípios do TO", "Atender 500 MPEs/MEIs em crédito assistido com inadimplência controlada"], "prerequisites": ["Validação bem-sucedida", "Métricas mínimas de satisfação e uso atingidas"], "investment_range": "R$ 120-180 mil"}, "foundation": {"focus": "Estruturação", "duration": "Meses 1-3", "objectives": ["Mapear rede territorial e requisitos da plataforma digital e do crédito assistido", "Estabelecer governança, jurídicos e arquitetura para pilotos controlados"], "key_results": ["Aprovar blueprint da plataforma e modelo-piloto de crédito assistido", "Formalizar pelo menos 5 parcerias locais para pontos de atendimento híbrido"], "investment_range": "R$ 60-110 mil", "capacity_requirements": {"team": "6-10 pessoas núcleo dedicado (multidisciplinar)", "dependencies": ["Aprovação da diretoria do Sebrae Tocantins para o plano 12 meses", "Disponibilidade de equipe de TI para integração com sistemas Sebrae"], "skills_needed": ["Gestão de projetos", "TI e UX", "Articulação institucional", "Gestão financeira e crédito", "Jurídico LGPD e convênios"]}}, "validation": {"focus": "Pilotos", "duration": "Meses 4-6", "objectives": ["Executar pilotos limitados da plataforma digital e do crédito assistido", "Coletar feedback de MPEs e parceiros e ajustar serviços e fluxos"], "key_results": ["Testar portal/app com 100 MPEs em 3 municípios-piloto", "Executar piloto de crédito assistido com até 30 MPEs acompanhadas"], "prerequisites": ["Fase 1 concluída", "Minutas de convênio e parecer jurídico aprovados"], "investment_range": "R$ 90-140 mil"}}, "total_investment": "R$ 60-110 mil", "capacity_assessment": {"blockers": ["Dependência de parecer jurídico e compliance para iniciar crédito assistido", "Limitação de equipe de TI interna para desenvolver e integrar a plataforma"], "team_readiness": "Média", "budget_adequacy": "Limitado", "stakeholder_alignment": "Parcial"}}'::jsonb, '{"roadmap": ["Curto Prazo (3-6 meses): Unificar base de dados, mapear jornada digital e capacitar equipe em analytics", "Médio Prazo (6-12 meses): Lançar plataforma de trilhas personalizadas e firmar 3 parcerias financeiras estratégicas", "Longo Prazo (12+ meses): Escalar ecossistema territorial com IA preditiva e dashboard público de impacto"], "key_findings": ["Ambiente de atratividade média: liderança compensa ameaça de substitutos, mas exige aceleração digital urgente", "Janela estratégica: inflação controlada e serviços em leve alta favorecem expansão de apoio digital segmentado", "Sucesso depende de mensurar impacto real (faturamento, empregos) para justificar investimentos e parcerias"], "main_findings": ["Força: Alta credibilidade institucional e capilaridade consolidada no estado, sendo referência no apoio a MPEs", "Fraqueza: Baixa maturidade digital e uso limitado de dados para personalização e mensuração de impacto", "Oportunidade: Cenário de crédito caro abre espaço para consultoria digital acessível e parcerias com fintechs", "Ameaça: Plataformas de IA e edtechs podem substituir serviços tradicionais com escala e custo inferior"], "important_notes": ["Modelo sem fins lucrativos limita investimentos; priorizar parcerias e recursos existentes", "Maturidade digital 6/10 exige capacitação interna antes de escalar soluções tecnológicas", "SELIC alta (14,9%) dificulta crédito às MPEs; articular linhas subsidiadas é crítico"], "central_challenge": "Escalar o apoio às MPEs do Tocantins com recursos limitados, transformando o modelo tradicional em um ecossistema digital, data-driven e territorialmente capilarizado que gere impacto mensurável.", "executive_summary": "O Sebrae Tocantins possui liderança institucional consolidada, mas enfrenta pressão de substitutos digitais e IA. O cenário macro (SELIC 14,9%, crédito caro) favorece soluções de baixo custo. A estratégia deve acelerar transformação digital, estruturar dados para personalização e fortalecer parcerias financeiras/governamentais para ampliar alcance e comprovar impacto em faturamento, sobrevivência e empregos das MPEs.", "strategic_priorities": ["Estruturar base de dados unificada para personalização e mensuração de impacto", "Lançar trilhas digitais segmentadas por setor e maturidade do negócio", "Firmar parcerias com fintechs e governo para crédito acessível às MPEs"], "consistency_validation": {"flags": ["Investimentos dependem de parcerias externas; sem receita própria significativa", "Equipe de 50-200 pode exigir contratações pontuais para analytics e tecnologia"], "legal_alignment": true, "capacity_alignment": true, "financial_alignment": true, "overall_realism_score": 7}, "overall_recommendation": "Priorizar transformação digital com foco em dados e parcerias, mantendo escopo realista aos recursos disponíveis. Começar pequeno, medir impacto e escalar com evidências."}'::jsonb, '{"sam": "R$ 24M - 40M", "som": "R$ 2M - 6M", "tam": "R$ 60M - 80M", "cagr": "+3% a.a. (baseado em: serviços 0,60% IBGE/BCB, ajustado por tendência digital)", "summary": "Mercado anual de apoio a MPEs no Tocantins estimado em R$ 60M-80M, com Sebrae TO podendo capturar R$ 2M-6M em cenário realista.", "assumptions": ["60-70 mil MPEs no TO via participação no nº nacional de empresas (IBGE)", "Gasto anual c/ apoio/capacitação: R$ 1k/MPE (benchmark serviços B2B Brasil)", "SAM = 30-50% do TAM, foco MPEs formais atendíveis (Sebrae/IBGE)"], "som_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 2M - 6M", "market_share": "8-15%"}, "optimistic": {"probability": 20, "value_range": "R$ 3,6M - 10M", "market_share": "15-25%"}, "conservative": {"probability": 30, "value_range": "R$ 0,7M - 3,2M", "market_share": "3-8%"}}, "tam_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 65M - 75M"}, "optimistic": {"probability": 20, "value_range": "R$ 75M - 80M"}, "conservative": {"probability": 30, "value_range": "R$ 60M - 65M"}}, "caveat_message": "⚠️ Estimativa baseada em benchmarks e proxies; recomenda-se validar com dados primários locais do Sebrae/IBGE.", "confidence_level": 45, "calculation_notes": "TAM via nº estimado de MPEs no Tocantins × gasto médio anual em apoio, consultoria e capacitação.", "data_sources_used": {"proxy_calculations": ["TAM ≈ 60-70 mil MPEs × R$ 1k/ano por empresa", "SAM ≈ 30-50% do TAM, limitado a MPEs alcançáveis por Sebrae/ políticas públicas"], "benchmark_extrapolations": ["Ticket anual R$ 1k/MPE inspirado em benchmarks de serviços B2B/educação corporativa", "Participação de TO estimada a partir da fatia do estado no PIB/empreendimentos nacionais"]}, "estimation_method": "benchmark_setorial", "baseline_recommendation": "conservative"}'::jsonb, '{"summary": "No mercado de R$ 60M–80M, o Sebrae TO é referência institucional, mas precisa acelerar digitalização e segmentação para capturar R$ 2M–6M adicionais em apoio às MPEs.", "best_practices": ["Marca Sebrae forte e reconhecida, gerando alta confiança das MPEs frente a novos entrantes.", "Rede capilar de atendimento presencial no Tocantins, alcançando municípios onde rivais não chegam.", "Portfólio amplo de capacitações e consultorias subsidiadas, reduzindo barreiras de acesso para MPEs."], "performance_gaps": ["Baixa oferta de atendimento 100% digital e escalável frente a plataformas online especializadas.", "Baixo uso de dados para segmentar ofertas por setor e maturidade, frente a consultores nichados.", "Medição limitada de impacto econômico dos programas, com poucos indicadores de resultado acompanhados."], "competitors_analyzed": ["Consultores de gestão independentes", "Agências de desenvolvimento regional", "Plataformas de educação corporativa online"]}'::jsonb, '{"raise": ["Uso de dados para priorizar negócios com maior risco ou potencial", "Acompanhamento intensivo nos primeiros 24 meses do negócio", "Parcerias com bancos e governo para soluções rápidas e integradas"], "create": ["Plataforma 24/7 de apoio com IA e especialistas locais sob demanda", "Trilhas contínuas por jornada do negócio, em vez de cursos soltos", "Radar territorial que antecipa demandas por região e cadeia produtiva"], "reduce": ["Uso de consultores para tarefas repetitivas e diagnósticos simples", "Eventos amplos de sensibilização sem apoio posterior", "Comunicação institucional e formalista com empreendedores"], "summary": "A estratégia transforma o Sebrae Tocantins em um orquestrador de um ecossistema de apoio contínuo, data-driven e territorial às MPEs, combinando IA, especialistas locais e parcerias financeiras e governamentais para gerar impacto mensurável em faturamento, sobrevivência e empregos.", "eliminate": ["Atendimentos presenciais burocráticos e demorados", "Cursos genéricos iguais para todos os perfis de empresa", "Projetos sem metas claras de faturamento ou empregos"], "new_value_curve": "Do atendimento genérico e reativo para um ecossistema digital, preditivo e contínuo de apoio às MPEs tocantinenses."}'::jsonb, '{"summary": "Growth focado em aquisição digital segmentada e trilhas personalizadas, medindo impacto por MPE para escalar receita e parcerias.", "leap_loop": {"name": "LEAP Loop", "type": "acquisition", "steps": ["Land: Atração por mídia digital segmentada + indicação de parceiros públicos, bancos e contadores do TO", "Engage: Jornada diagnóstica online guiada por IA com conteúdo local e trilhas sugeridas por setor/maturidade", "Activate: Ativação quando a MPE conclui diagnóstico e inicia trilha ou programa assistido do Sebrae Tocantins", "Propagate: Programa de indicação entre MPEs com benefícios em horas de consultoria e destaque em cases regionais"], "metrics": ["Leads de MPEs gerados/mês por canal", "Custo por MPE qualificada (CPL)", "Taxa de ativação diagnóstico→trilha", "Coeficiente viral (novas MPEs por indicação)"], "bottleneck": "Uso limitado de dados para segmentar e priorizar MPEs reduz eficiência das campanhas digitais e parcerias"}, "scale_loop": {"name": "SCALE Loop", "type": "monetization", "steps": ["Satisfy: Trilhas híbridas personalizadas + atendimento digital contínuo com foco em resultado mensurável por MPE", "Convert: Ofertas claras de cursos pagos acessíveis, consultorias premium e soluções de crédito assistido com parceiros", "Loop Back: Check-ups trimestrais de desempenho da MPE com novas recomendações de serviços e conteúdos acionáveis", "Expand: Upsell de projetos setoriais, consultorias especializadas e pacotes cofinanciados com bancos e governo"], "metrics": ["Receita média por MPE atendida (programas pagos e parcerias)", "Taxa de adesão a serviços pagos após trilhas gratuitas", "Retenção anual de MPEs em programas recorrentes", "Receita de expansão por upsell/cross-sell de soluções"], "bottleneck": "Baixa capacidade de medir impacto e ROI por MPE dificulta precificar, priorizar e expandir ofertas pagas"}}'::jsonb, '{"realist": {"name": "Cenário Realista", "description": "SELIC permanece alta em 14,90% a.a., PIB cresce 2,20% e serviços giram em torno de 0,60%, com comércio (-0,30%) e indústria (-0,40%) fracos. Inflação contida em 0,09% (12 meses), câmbio próximo de R$ 5,36 e desemprego em 5,60% criam ambiente estável, porém com crédito caro. MPEs priorizam caixa, exigindo apoio digital enxuto voltado a eficiência, gestão e formalização.", "probability": 60, "required_actions": ["Priorizar programas online de redução de custos, aumento de margem e gestão de caixa para MPEs.", "Mapear segmentos mais resilientes em serviços (0,60%) e focar ofertas digitais específicas para eles.", "Expandir atendimento remoto híbrido (on-line + pontos físicos) reduzindo custo por MPE atendida.", "Negociar com bancos públicos e regionais linhas de crédito assistido focadas em MPEs de maior risco."]}, "summary": "O Sebrae Tocantins opera em ambiente de juros altos (14,90% a.a.), PIB moderado (2,20%) e serviços em leve alta (0,60%), o que favorece apoio digital de baixo custo, porém com crédito caro. Há risco de aperto adicional ou desaceleração da atividade. Preparar portfólio flexível, monitorar SELIC, serviços, inflação e desemprego e alinhar parcerias financeiras e públicas são chaves para ampliar o apoio às MPEs e mitigar choques adversos.", "optimistic": {"name": "Cenário Otimista", "description": "Com SELIC recuando para 11% a.a. e PIB acima de 3%, serviços aceleram além de 1,5% (hoje 0,60%), inflação segue perto de 0,09% (12 meses) e câmbio cai de R$ 5,36 para abaixo de R$ 5,00. MPEs ampliam demanda por crédito e soluções digitais baratas, abrindo espaço para o Sebrae liderar apoio remoto segmentado em todo o Tocantins.", "probability": 20, "required_actions": ["Escalar rapidamente plataformas de atendimento digital segmentado por setor e porte de MPE no Tocantins.", "Lançar trilhas intensivas de gestão financeira e acesso a crédito para aproveitar apetite bancário.", "Firmar parcerias com fintechs e marketplaces para integrar serviços Sebrae em jornadas digitais das MPEs."]}, "pessimistic": {"name": "Cenário Pessimista", "description": "Aperto monetário eleva SELIC para acima de 16% a.a., PIB desacelera para abaixo de 1% e serviços recuam após os atuais 0,60%, acompanhando indústria (-0,40%) e comércio (-0,30%). Inflação sobe acima de 0,09% (12 meses), câmbio rompe R$ 5,80 e desemprego supera 7%. MPEs de Tocantins enfrentam queda de demanda e inadimplência, forçando o Sebrae a focar sobrevivência, renegociação e reorientação de negócios.", "probability": 20, "required_actions": ["Criar programas emergenciais de sobrevivência, renegociação de dívidas e revisão de modelos de negócio.", "Reforçar atendimento remoto em massa com conteúdos de crise, gestão de risco e apoio psicológico ao empreendedor.", "Articular com governo estadual e prefeituras subsídios, compras públicas e prorrogação de obrigações para MPEs."]}, "mitigation_tactics": ["Desenvolver portfólio digital modular que possa ser rapidamente redirecionado entre crescimento, eficiência e sobrevivência, conforme o cenário.", "Construir painéis internos de monitoramento com dados do IBGE/BCB (PIB 2,20%, serviços 0,60%, juros 14,90%, desemprego 5,60%) para decisões rápidas.", "Diversificar parcerias (bancos, fintechs, cooperativas, prefeituras) para compartilhar risco e ampliar canais de apoio às MPEs.", "Fortalecer capacidades analíticas e de segmentação de MPEs no Tocantins para direcionar recursos às empresas mais vulneráveis ou estratégicas em cada cenário."], "early_warning_signals": ["Mudanças bruscas na SELIC em relação aos 14,90% a.a. atuais (cortes acelerados ou alta adicional).", "Desaceleração acentuada ou forte aceleração do volume de serviços em relação aos 0,60% atuais, especialmente em segmentos intensivos em MPEs.", "Alta da inflação acima dos 0,09% (12 meses) combinada com desvalorização do câmbio além de R$ 5,36/USD e aumento do desemprego além de 5,60%."]}'::jsonb, '{"summary": "BSC foca impacto econômico das MPEs, satisfação, processos data-driven e desenvolvimento da equipe.", "customer": ["Atingir NPS ≥ 80 entre MPEs atendidas em todos os territórios do Tocantins", "Expandir em 30% o número de MPEs atendidas por ano no estado"], "financial": ["Aumentar em 15% o faturamento médio anual das MPEs atendidas até 2027", "Elevar em 20% a taxa de sobrevivência de MPEs atendidas em 3 anos"], "learning_growth": ["Capacitar 100% da equipe em uso de IA, dados e atendimento consultivo às MPEs", "Criar programa contínuo de formação de líderes locais e parceiros estratégicos"], "internal_processes": ["Implantar plataforma data-driven integrada a IA para gestão do ecossistema MPE", "Redesenhar jornada de atendimento territorial multicanal focada em MPEs"]}'::jsonb, '{"score": "8.4/10", "summary": "A matriz multicriterial indica que o crescimento digital escalável oferece maior impacto no alcance às MPEs do Tocantins, com melhor eficiência de custo e menor complexidade jurídica, especialmente em um cenário de juros altos (14,90% a.a.), PIB moderado (2,20%) e serviços em leve alta (0,60%). A recomendação é: (1) implantar, em 9-12 meses, uma plataforma digital integrada como eixo central; (2) estruturar, em 6-9 meses, um programa de crédito assistido com parecer jurídico prévio e convênios padronizados; e (3) fortalecer, em 3-6 meses, um modelo híbrido com núcleos móveis e pontos de apoio locais conectados ao canal digital. O ciclo de revisão trimestral, com gatilhos extraordinários regulatórios e de compliance, permitirá ajustar rapidamente o portfólio e a intensidade de cada estratégia, maximizando o apoio às micro e pequenas empresas e mitigando riscos jurídicos e institucionais.", "criteria": ["Impacto no alcance das MPEs (escala e inclusão territorial)", "Eficiência de custo e uso de recursos (custo por empresa atendida)", "Complexidade de implementação e risco (operacional e jurídico)"], "alternatives": ["Crescimento Digital Escalável (plataforma e atendimento remoto)", "Crescimento via Crédito Assistido e Parcerias Financeiras", "Crescimento Territorial e Presencial (hubs físicos e ações móveis)"], "review_cycle": {"frequency": "Trimestral", "extraordinary_triggers": ["Mudança regulatória que exija >10% de ajuste de custo", "Nova exigência de licenciamento que bloqueie operação", "Decisão judicial que afete modelo de negócio", "Falha de compliance LGPD/setorial", "Entrada de competidor relevante"]}, "score_comparison": "+18% acima da segunda opção", "monitoring_metrics": ["Número de MPEs/MEIs atendidos por mês (total e por município)", "Custo médio por empresa atendida (presencial + digital)", "Taxa de adesão e conclusão das trilhas digitais de capacitação", "Volume de crédito assistido viabilizado (R$) e número de operações apoiadas", "Índice de satisfação/NPS dos participantes dos programas", "Cobertura territorial: percentual de municípios do Tocantins com ações ativas", "Taxa de recorrência: MPEs que retornam para novos serviços em 12 meses"], "recommended_option": "Crescimento Digital Escalável (plataforma e atendimento remoto)", "final_recommendation": "A melhor opção é priorizar o crescimento digital escalável, com plataforma integrada e atendimento remoto de baixo custo, complementado gradualmente por crédito assistido e atendimento híbrido nas regiões com maior demanda e menor inclusão digital.", "priority_recommendations": [{"title": "Implantar plataforma integrada Sebrae Tocantins Digital para atendimento massivo às MPEs", "budget": "R$150-250k", "priority": 1, "timeline": "9-12 meses", "description": "Desenvolver e escalar uma plataforma digital integrada (portal/app) com trilhas de capacitação, diagnósticos rápidos, agendamento de consultorias remotas e conteúdo segmentado por setor. Foco em baixo custo marginal por empresa, altas doses de automação (chat, FAQs inteligentes) e integração com canais já existentes do Sebrae. Priorizar inclusão de MPEs em todo o estado, especialmente em municípios com menor acesso a atendimento presencial.", "legal_feasibility": {"risk_level": "Baixo", "mitigation_plan": "Realizar revisão de LGPD e termos de uso antes do lançamento; incluir cláusulas de confidencialidade e segurança da informação nos contratos de TI; prever política clara de consentimento e descarte de dados dos empreendedores.", "requires_legal_opinion": false, "regulatory_dependencies": ["Adequação à LGPD (políticas de privacidade e tratamento de dados)", "Contratos de prestação de serviços de TI e nuvem", "Conformidade com diretrizes internas do Sistema S para canais digitais"], "requires_statutory_change": false}}, {"title": "Estruturar programa de Crédito Assistido com rede de parcerias financeiras", "budget": "R$80-120k", "priority": 2, "timeline": "6-9 meses", "description": "Criar um programa estruturado de crédito assistido, articulando bancos públicos, cooperativas de crédito e agências de fomento para oferecer produtos financeiros adequados às MPEs em cenário de juros a 14,90% a.a. Combinar orientação em gestão financeira, avaliação de capacidade de pagamento, preparo de documentos e acompanhamento pós-crédito. Focar em reduzir inadimplência e melhorar a alocação do crédito, sem que o Sebrae atue como agente financeiro.", "legal_feasibility": {"risk_level": "Médio", "mitigation_plan": "Obter parecer jurídico antes da assinatura de convênios, delimitando claramente que o Sebrae não concede crédito nem assume risco financeiro; padronizar minutas de convênios com cláusulas de responsabilidade bem definidas; criar protocolo de orientação sem recomendação de produtos específicos para evitar conflito de interesses; como alternativa de menor risco, priorizar inicialmente ações de educação financeira e preparação para o crédito sem intermediar operações.", "requires_legal_opinion": true, "regulatory_dependencies": ["Convênios e termos de cooperação com instituições financeiras", "Análise de enquadramento regulatório junto ao BACEN (por meio dos parceiros financeiros)", "Políticas internas de prevenção à lavagem de dinheiro (quando aplicável nos convênios)"], "requires_statutory_change": false}}, {"title": "Fortalecer atendimento híbrido com núcleos móveis e pontos de apoio em parceria com prefeituras e entidades locais", "budget": "R$40-60k", "priority": 3, "timeline": "3-6 meses", "description": "Ampliar o alcance territorial por meio de unidades móveis, mutirões itinerantes e fortalecimento de salas do empreendedor e pontos de atendimento em parceria com prefeituras, associações comerciais e sindicatos. Integrar esses pontos ao canal digital, usando-os como portas de entrada e apoio à adesão às trilhas online, priorizando regiões com menor inclusão digital.", "legal_feasibility": {"risk_level": "Baixo", "mitigation_plan": "Utilizar modelos padronizados de convênios já adotados pelo Sebrae; revisar responsabilidades por uso de espaços, segurança e divulgação; garantir cláusulas de proteção de marca e de compartilhamento responsável de dados dos participantes.", "requires_legal_opinion": false, "regulatory_dependencies": ["Convênios ou termos de cooperação com prefeituras e entidades parceiras", "Adequação a normas municipais de uso de espaço público para ações itinerantes"], "requires_statutory_change": false}}]}'::jsonb, 'completed', NULL, 340048, true, false, true, 'MKD34PZD', '2025-12-04 18:55:00.181202+00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-04 18:45:49.877598+00'::timestamptz, '2025-12-04 18:55:00.181202+00'::timestamptz, '2025-12-04 18:51:29.670377+00'::timestamptz, NULL)
