INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('0935778d-a8d8-4b2d-bf6b-df11d6c6f1e1', 'f3f5f892-2d02-4473-8d2d-f1cad0d481ad', 'b0675a04-b602-4ecb-b724-663f021bdf73', NULL, '{"summary": "Marca eco-luxury forte e digitalmente madura, com espaço para escalar SPAs, amenities e Santopé, mas sob pressão de juros altos e gigantes globais.", "threats": [{"source": "análise de mercado", "content": "Rivalidade intensa com L''Occitane, Natura, Boticário no luxo e bem-estar", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Hotéis e SPAs com alto poder de barganha pressionando preço e condições", "confidence": "Média"}, {"source": "análise de mercado", "content": "Câmbio USD/BRL R$ 5.36 encarece insumos importados e viagens internacionais", "confidence": "Média"}, {"source": "análise de mercado", "content": "Regulação ANVISA e normas verdes elevam custos e risco em novos SKUs e SPAs", "confidence": "Média"}], "strengths": [{"source": "fato", "content": "Origem nos hotéis Emiliano, com prova social forte em hospitalidade de luxo", "confidence": "Alta"}, {"source": "fato", "content": "Posicionamento claro de eco-luxury, alinhado à alta renda e sustentabilidade", "confidence": "Alta"}, {"source": "fato", "content": "Modelo híbrido: SPAs franqueados, amenities B2B e D2C com ecommerce próprio", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Boa maturidade digital (8/10) para acelerar aquisição D2C e relacionamento", "confidence": "Média"}], "weaknesses": [{"source": "análise de mercado", "content": "Escala e orçamento de marketing menores que L''Occitane, Natura e Boticário", "confidence": "Média"}, {"source": "fato", "content": "Dependência da marca Emiliano para reconhecimento e prova de qualidade", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Capital próprio limitado em cenário de SELIC 14.90%, freando expansão rápida", "confidence": "Média"}, {"source": "análise de mercado", "content": "Complexidade de operar hotelaria, ecommerce, franquias e futuro canal farma", "confidence": "Média"}], "opportunities": [{"source": "análise de mercado", "content": "Escalar franquias de SPA em hotéis 5* além do Emiliano, rivalizando L''Occitane", "confidence": "Média"}, {"source": "análise de mercado", "content": "Expandir venda de amenities eco-luxury para redes de hotéis de luxo globais", "confidence": "Média"}, {"source": "fato", "content": "Lançar linha Santopé completa e ganhar nicho premium de cuidados para pés", "confidence": "Alta"}, {"source": "estimativa", "content": "Entrar em farmácias selecionadas com Santopé, reforçando awareness D2C", "confidence": "Média"}]}'::jsonb, '{"legal": ["Regulamentações ANVISA podem endurecer testes e alegações naturais, exigindo investimento em P&D regulatório.", "Evolução de normas ambientais traz risco de multas se comunicação eco-luxury não tiver lastro documental.", "Expansão via franquias de SPA exige contratos robustos frente ao CDC, evitando conflitos sobre experiência."], "social": ["Desemprego em 5,60% mantém consumo seletivo; branding forte é crítico para a marca eco-luxury.", "Inflação baixa (0,09% a.a.) preserva poder de compra da alta renda, apoiando tickets elevados no D2C.", "Busca por bem-estar e autocuidado abre janela para linha Santopé liderar categoria premium de pés."], "summary": "Juros altos, serviços em alta e câmbio pró-turismo criam cenário misto. Escalar SPAs e novas linhas com rigor regulatório e autenticidade eco-luxury será chave para capturar o ciclo de bem-estar.", "economic": ["Juros de 14,90% a.a. encarecem capital; franquias de SPA ganham apelo como modelo asset-light.", "PIB +2,20% e serviços +0,60% sugerem retomada gradual da demanda B2B por amenities e SPAs premium.", "Câmbio a R$ 5,36/USD encarece insumos importados, mas reforça atratividade do Brasil para turistas."], "political": ["Política monetária restritiva (juros 14,90% a.a.) limita crédito para expansão de SPAs parceiras.", "Serviços em alta (+0,60%) tende a ganhar atenção política, abrindo espaço a pautas pró-turismo wellness.", "Agenda pública de sustentabilidade pode priorizar hotelaria verde, favorecendo proposta eco-luxury da marca."], "environmental": ["Normas de sustentabilidade ambiental tendem a exigir métricas de impacto; oportunidade de liderar transparência.", "Pressão por cadeias limpas favorece fornecedores locais, reduzindo exposição ao câmbio de R$ 5,36/USD.", "Turismo consciente valoriza amenities recarregáveis/refil; chance de testar modelos circulares com hotéis."], "technological": ["Aceleração do ecommerce/D2C permite testar novos SKUs Santopé com baixo risco e feedback rico do cliente.", "Logística verde e compensação de carbono viram requisito em redes hoteleiras; atual vantagem pode commoditizar.", "Maturidade digital 8/10 habilita personalização online superior à de concorrentes tradicionais de cosméticos."]}'::jsonb, '{"summary": "Mercado atrativo porém exigente: rivalidade e poder de compradores são altos, mas crescimento em serviços (0.60%), narrativa eco-luxury e parcerias em hospitalidade criam espaço para captar valor via diferenciação e ações RACE em B2B e D2C.", "buyer_power": "Alto poder dos compradores: hotéis de luxo e redes farma concentram demanda e pressionam descontos; com comércio em -0.30% e desemprego em 5.60%, consumidor final fica seletivo, exigindo valor percebido e experiência superior.", "supplier_power": "Alto poder dos fornecedores: insumos e embalagens premium, muitos atrelados ao dólar a R$ 5.36/USD, somados ao juros de 14.90% a.a., comprimem margens e limitam capacidade da Santapele de renegociar preços e prazos.", "disruption_ai_data": "Disrupção por IA/dados média: D2C de beleza acelera uso de IA para personalização, mídia paga e CRM; sem investir em analytics proprietário, a Santapele perde eficiência de aquisição e retenção frente a players digitais mais capitalizados.", "threat_substitutes": "Ameaça alta de substitutos: amenities genéricos mais baratos, marcas globais em SPAs e dermocosméticos farma oferecem alternativas; juros de 14.90% e dólar a R$ 5.36/USD incentivam hotéis a migrar para opções de menor custo ou white label.", "competitive_rivalry": "Rivalidade alta: Natura, Boticário, Granado e L’Occitane disputam nicho premium; retração do comércio em -0.30% força guerra por contratos B2B e share D2C, exigindo diferenciação forte em eco-luxo e SPA autoral.", "threat_new_entrants": "Ameaça média: crescimento de serviços em 0.60% atrai novos SPAs e marcas indie D2C, mas exigências ANVISA, certificações verdes e capital caro a 14.90% a.a. elevam barreiras e protegem o posicionamento eco-luxury da Santapele.", "buyer_power_intensity": "Alta", "overall_attractiveness": "Média", "strategic_implications": ["Fortalecer contratos âncora com redes de hotéis e SPAs, com propostas exclusivas e SLAs rígidos.", "Criar plataforma D2C orientada por dados, com personalização de jornada e programa de fidelidade.", "Desenvolver sourcing sustentável multi-fornecedor para reduzir risco cambial e de concentração.", "Acelerar uso de IA em mídia, precificação e previsão de demanda para ganhar eficiência em escala."], "supplier_power_intensity": "Alta", "disruption_ai_data_intensity": "Média", "threat_substitutes_intensity": "Alta", "competitive_rivalry_intensity": "Alta", "power_partnerships_ecosystems": "Parcerias têm poder alto: serviços em alta (0.60%) favorecem expansão com redes hoteleiras, SPAs, farmácias e marketplaces; alianças em sustentabilidade e logística verde reforçam narrativa eco-luxury e ampliam alcance B2B e D2C.", "threat_new_entrants_intensity": "Média", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": "Plano de 90 dias para estruturar D2C eco-luxury, pilotar Santopé e preparar expansão B2B/SPAs.", "plan_90_days": [{"focus": "Fundação", "month": "Mês 1", "objective": "Estruturar base D2C eco-luxury com dados, LGPD e visão integrada de canais", "investment": "R$ 10-20 mil", "key_results": ["Selecionar e contratar ferramenta de CRM integrada ao ecommerce. Resp: Marketing", "Revisar LGPD, termos e política de privacidade do site. Resp: Jurídico", "Mapear jornada D2C e definir 3 personas prioritárias. Resp: Conselho/Marketing"], "aligned_recommendation": "Fortalecer D2C e comunidade de marca eco-luxury"}, {"focus": "Crescimento", "month": "Mês 2", "objective": "Desenvolver e lançar piloto da linha Santopé em D2C e canal farma selecionado", "investment": "R$ 20-40 mil", "key_results": ["Concluir desenvolvimento de 3-4 SKUs Santopé com ANVISA ok. Resp: P&D", "Lançar piloto Santopé no ecommerce com 2 bundles testados. Resp: Marketing", "Fechar 1 contrato-piloto com farmácia premium em SP. Resp: Comercial"], "aligned_recommendation": "Desenvolver e pilotar a linha Santopé como plataforma de cuidado premium para os pés"}, {"focus": "Consolidação", "month": "Mês 3", "objective": "Preparar modelo asset-light para expansão B2B em hotéis de luxo e SPAs", "investment": "R$ 30-50 mil", "key_results": ["Desenhar playbook preliminar de franquia/SPA Emiliano. Resp: Operações", "Identificar e priorizar 5 hotéis-alvo para amenities e SPA. Resp: Comercial", "Obter parecer jurídico inicial sobre franquias e contratos. Resp: Jurídico"], "aligned_recommendation": "Expansão seletiva B2B em hotelaria de luxo e SPAs franqueados (modelo asset-light)"}], "success_metrics": ["CRM D2C implantado e operante com base unificada de clientes", "Linha Santopé com 3-4 SKUs pronta e piloto ativo em ecommerce/farma", "Playbook inicial de SPA/franquia e pipeline de hotéis-alvo estruturados"], "execution_phases": {"scale": {"focus": "Expansão controlada", "duration": "Meses 7-12", "objectives": ["Escalar D2C eco-luxury com foco em recorrência e comunidade", "Ampliar rede de hotéis e SPAs franqueados em modelo asset-light"], "key_results": ["Alcançar 3 SPAs franqueados operando com playbook padronizado", "Fechar 8-10 novos contratos de amenities em hotéis de luxo"], "prerequisites": ["Validação bem-sucedida de Santopé, D2C e pilotos B2B", "Métricas mínimas de giro, margem e satisfação atingidas"], "investment_range": "R$ 150-200 mil"}, "foundation": {"focus": "Estruturação", "duration": "Meses 1-3", "objectives": ["Criar base jurídica, digital e de dados para D2C, Santopé e B2B", "Estruturar governança mínima para franquias e expansão hotelaria"], "key_results": ["CRM unificado ativo para D2C e relacionamento B2B", "Políticas LGPD, ANVISA e minuta-base de franquia definidas"], "investment_range": "R$ 60-110 mil", "capacity_requirements": {"team": "4-6 pessoas", "dependencies": ["Advogado externo especializado em digital, ANVISA e franchising", "Parceiros de logística e meios de pagamento para ecommerce"], "skills_needed": ["Marketing digital e CRM D2C", "Jurídico regulatório (LGPD, ANVISA, franquias)", "Comercial B2B hotelaria de luxo", "Gestão de produto cosmético e P&D"]}}, "validation": {"focus": "Pilotos", "duration": "Meses 4-6", "objectives": ["Validar aceitação da linha Santopé em ecommerce e 1-2 farmácias premium", "Testar pilotos de amenities e/ou SPA em 1-2 hotéis fora da base Emiliano"], "key_results": ["2 pilotos Santopé ativos (ecommerce e pelo menos 1 farmácia)", "1 contrato-piloto ativo de SPA ou amenities em novo hotel"], "prerequisites": ["Fase 1 concluída", "Aprovações e pareceres jurídicos críticos obtidos"], "investment_range": "R$ 80-120 mil"}}, "total_investment": "R$ 60-110 mil", "capacity_assessment": {"blockers": ["Capital próprio limitado em cenário de SELIC 14.90%, exigindo expansão asset-light", "Ausência de equipe dedicada a franquias e canal farma aumenta risco de sobrecarga"], "team_readiness": "Média", "budget_adequacy": "Limitado", "stakeholder_alignment": "Parcial"}}'::jsonb, '{"roadmap": ["Curto Prazo (3-6 meses): Estruturar clube de assinatura D2C, lançar linha completa Santopé (4-5 SKUs), fechar 2 pilotos B2B hotelaria", "Médio Prazo (6-12 meses): Escalar Santopé para 3 redes Farma, converter pilotos B2B em contratos recorrentes, validar modelo de franquia SPA com 1-2 unidades", "Longo Prazo (12+ meses): Expandir franquias SPA seletivamente (3-5 unidades), internacionalizar amenities para hotéis latam, consolidar liderança em cuidados premium para pés"], "key_findings": ["Oceano azul identificado: integração eco-luxury + hospitalidade + Santopé cria ecossistema único sem concorrência direta", "Modelo de franquia SPA tem unit economics atrativo (fee + royalties + venda de produtos) mas exige capital paciente", "D2C recorrente via clubes de assinatura pode gerar caixa previsível para financiar expansão B2B"], "main_findings": ["FORÇA: Marca eco-luxury pioneira com credencial Emiliano e ecommerce maduro (maturidade digital 8/10)", "FRAQUEZA: Escala limitada e equipe enxuta (1-10) para operar 4 canais simultâneos com complexidade logística", "OPORTUNIDADE: Categoria de cuidados premium para pés (Santopé) sem concorrência direta e SPAs em crescimento", "AMEAÇA: Juros de 14,9% encarecem expansão de franquias e gigantes globais dominam o segmento de SPAs em hotéis"], "important_notes": ["Custo de capital alto (Selic 14,9%) exige autofinanciamento e pilotos antes de escalar franquias", "Equipe de 1-10 pessoas é gargalo crítico para executar 4 frentes simultaneamente", "Regulamentação ANVISA e certificações eco são barreiras de entrada que protegem a marca"], "central_challenge": "Escalar uma marca eco-luxury bootstrapped em múltiplos canais (B2B hotelaria, franquias SPA, D2C, linha Santopé) com capital caro (Selic 14,9%) e equipe enxuta, competindo contra gigantes globais como L''Occitane.", "executive_summary": "Santapele possui posicionamento único de eco-luxury nascido no Hotel Emiliano, com maturidade digital alta e diversificação de canais. O cenário macro favorece serviços (SPAs +0,60%) mas pressiona expansão via juros elevados. Priorizar disciplina de caixa, pilotos seletivos B2B e fortalecimento D2C antes de escalar franquias. Santopé representa oportunidade de categoria nova com baixa competição premium.", "strategic_priorities": ["Fortalecer D2C com recorrência para gerar caixa e reduzir dependência de capital externo", "Pilotar Santopé no canal Farma com 2-3 redes antes de escalar nacionalmente", "Selecionar 3-5 hotéis de luxo estratégicos para pilotos B2B com métricas claras de conversão"], "consistency_validation": {"flags": ["CAPACIDADE: Equipe de 1-10 pessoas é insuficiente para 4 canais - recomenda-se foco em 2 frentes prioritárias (D2C + Santopé) antes de escalar B2B/franquias", "FINANCEIRO: Expansão de franquias com Selic 14,9% exige autofinanciamento - OKRs de franquia devem ser condicionados a geração de caixa prévia"], "legal_alignment": true, "capacity_alignment": false, "financial_alignment": true, "overall_realism_score": 7}, "overall_recommendation": "Adotar estratégia de ''crescimento disciplinado'': priorizar caixa via D2C e Santopé antes de escalar franquias. Expansão B2B deve ser seletiva e autofinanciada. Conselho deve monitorar burn rate e evitar dispersão em múltiplas frentes simultâneas."}'::jsonb, '{"sam": "R$ 300M - 600M", "som": "R$ 9M - 90M", "tam": "R$ 3B - 6B", "cagr": "+5% a.a. (baseado em: serviços +0,60% IBGE, varejo -0,30% e tendência bem-estar/eco)", "summary": "Nicho de eco-luxury em beleza e SPA no Brasil indica SOM de R$9-90M/ano em 5-7 anos, focando hotéis de luxo, SPAs e D2C.", "assumptions": ["Mercado beleza BR ~R$120-150B; luxo/eco 2-4% ⇒ TAM R$3-6B (ABIHPEC+ajuste nicho)", "Amenities SPA/hotel+footcare ≈10% do luxo ⇒ SAM R$300-600M (proxy canais)", "Santapele PME pode capturar 3-15% do SAM em 5-7 anos (market share alvo)"], "som_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 30M - 60M", "market_share": "10%"}, "optimistic": {"probability": 20, "value_range": "R$ 45M - 90M", "market_share": "15%"}, "conservative": {"probability": 30, "value_range": "R$ 9M - 18M", "market_share": "3%"}}, "tam_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 4B - 5B"}, "optimistic": {"probability": 20, "value_range": "R$ 5B - 6B"}, "conservative": {"probability": 30, "value_range": "R$ 3B - 4B"}}, "confidence_level": 60, "calculation_notes": "TAM via % luxo/eco do mercado beleza BR; SAM como 10% focado em amenities+SPA; SOM por shares 3-15% sobre SAM.", "data_sources_used": {"direct_data": ["Faturamento Santapele R$1,5-2,0M/ano (dados do cliente)"], "proxy_calculations": ["Share alvo 3-15% sobre SAM R$300-600M para projetar SOM R$9-90M", "SAM como 10% do segmento luxo/eco focado em hotéis de luxo, SPAs e footcare"], "benchmark_extrapolations": ["Mercado beleza BR ~R$120-150B (ABIHPEC) com luxo/eco 2-4%", "Macro: serviços +0,60%, comércio -0,30%, juros 14,90% a.a. (IBGE/BCB)"]}, "estimation_method": "benchmark_setorial", "baseline_recommendation": "conservative"}'::jsonb, '{"summary": "Santapele enfrenta gigantes multicanais, mas o nicho eco-luxury sugere SOM de R$9-90M/ano em 5-7 anos via hotéis, SPAs e D2C.", "best_practices": ["Posicionamento claro em eco-luxury, alinhado à tendência global de beleza limpa e sustentável.", "Origem na hospitalidade de luxo (Emiliano), gerando autoridade para assinar SPAs de hotéis premium.", "Modelo híbrido B2B, D2C e franquias de SPA, diluindo risco e elevando ticket médio por cliente."], "performance_gaps": ["Baixa notoriedade nacional frente a Natura, Boticário, Granado e L''Occitane no público final.", "Portfólio e canais ainda concentrados em SPAs/hotelaria, com pouca capilaridade em varejo e farma.", "Menor escala produtiva e de mídia, limitando margem para promoções agressivas e investimentos em P&D."], "competitors_analyzed": ["L''Occitane", "Granado", "Natura &Co", "Boticário"]}'::jsonb, '{"raise": ["Prova científica de bem-estar e performance dos protocolos SPA", "Personalização de amenities por hotel, clima e cultura local", "Integração logística verde em toda a cadeia B2B e D2C"], "create": ["Plataforma data-driven de conversão hóspede→cliente D2C recorrente", "Categoria líder de cuidado premium para pés com foco Farma + SPA", "Rede de SPAs-boutique assinatura Santapele com design brasileiro autoral"], "reduce": ["Dependência de reconhecimento via marca Emiliano", "Portfólio de SKUs pouco rentáveis ou canibais", "Intermediação em vendas D2C sem dados primários"], "summary": "Santapele abre um oceano azul ao integrar eco-luxo, ciência do bem-estar, dados de hospitalidade e a categoria líder em cuidado premium para pés, criando um ecossistema único entre hotéis de luxo, SPAs-franquia e D2C recorrente.", "eliminate": ["Amenities genéricos sem identidade de experiência", "Promoções baseadas apenas em desconto de volume", "Parcerias com hotéis fora do recorte de luxo sustentável"], "new_value_curve": "De fornecedora de cosméticos a ecossistema eco-luxury de bem-estar, unindo hotelaria, SPAs e D2C com dados e nichos premium."}'::jsonb, '{"summary": "Alavancar eco-luxury para captar hotéis, SPAs e D2C com pilotos rápidos, depois monetizar via franquias, cross-sell Santopé e recorrência em clubes.", "leap_loop": {"name": "LEAP Loop", "type": "acquisition", "steps": ["Land: ABM e parcerias para captar hotéis 5*, SPAs franqueados, D2C e canal farma eco-luxury", "Engage: Amostras e experiências sensoriais, conteúdo premium e CRM segmentado para cada persona", "Activate: Pilotos rápidos de amenities e SPA em poucos hotéis + bundles exclusivos no ecommerce e farma", "Propagate: Programas de indicação entre hotéis, UGC dos hóspedes e cliente final, kits presenteáveis e co-branding"], "metrics": ["CAC por canal (hotel, SPA, D2C, farma)", "Taxa de conversão lead→contrato/compra", "Coeficiente viral (indicação hotéis, SPAs e D2C)"], "bottleneck": "Baixo awareness fora do Emiliano e orçamento de marketing menor que concorrentes globais, limitando geração eficiente de leads qualificados"}, "scale_loop": {"name": "SCALE Loop", "type": "monetization", "steps": ["Satisfy: Protocolos de SPA consistentes, qualidade eco-luxury e suporte próximo a hotéis, franqueados e D2C", "Convert: Estruturar pacotes e contratos claros de amenities, franquias SPA e upsell de linhas Santopé e varejo", "Loop Back: Clubs e assinaturas, CRM com jornadas por segmento e programas de fidelidade para hotéis, SPAs e D2C", "Expand: Cross-sell entre SPA, amenities, ecommerce e farma; lançamentos de SKUs Santopé e expansão internacional"], "metrics": ["LTV por segmento (hotel, SPA, D2C, farma)", "Taxa de recompra e ocupação/uso recorrente dos SPAs", "Receita de expansão (upsell, cross-sell, novas unidades e países)"], "bottleneck": "Gestão complexa de múltiplos canais (hotelaria, franquias SPA, ecommerce, farma) com equipe enxuta, dificultando padronização e captura de margem"}}'::jsonb, '{"realist": {"name": "Cenário Realista", "description": "PIB segue em torno de 2.20 %, serviços em 0.60 % e comércio em -0.30 %, com juros a 14.90% a.a. e inflação de 0.09% (12 meses). Crescimento moderado favorece wellness, mas encarece capital e insumos ligados ao R$ 5.36/USD. Santapele cresce seletivamente em SPAs e amenities, com disciplina de caixa e foco em mix de maior margem.", "probability": 60, "required_actions": ["Priorizar expansão de SPAs/franquias em poucos parceiros estratégicos, com modelo enxuto, payback claro e royalties atrelados a metas de ticket médio e ocupação", "Otimizar mix de canais: reforçar serviços de SPA (margem maior), manter D2C como vitrine de marca e selecionar poucos pontos farma âncora para Santopé", "Ajustar preços e tamanhos de embalagem para preservar margem diante de juros em 14.90% a.a. e câmbio a R$ 5.36/USD, sem diluir o posicionamento de eco-luxury", "Profissionalizar gestão de dados: unit economics por hotel, SPA e SKU, medindo CAC/LTV por canal para orientar decisão de expansão nacional e internacional"]}, "summary": "Com PIB em 2.20 %, juros de 14.90% a.a., serviços em 0.60 % e câmbio a R$ 5.36/USD, o ciclo favorece bem-estar mas com capital caro e custos pressionados. O risco central é escalar SPAs, franquias e novas linhas rápido demais. Disciplina de caixa, expansão seletiva B2B, fortalecimento do D2C e monitoramento dos indicadores macro são críticos para proteger a tese de eco-luxury.", "optimistic": {"name": "Cenário Otimista", "description": "Serviços mantêm 0.60 % ou melhor e turismo ganha tração com R$ 5.36/USD, favorecendo hotéis de luxo. PIB acelera além dos 2.20 % com inflação perto de 0.09% (12 meses). Santapele expande SPAs/franquias, amenities B2B no Brasil e exterior e fortalece D2C e Santopé, capturando share dos grandes grupos.", "probability": 20, "required_actions": ["Acelerar expansão de franquias de SPA em destinos turísticos e hubs de hotelaria de luxo, usando o câmbio a R$ 5.36/USD como argumento de atração", "Fechar contratos âncora de amenities com redes hoteleiras premium, com portfólio eco-luxury customizado e SLAs de serviço superiores à L''Occitane", "Escalar D2C e linha Santopé via ecommerce e canal farma premium, com programas de fidelidade e storytelling da origem Emiliano"]}, "pessimistic": {"name": "Cenário Pessimista", "description": "Taxa de juros mantém-se em 14.90% a.a. ou sobe, retraindo crédito e consumo premium. Comércio aprofunda queda além de -0.30 % e indústria segue em -0.40 %, com desemprego acima dos atuais 5.60 %. Câmbio se afasta de R$ 5.36/USD, encarecendo insumos. Hotéis adiam reformas de SPA e trocas de amenities; D2C desacelera.", "probability": 20, "required_actions": ["Proteger caixa: frear abertura de novas franquias de SPA, renegociar prazos com fornecedores e priorizar contratos B2B de maior recorrência e margem", "Reforçar ofertas para base instalada de hotéis e SPAs Emiliano, com programas de upgrade e cross-sell de linha SPA e Santopé, reduzindo dependência de novos clientes", "Lançar formatos mais acessíveis mantendo a curadoria eco-luxury (kits de viagem, tamanhos menores), focando canais digitais de menor custo fixo"]}, "mitigation_tactics": ["Construir esteira disciplinada de franquias de SPA, com critérios rígidos de seleção de hotéis, contratos flexíveis e modelos asset-light para reduzir risco em ciclos de juros de 14.90% a.a.", "Implementar gestão ativa de custos e risco cambial: revisar portfólio de insumos ligados ao R$ 5.36/USD, buscar fornecedores locais e travar parte da exposição quando possível", "Fortalecer o diferencial de eco-luxury e origem Emiliano por meio de branding, certificações ambientais e educação do consumidor, aumentando poder de preço em cenários voláteis", "Criar cockpit de indicadores (PIB 2.20 %, serviços 0.60 %, comércio -0.30 %, desemprego 5.60 %, juros 14.90% a.a.) para ajustar ritmo de CAPEX, expansão de franquias e estoque"], "early_warning_signals": ["Movimentos do Banco Central indicando manutenção prolongada ou elevação da taxa de juros acima dos atuais 14.90% a.a., encarecendo financiamento de expansão de SPAs", "Queda do volume de serviços abaixo dos atuais 0.60 % e aprofundamento da retração do comércio além de -0.30 %, sinalizando menor demanda por amenities e bem-estar premium", "Alta do desemprego a partir de 5.60 % e volatilidade do câmbio se afastando de R$ 5.36/USD, reduzindo turismo e pressionando custos de insumos e embalagens importadas"]}'::jsonb, '{"summary": "Santapele integra eco-luxo, ciência e dados para escalar receitas em hotéis, SPAs e D2C.", "customer": ["Ser marca referência eco-luxo em hotéis e SPAs de alto padrão", "Elevar NPS de hóspedes, franqueados e clientes finais D2C"], "financial": ["Aumentar receita recorrente D2C em eco-luxo e linha Santopé", "Elevar margem via mix premium: SPAs-franquia, hotéis e ecommerce"], "learning_growth": ["Desenvolver capacidades em ciência do bem-estar e podologia avançada", "Criar cultura data-driven com insights de hotelaria, SPAs e ecommerce"], "internal_processes": ["Padronizar operação de SPAs-franquia com protocolos guiados por dados", "Otimizar supply chain verde para amenities e linha premium de pés"]}'::jsonb, '{"score": "8.4/10", "summary": "A matriz considera retorno ajustado ao risco, intensidade de capital e complexidade regulatória num contexto de PIB em 2,20%, juros de 14,90% a.a., serviços em 0,60% e câmbio a R$ 5,36/USD. Dado o capital caro e o risco de escalar SPAs/franquias e novas linhas rápido demais, a estratégia ótima é usar o D2C como eixo central de crescimento asset-light, alavancando o prestígio Emiliano e o posicionamento eco-luxury para aumentar ticket, recorrência e margem. Em paralelo, a expansão B2B deve ser seletiva, com poucos hotéis de referência e franquias bem estruturadas, sob forte disciplina contratual e regulatória (parecer jurídico obrigatório). A linha Santopé deve ser desenvolvida e testada em ciclos curtos, com pilotos no ecommerce e em farmácias premium, antes de qualquer roll-out amplo. O conselho deve revisar a estratégia a cada trimestre, monitorando KPIs de receita, margem, CAC/LTV e NPS, e acionar revisão extraordinária diante de choques regulatórios, bloqueios de licenciamento, decisões judiciais que afetem o modelo de franquia/hotelaria ou falhas de compliance (LGPD/setorial). Próximos passos: detalhar planos operacionais das três recomendações, contratar suporte jurídico para B2B/franquias e regulação de produtos, e implantar um painel de indicadores para acompanhamento contínuo pelo conselho.", "criteria": ["Retorno financeiro ajustado ao risco em 3-5 anos", "Intensidade de capital e impacto em caixa", "Complexidade operacional e regulatória"], "alternatives": ["Expansão seletiva B2B em hotelaria de luxo e SPAs franqueados", "Escalada do D2C digital e fortalecimento da marca eco-luxury", "Lançamento acelerado da linha Santopé e entrada em canal Farma"], "review_cycle": {"frequency": "Trimestral", "extraordinary_triggers": ["Mudança regulatória >10% custo", "Bloqueio de licenciamento", "Decisão judicial relevante", "Falha de compliance LGPD/setorial", "Entrada de competidor relevante"]}, "score_comparison": "+18% acima da segunda opção", "monitoring_metrics": ["Receita trimestral D2C e crescimento (% vs. trimestre anterior)", "CAC, LTV e payback por canal (D2C, B2B, Farma)", "Número de hotéis e SPAs parceiros ativos e churn de contratos", "Margem bruta consolidada e por linha (Amenities, SPA, Santopé)", "Participação do D2C na receita total (%)", "NPS e satisfação de hóspedes/SPAs e clientes D2C"], "recommended_option": "Escalada do D2C digital e fortalecimento da marca eco-luxury", "final_recommendation": "A melhor opção é escalar o D2C digital e fortalecer a marca eco-luxury, usando B2B seletivo e a linha Santopé em pilotos controlados, preservando caixa em cenário de juros altos e construindo base recorrente de clientes premium.", "priority_recommendations": [{"title": "Fortalecer D2C e comunidade de marca eco-luxury", "budget": "R$150-250k", "priority": 1, "timeline": "9-12 meses", "description": "Consolidar o ecommerce como eixo central de crescimento, aumentando ticket médio e recorrência via CRM, programas de fidelidade e storytelling da origem Emiliano/eco-luxury. Priorizar mix de amenities de hotelaria e linha SPA para uso em casa, com foco em margens e dados de cliente. Aproveitar cenário de juros altos para crescer de forma asset-light, testando pricing e bundles voltados a bem-estar.", "legal_feasibility": {"risk_level": "Médio", "mitigation_plan": "Revisar termos de uso, política de privacidade e política de trocas com advogado especializado em digital/consumidor; implementar governança de dados (LGPD) e treinamento básico do time; estruturar fluxo de atendimento a reclamações (Procon, Reclame Aqui) para reduzir risco de contencioso.", "requires_legal_opinion": false, "regulatory_dependencies": ["Adequação plena à LGPD e políticas de privacidade do ecommerce", "Conformidade com Código de Defesa do Consumidor e normas de publicidade de cosméticos"], "requires_statutory_change": false}}, {"title": "Expansão seletiva B2B em hotelaria de luxo e SPAs franqueados (modelo asset-light)", "budget": "R$80-120k", "priority": 2, "timeline": "6-9 meses", "description": "Ampliar presença em hotéis de luxo fora da base Emiliano, priorizando contratos com forte reputação e baixo CAPEX próprio. Estruturar modelo de franquias/gestão de SPAs com playbook claro (operações, marca, protocolos, venda de produtos) e critérios rígidos de seleção de franqueados. Iniciar com pilotos em poucos destinos estratégicos, evitando escala acelerada que pressione caixa em ambiente de juros de 14,90% a.a. e custos elevados.", "legal_feasibility": {"risk_level": "Alto", "mitigation_plan": "Obter parecer jurídico prévio em franchising, contratos de hotelaria e regulação sanitária; padronizar COF, contratos de franquia e de operação de SPA com cláusulas claras de responsabilidade civil, compliance e uso de marca; exigir que cada SPA/franquia comprove licenças sanitárias locais antes da abertura. Alternativa de menor risco: em mercados mais incertos, priorizar contratos de licenciamento de marca e fornecimento de protocolos/produtos, sem estrutura formal de franquia, reduzindo exposição jurídica e obrigações legais típicas do franchising.", "requires_legal_opinion": true, "regulatory_dependencies": ["Conformidade ANVISA para linhas profissionais e amenities", "Atendimento integral à Lei de Franquias (Lei 13.966/2019)", "Licenças e alvarás sanitários locais para operação de SPAs parceiros"], "requires_statutory_change": false}}, {"title": "Desenvolver e pilotar a linha Santopé como plataforma de cuidado premium para os pés", "budget": "R$40-60k", "priority": 3, "timeline": "3-6 meses", "description": "Transformar o Santopé em uma mini-plataforma de 4-5 SKUs focados em cuidado premium dos pés, iniciando por ajustes de formulação, validação com dermatologistas/podólogos e testes de posicionamento de preço. Fazer pilotos controlados no ecommerce próprio e em poucas farmácias premium em São Paulo, medindo aceitação, giro e elasticidade de preço antes de escalar o canal Farma nacionalmente.", "legal_feasibility": {"risk_level": "Médio", "mitigation_plan": "Garantir que as alegações de marketing da linha Santopé estejam alinhadas à categoria regulatória (cosmético vs. produto com apelo terapêutico); revisar rótulos, bulas e materiais promocionais com suporte jurídico/regulatório; iniciar com contratos-piloto de distribuição em farmácias selecionadas, com cláusulas claras de devolução e performance mínima.", "requires_legal_opinion": false, "regulatory_dependencies": ["Regularização/alteração de registros de novos SKUs junto à ANVISA, conforme categoria de cosmético", "Contratos de distribuição e exposição de produtos com redes de farmácia"], "requires_statutory_change": false}}]}'::jsonb, 'completed', NULL, 300600, true, true, true, 'AZ6VBWC9', '2025-12-04 12:02:39.501545+00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-04 11:57:10.892633+00'::timestamptz, '2025-12-04 13:10:10.801016+00'::timestamptz, '2025-12-04 12:02:11.23696+00'::timestamptz, NULL)
