INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('4cefbc5d-f382-485b-81bb-6b987af41736', '3fd14473-39ac-4f23-991d-6ba873fd5d4f', '83d23c8b-8eca-499e-80af-f46866f17248', NULL, '{"summary": "B2B regional sólido, pronto para acelerar via parcerias, ESG e digital, mas sensível a juros altos, demanda fraca e câmbio.", "threats": [{"source": "análise de mercado", "content": "Juros SELIC 14,90% encarecem crédito e travam investimentos em estoque e expansão", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Comércio -0,30% indica demanda fraca e maior disputa por preço entre distribuidores", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Concorrentes regionais fortes aumentam poder de barganha dos grandes compradores", "confidence": "Média"}, {"source": "análise de mercado", "content": "Câmbio USD/BRL a R$ 5.36 pressiona custo de insumos químicos importados", "confidence": "Média"}], "strengths": [{"source": "fato", "content": "Carteira B2B consolidada em higiene profissional no ABC Paulista", "confidence": "Alta"}, {"source": "análise de mercado", "content": "19 anos de operação contínua gerando credibilidade e relacionamentos", "confidence": "Média"}, {"source": "fato", "content": "Receita anual R$4–5 mi, permitindo escala mínima para parcerias maiores", "confidence": "Alta"}, {"source": "fato", "content": "Estrutura enxuta de 11–50 colaboradores favorece agilidade em decisões", "confidence": "Média"}], "weaknesses": [{"source": "fato", "content": "Dependência de crescimento orgânico lento limita ganho de escala B2B", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Baixa presença digital e redes sociais reduz geração de leads qualificados", "confidence": "Média"}, {"source": "estimativa", "content": "Processo comercial pouco digitalizado dificulta vendas fora da base atual", "confidence": "Média"}, {"source": "fato", "content": "Planejamento para parcerias ainda em análise, atrasando movimentos estratégicos", "confidence": "Alta"}], "opportunities": [{"source": "análise de mercado", "content": "Firmar parcerias estratégicas com grandes contas de serviços em alta (+0,60%)", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Criar linha e narrativa ESG em higiene verde para contratos B2B de maior valor", "confidence": "Média"}, {"source": "análise de mercado", "content": "Digitalizar prospecção B2B (inside sales, marketplace) para escalar além do ABC", "confidence": "Média"}, {"source": "análise de mercado", "content": "Usar dados abertos públicos para mapear licitações e contratos recorrentes", "confidence": "Alta"}]}'::jsonb, '{"legal": ["LGPD exige segurança de dados de clientes B2B; conformidade atual pode virar diferencial", "Lei 12.527/2011 e Dec. 8.777/2016 abrem dados de compras, mas exigem compliance em propostas", "Regras sanitárias rígidas para higienização profissional elevam barreiras a novos entrantes"], "social": ["Desemprego 5,60% reduz pool de mão de obra barata, pressionando salários em logística e limpeza", "Clientes B2B valorizam higiene profissional, favorecendo contratos recorrentes de maior ticket", "Pressão por bem-estar no trabalho reforça demanda por ambientes limpos em escritórios e indústrias"], "summary": "Juros altos e comércio fraco pressionam margens, mas serviços em alta, transparência pública e agenda ESG abrem espaço para crescer via contratos B2B maiores, produtos sustentáveis e uso de dados abertos em parcerias e novos canais.", "economic": ["SELIC 14,90% a.a. encarece capital de giro para estoques e limita crescimento inorgânico", "Comércio -0,30% sinaliza demanda fraca de parte da base B2B, exigindo diversificar segmentos", "Serviços +0,60% e PIB 2,20% indicam espaço para upsell em facilities e higienização terceirizada"], "political": ["Dados abertos (Dec. 8.777/2016) ampliam acesso a licitações de limpeza no setor público", "Lei 12.527/2011 exige transparência; empresas preparadas ganham vantagem em contratos públicos", "Agenda ESG em governos locais pode priorizar fornecedores com produtos de menor impacto ambiental"], "environmental": ["Tendência ESG pressiona migração para químicos menos agressivos e embalagens recicláveis", "Clientes corporativos podem exigir laudos ambientais, filtrando distribuidores despreparados", "Custo da construção +0,27% sugere novos prédios com padrões verdes e mais demanda de limpeza"], "technological": ["Maturidade digital média e ausência em redes sociais limitam geração de leads fora do ABC", "Dados abertos facilitam uso de inteligência para mapear editais e compras públicas de limpeza", "Automação de pedidos B2B e integrações ERP podem reduzir custos e fidelizar grandes contas"]}'::jsonb, '{"summary": "Setor com rivalidade e poder de compra elevados, pressionado por juros de 14,90% e comércio -0,30%, mas com espaço em serviços (+0,60%). Crescimento acima do orgânico virá de parcerias estratégicas, digitalização comercial e uso intensivo de dados.", "buyer_power": "Clientes B2B pressionam preço em cenário de comércio -0,30%, juros de 14,90% e desemprego de 5,60%, alongando prazos e reduzindo estoque; Cleaning Solutions precisa agregar serviço e consultoria para escapar de leilão puramente por preço.", "supplier_power": "Importados atrelados a USD R$ 5,36 e crédito caro (juros 14,90% a.a.) fortalecem fornecedores, mas baixa inflação (0,09% a.a.) e diversidade de indústrias químicas limitam repasse, gerando poder de barganha médio sobre a empresa.", "disruption_ai_data": "Digitalização B2B e IA em compras, roteirização e precificação tendem a concentrar demanda em players data-driven; com maturidade digital média, a Cleaning Solutions deve investir em ERP integrado, e-commerce e analytics para preservar competitividade.", "threat_substitutes": "Substitutos avançam via fabricantes vendendo direto, atacarejos e marketplaces B2B, além de empresas de facilities que entregam limpeza como serviço; com serviços +0,60%, há risco de migração de gasto de compra de produto para contratos terceirizados.", "competitive_rivalry": "Rivalidade alta no atacado regional de higiene, com vários players no ABC e demanda fraca no comércio (-0,30%) apesar do PIB +2,20%; exige diferenciação via serviço técnico, rapidez logística e contratos B2B de longo prazo.", "threat_new_entrants": "Barreiras moderadas: capital de giro onerado por juros de 14,90% e estoques indexados ao USD R$ 5,36, porém baixa complexidade operacional e legislação estável permitem entrada de distribuidores locais enxutos e e-commerces B2B segmentados.", "buyer_power_intensity": "Alta", "overall_attractiveness": "Média", "strategic_implications": ["Construir portfólio diferenciado com bundles produto+serviço, treinamento e SLAs para reduzir sensibilidade a preço e fidelizar contas B2B chave.", "Fechar parcerias regionais com 2–3 fabricantes e ao menos 1 empresa de facilities para ofertas conjuntas e entrada em contratos maiores no ABC.", "Implantar e-commerce B2B e CRM integrado ao ERP em até 24 meses, digitalizando vendas, crédito e relacionamento para ganhar escala e eficiência.", "Criar célula de inteligência de dados para gestão de preços, estoques e risco de crédito, usando analytics e IA para proteger margem em ambiente competitivo."], "supplier_power_intensity": "Média", "disruption_ai_data_intensity": "Alta", "threat_substitutes_intensity": "Média", "competitive_rivalry_intensity": "Alta", "power_partnerships_ecosystems": "Parcerias com fabricantes, facilities e plataformas digitais podem acelerar crescimento além do orgânico, capturando alta em serviços (+0,60%) e melhorando condições de compra, mix e capilaridade no ABC sem elevar muito o risco financeiro.", "threat_new_entrants_intensity": "Média", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": ""}'::jsonb, '{"roadmap": ["Curto Prazo (3-6 meses): Implementar CRM, ativar LinkedIn B2B, pilotar modelo de assinatura com 3-5 clientes atuais", "Médio Prazo (6-12 meses): Fechar 2 parcerias estratégicas (facilities/fabricantes), expandir assinaturas para 15-20% da base, iniciar prospecção digital estruturada", "Longo Prazo (12+ meses): Expandir para região metropolitana de SP, consolidar plataforma de soluções integradas, atingir 30% de receita recorrente"], "key_findings": ["Modelo de assinatura por ambiente pode elevar LTV em 40-60% e reduzir ciclo de vendas com contratos plurianuais", "Parcerias com facilities e fabricantes aceleram entrada em contas maiores sem investimento em estrutura própria", "Digitalização comercial (CRM + prospecção ativa) é pré-requisito para escalar além do ABC Paulista"], "main_findings": ["FORÇA: 19 anos de operação, relacionamento B2B consolidado e expertise técnica em higienização profissional", "FRAQUEZA: Crescimento limitado ao orgânico, ausência em redes sociais e dependência de modelo tradicional de distribuição", "OPORTUNIDADE: Demanda ESG crescente, serviços em alta e espaço para contratos recorrentes com grandes contas B2B", "AMEAÇA: Juros de 14,90% encarecem expansão, comércio em queda (-0,30%) e alta rivalidade com poder de barganha do comprador"], "important_notes": ["Selic a 14,90% inviabiliza alavancagem: crescimento deve ser autofinanciado ou via parcerias estratégicas", "Ausência digital (LinkedIn, Instagram) limita prospecção e visibilidade para novos negócios", "Discrepância entre capital social (R$80k) e faturamento (R$4-5M) pode dificultar acesso a crédito formal"], "central_challenge": "Crescer além do ritmo orgânico atual (R$4-5M) em mercado pressionado por juros altos e demanda fraca, sem capital externo, exigindo parcerias estratégicas e novos modelos de receita.", "executive_summary": "Cleaning Solutions, com 19 anos de mercado e base B2B sólida no ABC Paulista, enfrenta teto de crescimento orgânico. A saída: evoluir de distribuidora para plataforma de soluções em higiene, combinando contratos recorrentes, consultoria técnica e parcerias com facilities. Juros de 14,90% exigem disciplina de caixa; serviços em alta (+0,60%) e agenda ESG abrem janela de oportunidade para diferenciação e expansão regional.", "strategic_priorities": ["Lançar modelo de contrato recorrente (assinatura) para clientes-âncora até Q2/2025", "Estruturar 2-3 parcerias estratégicas com facilities ou fabricantes até Q3/2025", "Implementar CRM e presença digital ativa (LinkedIn B2B) até Q1/2025"], "consistency_validation": {"flags": ["Equipe de 11-50 pode exigir contratação pontual para CRM/digital (custo estimado: R$8-15k/mês)", "Parcerias dependem de negociação comercial - timeline pode estender 2-3 meses além do previsto"], "legal_alignment": true, "capacity_alignment": true, "financial_alignment": true, "overall_realism_score": 7}, "overall_recommendation": "Priorizar conversão de clientes atuais para contratos recorrentes e fechar 2 parcerias estratégicas em 2025. Crescimento agressivo só após validar modelo de assinatura e estabilizar fluxo de caixa."}'::jsonb, '{"sam": "R$ 240M - 540M", "som": "R$ 20M - 50M", "tam": "R$ 12B - 18B", "cagr": "+4% a.a. (baseado em: PIB 12m 3,20% e serviços 0,60% - Macro-Contexto)", "summary": "Mercado nacional grande (R$ 12-18B), com nicho regional ABC de R$ 240-540M e potencial capturável de R$ 20-50M/ano.", "assumptions": ["TAM Brasil higiene/limpeza B2B ~R$ 12-18B (ABIPLA/IBGE e dados 2023 do setor)", "SAM = TAM x 2-3% (participação estimada do ABC Paulista no mercado Brasil)", "SOM realista = 8-10% do SAM, alinhado à receita-alvo PME (R$ 20-50M/ano)"], "som_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 19M - 54M", "market_share": "8-10%"}, "optimistic": {"probability": 20, "value_range": "R$ 29M - 97M", "market_share": "12-18%"}, "conservative": {"probability": 30, "value_range": "R$ 7M - 22M", "market_share": "3-4%"}}, "tam_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 14B - 16B"}, "optimistic": {"probability": 20, "value_range": "R$ 16B - 18B"}, "conservative": {"probability": 30, "value_range": "R$ 12B - 14B"}}, "confidence_level": 60, "calculation_notes": "TAM por benchmark nacional higiene/limpeza B2B; SAM por peso ABC; SOM por % de penetração para PME estabelecida.", "data_sources_used": {"direct_data": ["Faturamento anual informado: R$ 4-5M (Cleaning Solutions)", "Porte 11-50 colaboradores, foco B2B, localização Santo André - SP", "Indicadores macroeconômicos de comércio/serviços (Macro-Contexto)"], "proxy_calculations": ["SAM = TAM Brasil x 2-3% para refletir ABC Paulista", "SOM calculado como 3-18% do SAM em três cenários de participação", "Validação por comparação com faixa típica de receita PME (R$ 5-50M/ano)"], "benchmark_extrapolations": ["Tamanho do mercado brasileiro de higiene/limpeza B2B estimado em R$ 12-18B/ano com base em dados setoriais 2023", "Ajuste regional considerando densidade industrial/comercial do ABC Paulista acima da média nacional"]}, "estimation_method": "benchmark_setorial", "baseline_recommendation": "conservative"}'::jsonb, '{"summary": "Frente a concorrentes regionais e nacionais, a Cleaning Solutions é forte no nicho B2B local, mas precisa ganhar escala via digital, parcerias e expansão geográfica.", "best_practices": ["Posicionamento claro em B2B de higiene profissional, com foco em demanda recorrente e maior previsibilidade.", "Relacionamento regional forte no ABC, com logística próxima ao cliente e atendimento personalizado.", "Portfólio amplo de higiene e limpeza, viabilizando venda cruzada e aumento de share em clientes atuais."], "performance_gaps": ["Presença digital limitada vs concorrentes com e-commerce, mídias sociais ativas e geração constante de leads.", "Expansão geográfica tímida, mantendo nicho no ABC enquanto rivais atuam em múltiplas regiões e canais.", "Poucas parcerias com fabricantes e facilities, limitando descontos, mix e acesso a grandes contas."], "competitors_analyzed": ["Clean Service Castro Limpeza Máxima Ltda", "Clean Company Prestação de Serviços de Limpeza Ltda", "The Best Cleaner Ltda"]}'::jsonb, '{"raise": ["Consultoria em higiene com foco em resultado do cliente", "Nível de serviço logístico e SLAs por segmento B2B", "Uso de dados de consumo para otimizar compras do cliente"], "create": ["Plataforma digital B2B de gestão total de higiene", "Modelos de assinatura por ambiente e nível de serviço", "Ecossistema de parcerias com facilities e fabricantes"], "reduce": ["Portfólio amplo sem curadoria de performance", "Dependência de crédito longo e consignação", "Descontos lineares para todos os clientes"], "summary": "A Cleaning Solutions sai da disputa por preço na distribuição e cria um oceano azul como plataforma de soluções de higiene B2B: combina consultoria técnica, assinaturas por ambiente, dados de consumo e um ecossistema de parceiros (facilities e fabricantes), elevando serviço e resultado entregue enquanto reduz estoque, crédito longo e descontos generalizados.", "eliminate": ["Guerra de preços em itens comoditizados", "Venda focada apenas em produto e marca", "Visitas comerciais só presenciais e reativas"], "new_value_curve": "De distribuidora de produtos a plataforma de soluções de higiene B2B por assinatura e performance."}'::jsonb, '{"summary": "Acelerar aquisição B2B com prospecção digital, parcerias e ESG, e crescer LTV via contratos recorrentes, upsell e expansão regional.", "leap_loop": {"name": "LEAP Loop", "type": "acquisition", "steps": ["Land: Prospecção digital B2B + parcerias com grandes facilities e licitações no ABC e regiões adjacentes", "Engage: Conteúdo ESG e cases de higienização profissional em landing pages, e-mail e visitas consultivas", "Activate: Roteiro de inside sales com proposta padrão por segmento e piloto rápido com 10 contas âncora", "Propagate: Programa de indicação entre clientes B2B com desconto progressivo por contrato fechado indicado"], "metrics": ["CAC digital", "Taxa de conversão lead→cliente", "Coeficiente viral (indicações)"], "bottleneck": "Baixa presença digital e processo comercial pouco digitalizado limitam geração e nutrição de novos leads B2B"}, "scale_loop": {"name": "SCALE Loop", "type": "monetization", "steps": ["Satisfy: Pacotes de fornecimento + treinamento em higiene profissional e linha verde alinhados a metas ESG do cliente", "Convert: Contratos anuais com desconto por volume e mix produto-serviço para elevar ticket médio B2B", "Loop Back: Reposição automática (assinatura) com previsão de consumo e check-ins trimestrais de performance", "Expand: Upsell de linha premium/ESG e cross-sell de serviços em múltiplas unidades e filiais do mesmo cliente"], "metrics": ["LTV por cliente B2B", "Taxa de recompra/renovação de contratos", "Receita de expansão (upsell + cross-sell)"], "bottleneck": "Dependência de crescimento orgânico e ausência de esteiras estruturadas de upsell reduzem expansão na base atual"}}'::jsonb, '{"realist": {"name": "Cenário Realista", "description": "Economia cresce perto dos 2,20%, com serviços em torno de 0,60% e comércio estagnado próximo a -0,30%. SELIC permanece elevada em 14,90% a.a., câmbio perto de R$ 5,36 pressiona insumos. Cleaning Solutions cresce acima do orgânico via nichos B2B do ABC, contratos recorrentes e ofertas ESG, exigindo disciplina comercial e financeira.", "probability": 60, "required_actions": ["Priorizar segmentos B2B menos sensíveis ao ciclo, como saúde, alimentos e condomínios corporativos no ABC.", "Estruturar ofertas de assinatura de insumos com previsão de consumo, SLA de entrega e reajuste indexado.", "Renegociar prazos com fornecedores e clientes para reduzir a necessidade de capital de giro caro.", "Intensificar uso de dados abertos de compras públicas para mapear e disputar licitações aderentes."]}, "summary": "Cleaning Solutions opera com juros de 14,90% a.a., câmbio em R$ 5,36/USD e comércio em -0,30%, mas com serviços em alta (0,60%) e demanda ESG crescente. A preparação exige disciplina de caixa, foco em nichos B2B resilientes, uso de dados abertos e parcerias para crescer além do orgânico, reagindo rápido aos sinais do macrocontexto.", "optimistic": {"name": "Cenário Otimista", "description": "Serviços avançam bem acima dos atuais 0,60%, comércio sai de -0,30% para terreno positivo e o PIB supera 2,20%. A SELIC, hoje em 14,90% a.a., inicia ciclo de queda, barateando crédito. Cleaning Solutions fecha parcerias B2B nacionais, lança linha sustentável e usa dados abertos para grandes contas públicas e privadas.", "probability": 20, "required_actions": ["Escalar parcerias com empresas de facilities e limpeza terceirizada para contratos B2B nacionais de fornecimento.", "Criar portfólio ESG de higiene verde direcionado a grandes contas corporativas e órgãos públicos.", "Investir em time de vendas consultivas focado em contratos de longo prazo e tickets médios maiores."]}, "pessimistic": {"name": "Cenário Pessimista", "description": "PIB frustra e fica abaixo dos 2,20%, comércio aprofunda queda além de -0,30% e serviços desaceleram dos 0,60%. SELIC segue em 14,90% a.a. por mais tempo, crédito encarece e câmbio ultrapassa R$ 5,36, elevando custos. Empresas cortam terceirização e higienização. Cleaning Solutions enfrenta pressão forte em preço e inadimplência.", "probability": 20, "required_actions": ["Focar em clientes com baixo risco de crédito e contratos essenciais, mesmo com margens menores.", "Reduzir estoques de itens de baixa saída e priorizar linhas com giro rápido e menor exposição cambial.", "Criar planos de contingência de caixa, cortando despesas não críticas e adiando investimentos de expansão."]}, "mitigation_tactics": ["Implementar planejamento de cenários trimestral com testes de estresse de margem, câmbio e juros.", "Diversificar base de clientes além de Santo André/ABC para outros polos industriais e de serviços do estado.", "Negociar linhas de crédito pré-aprovadas antes de precisar, mesmo com SELIC em 14,90% a.a.", "Adotar política de compras combinando contratos de longo prazo e cotações spot para reduzir impacto de R$ 5,36/USD."], "early_warning_signals": ["Queda adicional do volume de comércio abaixo dos atuais -0,30% por vários meses consecutivos.", "Manutenção da SELIC em 14,90% a.a. com inflação acima de 0,09% por mais de dois trimestres.", "Aceleração da taxa de desemprego além dos 5,60%, afetando demanda de clientes B2B locais."]}'::jsonb, '{"summary": "BSC migra a Cleaning Solutions da disputa por preço para plataforma recorrente de soluções B2B, elevando valor entregue, margens e escala com dados de consumo e parceiros.", "customer": ["Aumentar NPS para 75 focando consultoria técnica e resultado de higienização", "Elevar share de carteira em clientes chave com soluções por ambiente"], "financial": ["Elevar margem bruta média em 5 p.p. migrando de desconto a valor agregado", "Alcançar 40% da receita em modelo recorrente de assinaturas B2B"], "learning_growth": ["Formar squad de soluções B2B com 100% da equipe comercial treinada em consultoria", "Implantar cultura data-driven com uso mensal de dashboards de consumo por cliente"], "internal_processes": ["Lançar plataforma de assinaturas por ambiente com painel de consumo em 12 meses", "Reduzir giro médio de estoque em 20% via previsões e contratos recorrentes"]}'::jsonb, '{"score": "", "summary": "", "criteria": null, "alternatives": null, "review_cycle": {"frequency": "", "extraordinary_triggers": null}, "score_comparison": "", "monitoring_metrics": null, "recommended_option": "", "final_recommendation": "", "priority_recommendations": null}'::jsonb, 'completed', NULL, 334944, false, false, false, 'MQZ66GL5', '2025-12-02 17:09:01.866435+00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-02 17:00:26.306871+00'::timestamptz, '2025-12-02 17:09:01.866435+00'::timestamptz, '2025-12-02 17:06:00.98816+00'::timestamptz, NULL)
