INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('518794ed-5388-41c3-9d9f-c165224c242e', 'd9fc9094-605b-4ace-8749-75cc45d3f16c', '5d4d0fef-fc56-4835-9985-52a192b2dd96', NULL, '{"summary": "Santapele deve usar os R$2 mi para reforçar marca premium, digital e B2B, ganhando escala eficiente num mercado de wellness em alta, porém competitivo e sensível a juros altos.", "threats": [{"source": "fato", "content": "SELIC 14.90% a.a. encarece capital e pressiona retorno mínimo exigido", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Alta rivalidade com Natura, Boticário, Granado e L''Occitane reduz margem", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Private labels e importados asiáticos pressionam preço e percepção de valor", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Regulação ANVISA mais rígida e logística reversa elevam custos operacionais", "confidence": "Média"}], "strengths": [{"source": "análise de mercado", "content": "Marca wellness premium brasileira já posicionada em nicho de alto valor", "confidence": "Média"}, {"source": "fato", "content": "Histórico bootstrapped indica disciplina financeira e eficiência de capital", "confidence": "Alta"}, {"source": "fato", "content": "Modelo híbrido B2B/B2C diversifica receitas e reduz risco de demanda", "confidence": "Alta"}, {"source": "fato", "content": "Base em São Paulo facilita acesso a talentos, parceiros e canais premium", "confidence": "Alta"}], "weaknesses": [{"source": "fato", "content": "Falta plano detalhado para alocar R$2 mi e metas claras pós-investimento", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Escala limitada frente a grandes players reduz poder de negociação e mídia", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Capacidades digitais medianas travam aquisição eficiente de clientes", "confidence": "Média"}, {"source": "análise de mercado", "content": "Dependência de capital externo aumenta vulnerabilidade a atrasos na rodada", "confidence": "Média"}], "opportunities": [{"source": "análise de mercado", "content": "Crescimento HPPC 7-9% favorece expansão em wellness premium bem posicionado", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Parcerias B2B com hotéis e spas elevam ticket médio e previsibilidade de receita", "confidence": "Média"}, {"source": "análise de mercado", "content": "Investir em e-commerce, CRM e conteúdo otimiza CAC e recorrência B2C", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Posicionamento sustentável pode capturar nichos premium dispostos a pagar mais", "confidence": "Média"}]}'::jsonb, '{"legal": ["RDC ANVISA sobre alérgenos pode exigir revisão de fórmulas e rótulos, impactando portfólio atual.", "Regras futuras para uso de \"Natural\" e \"Orgânico\" podem restringir claims e elevar custo jurídico.", "Exigências BPF e ISO 22716 elevam barreira a terceiristas; seleção rigorosa de parceiros é crítica."], "social": ["Consumidor seletivo busca custo-benefício ou experiência premium; risco de downgrade no B2C.", "Tendência Clean Beauty e bem-estar favorece a marca, mas exige provas reais de sustentabilidade.", "Alta renda e hotelaria/spas de luxo tendem a manter demanda, porém nicho é restrito e exigente."], "summary": "Juros de 14.90% a.a., câmbio R$ 5.35/USD e consumo seletivo exigem aplicar os R$ 2 mi em eficiência digital, mix premium enxuto e robustez regulatória, alavancando tendências de wellness e sustentabilidade sem comprometer o caixa.", "economic": ["SELIC 14.90% a.a. com IPCA 0.09% (12 meses) exige plano de R$ 2 mi focado em margem e eficiência.", "Câmbio em R$ 5.35/USD eleva custo de insumos importados, embalagens e fragrâncias diferenciadas.", "PIB 12m em 3.20 % e comércio -0.30 % indicam consumo seletivo; mix deve priorizar tíquete alto."], "political": ["Reforma Tributária no consumo pode mudar carga sobre varejo wellness; exige simulações de cenários.", "Foco fiscal do governo pode elevar tributos setoriais, comprimindo margens em cosméticos premium.", "Novas diretrizes ANVISA e saúde pública podem elevar exigências de segurança e testes dos produtos."], "environmental": ["Lei de Logística Reversa pressiona gestão de embalagens; chance de diferenciar com refil e coleta.", "Alta do petróleo encarece plástico e frete, estimulando embalagens menores e materiais sustentáveis.", "Volatilidade climática em óleos essenciais ameaça oferta; contratos locais reduzem essa exposição."], "technological": ["Adoção média-alta de e-commerce pede UX superior e omnichannel para competir com DNVBs de beleza.", "Personalização via IA abre espaço para kits sob medida, mas exige dados estruturados e CRM robusto.", "Maturidade digital 6/10 indica base, porém lacunas em automação e testes A/B podem travar escala."]}'::jsonb, '{"summary": "Wellness premium em HPPC é atraente, com crescimento de 7-9% e baixa inflação (IPCA 0.09%), mas alta rivalidade, substitutos e SELIC 14.90% a.a. exigem uso cirúrgico dos R$ 2 milhões em marca, parcerias B2B e capacidades digitais e operacionais.", "buyer_power": "Alto poder do comprador: consumidor seletivo e B2B concentrado em redes hoteleiras negociam preço e prazo. Com IPCA 0.09% (12 meses) e desemprego 5.60 %, valorizam custo-benefício e experiência premium claramente justificável.", "supplier_power": "Poder de fornecedor médio: petróleo e diesel caros elevam custos de embalagens e frete; óleos essenciais sofrem volatilidade. Cadeia estável, porém Santapele precisa contratos longos e diversificar insumos para proteger margem.", "disruption_ai_data": "IA/dados em alta: personalização via IA e CRM avançado tornam-se padrão em HPPC. DNVBs data-driven otimizam CAC e LTV; Santapele precisa investir em analytics, testes A/B e automação para competir em alcance, conversão e retenção.", "threat_substitutes": "Substitutos em alta: private labels de grandes varejistas e asiáticos baratos ganham apelo. Com SELIC 14.90% a.a. e consumo pressionado, parte do público migra para opções mais baratas, forçando proposta de valor bem-estar superior.", "competitive_rivalry": "Alta rivalidade: HPPC cresce 7-9%, mas comércio -0.30% e concentração alta em Natura/Granado. DNVBs ampliam share via influência, exigindo da Santapele forte diferenciação wellness e foco em nichos B2B hotelaria/spas.", "threat_new_entrants": "Ameaça média: barreiras ANVISA/BPF e capital de marca filtram players, mas tecnologia média-alta e câmbio R$ 5.35/USD facilitam DNVBs digitais e importados, exigindo da Santapele narrativa robusta de brasilidade e wellness.", "buyer_power_intensity": "Alta", "overall_attractiveness": "Média", "strategic_implications": ["Alocar parte dos R$ 2 milhões em fortalecimento de marca e alcance digital (RACE: Reach), com conteúdo wellness e brasilidade para defender preço em cenário de alta rivalidade e substitutos.", "Estruturar programa robusto de parcerias B2B com hotéis, spas e marketplaces premium (RACE: Reach/Convert), garantindo receitas recorrentes e maior poder de negociação com fornecedores.", "Investir em CRM, dados e IA para personalização, automação e fidelização (RACE: Act/Engage), elevando LTV e reduzindo CAC frente a DNVBs data-driven em um ambiente de juros de 14.90% a.a.", "Rever cadeia de suprimentos e contratos logísticos para mitigar impacto de petróleo/diesel e volatilidade de óleos essenciais, protegendo margem e caixa enquanto escala com capital limitado."], "supplier_power_intensity": "Média", "disruption_ai_data_intensity": "Alta", "threat_substitutes_intensity": "Alta", "competitive_rivalry_intensity": "Alta", "power_partnerships_ecosystems": "Ecossistemas fortes: omnichannel e M&A no setor criam espaço para parcerias com hotéis, spas, marketplaces e grandes grupos. Santapele pode usar acordos B2B e white label para escalar com baixo CAPEX e ampliar reconhecimento.", "threat_new_entrants_intensity": "Média", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": "Em 90 dias, Santapele organiza governança, base regulatória e CRM para iniciar pilotos omnichannel e sustentar a tese de captação dos R$2 mi.", "plan_90_days": [{"focus": "Fundação", "month": "Mês 1", "objective": "Organizar governança, dados e tese de investimento dos R$2 mi", "investment": "R$ 15-25 mil", "key_results": ["Finalizar deck de investimento com 3 cenários de alocação dos R$2 mi", "Implantar DRE e fluxo de caixa mensal separados para B2B e B2C", "Definir portfólio core e lista de até 5 SKUs a descontinuar"], "aligned_recommendation": "Preparar governança, instrumentos societários e métricas para a próxima rodada de captação"}, {"focus": "Crescimento", "month": "Mês 2", "objective": "Consolidar base produtiva, regulatória e mix premium enxuto", "investment": "R$ 20-40 mil", "key_results": ["Revisar 100% dos rótulos e fórmulas do portfólio core com consultor ANVISA", "Negociar 2 contratos de suprimento com preços e prazos fixos", "Selecionar e contratar ferramenta de CRM integrada ao e-commerce"], "aligned_recommendation": "Fortalecer base produtiva, regulatória e mix premium enxuto"}, {"focus": "Consolidação", "month": "Mês 3", "objective": "Desenhar pilotos da máquina de crescimento omnichannel B2B2C", "investment": "R$ 25-45 mil", "key_results": ["Mapear jornada do cliente em e-commerce, hotelaria e spas em 3 fluxos", "Configurar CRM com 3 fluxos: boas-vindas, pós-compra e reativação", "Documentar playbook B2B com metas e roteiro para 3 tipos de hotéis"], "aligned_recommendation": "Construir máquina de crescimento omnichannel e dados próprios (core do plano de R$ 2M)"}], "success_metrics": ["Plano de investimento dos R$2 mi estruturado e validado com 1 advisor externo", "Riscos regulatórios e portfólio core priorizados com plano de ação definido", "CRM básico e playbook B2B prontos para iniciar pilotos omnichannel no mês 4"], "execution_phases": {"scale": {"focus": "Expansão controlada", "duration": "Meses 7-12", "objectives": ["Escalar canais validados e preparar próxima rodada de captação", "Aumentar previsibilidade de receita com contratos B2B e recorrência"], "key_results": ["Fechar 10-15 contratos B2B ativos com hotéis/spas com recorrência mínima", "Alcançar 30-40% da receita via canais recorrentes (assinaturas e B2B)"], "prerequisites": ["Validação bem-sucedida dos pilotos", "Métricas mínimas de retenção e margem atingidas"], "investment_range": "R$ 1,4-1,6 mi"}, "foundation": {"focus": "Estruturação", "duration": "Meses 1-3", "objectives": ["Organizar governança, dados financeiros e tese de investimento de R$2 mi", "Preparar base produtiva, regulatória e de dados para pilotos omnichannel"], "key_results": ["Data room jurídico-financeiro mínimo concluído e atualizado", "CRM implementado com base de clientes unificada e tags B2B/B2C"], "investment_range": "R$ 60-110 mil", "capacity_requirements": {"team": "4-6 pessoas", "dependencies": ["Contratação de escritório jurídico especializado", "Escolha e contratação de ferramenta de CRM integrada ao e-commerce"], "skills_needed": ["Finanças e controladoria", "Marketing digital e CRM", "Jurídico regulatório ANVISA/LGPD (terceirizado)", "Comercial B2B hotelaria/spas"]}}, "validation": {"focus": "Pilotos", "duration": "Meses 4-6", "objectives": ["Testar máquina omnichannel em pilotos controlados B2C e B2B2C", "Validar proposta de valor do mix premium enxuto com poucos parceiros"], "key_results": ["Lançar piloto de assinatura B2C com pelo menos 50 clientes teste", "Rodar piloto B2B com 3 hotéis/spas medindo ticket e recompra"], "prerequisites": ["Fase 1 concluída", "Aprovações jurídicas e regulatórias críticas obtidas"], "investment_range": "R$ 300-500 mil"}}, "total_investment": "R$ 60-110 mil (estimado para os 90 dias)", "capacity_assessment": {"blockers": ["Falta plano detalhado para alocar R$2 mi e metas claras pós-investimento", "Dependência de pareceres jurídicos para LGPD, ANVISA e estrutura societária"], "team_readiness": "Média", "budget_adequacy": "Suficiente", "stakeholder_alignment": "Parcial"}}'::jsonb, '{"roadmap": ["Curto Prazo (3-6 meses): Governança e compliance ANVISA, implementação de CRM, contratação de head comercial B2B e head de growth digital. Investimento: R$ 400 mil.", "Médio Prazo (6-12 meses): Escalar aquisição digital (CAC < R$ 80), lançar programa de assinaturas, fechar 10 contratos B2B piloto. Investimento: R$ 900 mil.", "Longo Prazo (12-18 meses): Consolidar operação omnichannel, atingir R$ 350 mil MRR, preparar data room e iniciar roadshow para Series A de R$ 8-10 mi. Investimento: R$ 700 mil + reserva."], "key_findings": ["Modelo B2B2C via hotelaria/spas oferece CAC 60% menor que D2C puro e gera recorrência previsível com contratos de 12-24 meses.", "LTV atual estimado em 3-4x CAC; com CRM de recorrência (assinaturas), projeção sobe para 6-8x, viabilizando Series A.", "Cenário base projeta receita de R$ 4-5 mi em 24 meses; cenário otimista R$ 6-7 mi com execução B2B acelerada."], "main_findings": ["FORÇA: Marca consolidada em wellness premium com 12 anos de operação bootstrapped, demonstrando eficiência de capital e resiliência operacional.", "FRAQUEZA: Escala limitada (1-10 funcionários) e dependência de capital externo para competir com players como Granado e Natura em canais estratégicos.", "OPORTUNIDADE: Mercado HPPC crescendo 7-9% a.a. com tendência forte de clean beauty e wellness; canal B2B (hotelaria/spas) subexplorado por concorrentes de nicho.", "AMEAÇA: Juros de 14,90% a.a. encarecem capital, marcas próprias de varejistas e importados asiáticos pressionam margens no segmento premium."], "important_notes": ["CRÍTICO: Com SELIC a 14,90%, cada R$ 1 investido precisa gerar ROI > 20% a.a. para justificar uso vs. aplicação financeira.", "ALERTA: Equipe de 1-10 pessoas exigirá contratações estratégicas (mín. 3-4 posições-chave) para executar plano de expansão.", "REGULATÓRIO: Novas normas ANVISA sobre rotulagem e termos ''natural/orgânico'' exigem compliance imediato antes de escalar."], "central_challenge": "Definir alocação estratégica de R$ 2 milhões captados para escalar operação B2B2C de wellness premium, maximizando ROI em ambiente de juros altos (14,90% a.a.) e preparando métricas para próxima rodada.", "executive_summary": "Santapele deve alocar os R$ 2 mi em três pilares: 40% em máquina digital de aquisição e CRM de recorrência, 35% em expansão B2B (hotelaria/spas) e 25% em capital de giro e blindagem regulatória. Com SELIC a 14,90%, priorizar eficiência sobre crescimento agressivo. Meta: dobrar receita em 18 meses e atingir unit economics que sustentem Series A de R$ 8-10 mi.", "strategic_priorities": ["Implementar CRM e programa de assinaturas para elevar LTV em 80% nos próximos 12 meses.", "Fechar 15-20 contratos B2B com redes hoteleiras/spas premium até Q4 2025.", "Estruturar governança e métricas (MRR, CAC, LTV, churn) para pitch de Series A em 18 meses."], "consistency_validation": {"flags": ["CAPACIDADE: Equipe atual de 1-10 pessoas é insuficiente para executar plano completo; orçar R$ 300-400 mil para 4 contratações críticas nos primeiros 6 meses.", "CONSERVADORISMO: Cenário base assume execução de 70% do plano; recomenda-se buffer de 20% no timeline para imprevistos operacionais."], "legal_alignment": true, "capacity_alignment": false, "financial_alignment": true, "overall_realism_score": 7}, "overall_recommendation": "Aprovar captação de R$ 2 mi com alocação disciplinada: priorizar unit economics e recorrência sobre crescimento de vaidade. Manter 15% como reserva estratégica dado cenário macroeconômico volátil. Próxima rodada viável em 18-24 meses se LTV/CAC > 5x e MRR > R$ 300 mil."}'::jsonb, '{"sam": "R$ 800M - 1.5B", "som": "R$ 8M - 80M", "tam": "R$ 120B - 160B", "cagr": "+8% a.a. (baseado em: macro_context.industry_trends HPPC 7-9%)", "summary": "Mercado de wellness/cosméticos é amplo; com 2-5% do nicho, Santapele pode escalar de R$2M para ~R$30-40M/ano em 5-7 anos.", "assumptions": ["TAM HPPC Brasil ~R$120-160B/ano (ABIHPEC+benchmark varejo 1,5-2T)", "SAM = 0,6-0,9% do TAM (wellness premium+hotelaria SP/Brasil)", "SOM 2-5% do SAM em 5-7 anos (startup nicho B2B/B2C wellness)"], "som_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 30M - 40M", "market_share": "2-5% do SAM"}, "optimistic": {"probability": 20, "value_range": "R$ 75M - 80M", "market_share": "5-10% do SAM"}, "conservative": {"probability": 30, "value_range": "R$ 8M - 16M", "market_share": "0,5-2% do SAM"}}, "tam_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 120B - 160B"}, "optimistic": {"probability": 20, "value_range": "R$ 150B - 200B"}, "conservative": {"probability": 30, "value_range": "R$ 100B - 130B"}}, "confidence_level": 70, "calculation_notes": "TAM via tamanho do mercado HPPC Brasil; SAM como 0,6-0,9% do TAM; SOM como 0,5-10% do SAM, ajustado à realidade de PME de nicho.", "data_sources_used": {"direct_data": ["Receita anual R$1,5-2,0M informada pelo cliente", "Macro_context.industry_trends (CAGR 7-9% HPPC Brasil)"], "proxy_calculations": ["SAM estimado como 0,6-0,9% do TAM (wellness premium+hotelaria)", "SOM como 0,5-10% do SAM, conforme cenários RACE/AIM"], "benchmark_extrapolations": ["TAM HPPC Brasil ~R$120-160B/ano com base em ABIHPEC e varejo 1,5-2T", "Validação de SOM com faixa típica de PMEs (R$5-50M/ano)"]}, "estimation_method": "benchmark_setorial", "baseline_recommendation": "conservative"}'::jsonb, '{"summary": "Santapele é nicho especializado em wellness, com modelo B2B/B2C similar a Avatim e L''Occitane, mas ainda com menor escala nacional, menor intensidade digital e portfólio menos amplo que Natura e Granado. Mercado de wellness/cosméticos é amplo; com 2-5% do nicho, Santapele pode escalar de R$2M para ~R$30-40M/ano em 5-7 anos.", "best_practices": ["Posicionamento nichado em wellness premium, alinhado à tendência de clean beauty e experiência sensorial.", "Modelo híbrido B2B hotelaria/spas + B2C e-commerce espelha estratégia vencedora de Avatim e L''Occitane.", "Operação bootstrapped enxuta favorece disciplina de caixa que falta em grandes grupos alavancados."], "performance_gaps": ["Baixa escala de marca vs. Natura/Granado; pouca presença nacional e em canais próprios físicos.", "Maturidade digital abaixo de líderes em CRM, personalização e automação de marketing.", "Portfólio e P&D menos robustos; menor velocidade de lançamentos e testes de linhas wellness."], "competitors_analyzed": ["Granado Pharmácias", "Avatim", "Natura &Co", "L''Occitane au Brésil"]}'::jsonb, '{"raise": ["Profundidade de parcerias exclusivas com hotéis, spas e retreats", "Nível de personalização de rituais e kits por jornada do hóspede", "Transparência sobre origem, impacto e ciência dos ingredientes"], "create": ["Plataforma de amenities wellness-as-a-service para redes hoteleiras", "Clube de assinatura de rituais sensoriais ligados a destinos do Brasil", "App de rotinas guiadas integrando produtos, IA e dados dos parceiros"], "reduce": ["Portfólio de SKUs pouco rentáveis ou sem fit com wellness premium", "Investimento em mídia ampla; focar em nichos B2B de alta margem", "Complexidade logística com múltiplos operadores e armazéns"], "summary": "A Santapele sai da disputa de prateleira e cria um ecossistema wellness B2B2C: parcerias exclusivas com hotelaria e spas, recorrência via assinaturas de rituais e plataforma digital de experiências personalizadas, maximizando margem e fidelidade com baixo CAPEX físico.", "eliminate": ["Competição por preço com linhas de cosméticos de massa", "Campanhas genéricas de influência sem vínculo com bem-estar real", "Dependência de revenda em PDVs sem curadoria de experiência"], "new_value_curve": "De marca de cosméticos premium a plataforma de experiências wellness B2B2C recorrentes."}'::jsonb, '{"summary": "Direcionar R$2 mi para máquina de aquisição digital+B2B e CRM de recorrência, elevando LTV e preparando próxima rodada.", "leap_loop": {"name": "LEAP Loop", "type": "acquisition", "steps": ["Land: Atrair B2C via mídia paga/SEO wellness e B2B com prospecção ativa de hotéis/spas premium", "Engage: Nutrir leads com conteúdo de rituais de bem-estar, bastidores da marca e kits testers segmentados", "Activate: Oferecer primeira compra guiada com combos de rituais, desconto progressivo e onboarding B2B", "Propagate: Programa de indicação com benefícios para clientes e hotéis: upgrades, amenities extras e cupons"], "metrics": ["CAC B2C e B2B", "Taxa de conversão lead->cliente", "Engajamento de conteúdo (CTR, salvamentos, replies)", "Coeficiente viral (taxa de indicações/convidados)"], "bottleneck": "Aquisição digital ainda pouco estruturada (mídia, SEO, CRM), sem máquina previsível de geração de leads"}, "scale_loop": {"name": "SCALE Loop", "type": "monetization", "steps": ["Satisfy: Entregar experiência premium consistente em produto, embalagem, unboxing, entrega e suporte B2B", "Convert: Formalizar contratos recorrentes com hotéis/spas e bundles de assinatura de rituais para B2C", "Loop Back: Usar CRM para reposição preditiva, campanhas sazonais e clube de pontos por frequência e ticket", "Expand: Fazer upsell de linhas complementares, edições limitadas e cross-sell entre canais B2B e B2C"], "metrics": ["LTV por segmento (B2B/B2C)", "Taxa de recompra em 60-90 dias", "MRR/receita recorrente de contratos B2B", "Receita de upsell e cross-sell por cliente"], "bottleneck": "Ausência de plano detalhado e de máquina de retenção/recorrência estruturada reduz LTV e previsibilidade de caixa"}}'::jsonb, '{"realist": {"name": "Cenário Realista", "description": "Economia cresce perto de 2,20%, com comércio em -0,30% e serviços em +0,60%. SELIC permanece elevada em 14,90% a.a., IPCA em 0,09% (12 meses) e câmbio em torno de R$ 5,35/USD. Consumo segue seletivo: ou preço-benefício ou experiência premium. Espaço existe para nichos wellness, mas com forte disciplina de caixa e eficiência digital.", "probability": 60, "required_actions": ["Priorizar aplicação dos R$ 2 milhões em produtividade: automação de marketing, CRM unificado e melhoria de margem bruta (negociação com fornecedores, logística)", "Focar mix premium enxuto: reduzir SKUs de baixa margem, reforçar best-sellers alinhados à tendência wellness e sustentabilidade", "Fortalecer robustez regulatória: investir em adequação ANVISA, rotulagem e logística reversa para evitar riscos e ganhar confiança de varejistas B2B", "Criar trilha clara de próxima rodada (Seed/Series A): metas trimestrais de receita (R$ 1,5–2M atuais para patamar superior), LTV/CAC e share em B2B hotelaria"]}, "summary": "O plano de investimento de R$ 2 milhões para a Santapele Cosméticos deve equilibrar crescimento digital e proteção de caixa num ambiente de juros de 14,90% a.a., câmbio em R$ 5,35/USD e consumo seletivo. Preparar-se exige: foco em eficiência omnichannel, mix premium enxuto, blindagem regulatória, contratos de suprimentos mais previsíveis e métricas claras para habilitar a próxima rodada de captação.", "optimistic": {"name": "Cenário Otimista", "description": "PIB acelera acima de 3,20%, serviços (+0,60%) e comércio superam -0,30%. SELIC inicia ciclo de queda a partir de 14,90% a.a., câmbio fica próximo de R$ 5,35/USD e desemprego segue em 5,60%. Consumo wellness premium reage; investidores buscam teses ESG, favorecendo Santapele em nicho de varejo wellness.", "probability": 20, "required_actions": ["Alocar ~R$ 800k em aceleração digital (mídia de performance, CRM, UX do e-commerce) para capturar B2C de alta renda", "Investir ~R$ 600k em expansão B2B selecionada (hotelaria/spas âncora), com contratos de médio prazo e co-branding", "Direcionar ~R$ 400k para inovação de mix premium enxuto e certificações (cruelty-free, sustentabilidade) reforçando posicionamento", "Reservar ~R$ 200k para testes de novos canais (marketplaces selecionados, lojas parceiras) com métricas rígidas de payback"]}, "pessimistic": {"name": "Cenário Pessimista", "description": "Crescimento do PIB cai abaixo de 2,20%, comércio aprofunda queda além de -0,30% e desemprego supera 5,60%. SELIC se mantém em 14,90% a.a. por mais tempo, pressionando crédito, e o câmbio rompe o patamar de R$ 5,35/USD, elevando custos de insumos e logística. Consumidor migra para marcas próprias e importados baratos, apertando nichos premium.", "probability": 20, "required_actions": ["Repriorizar o plano: preservar caixa dos R$ 2 milhões, alongando runway, cortando despesas não essenciais e congelando expansões físicas", "Reforçar oferta de entrada e kits com melhor relação valor percebido/preço para defender base B2C e B2B sensível a custo", "Negociar contratos mais longos com fornecedores estratégicos para mitigar repasses ligados a câmbio e juros, mantendo margem mínima"]}, "mitigation_tactics": ["Manter reserva de liquidez dos R$ 2 milhões (ao menos 6–9 meses de custos fixos) dado o nível de 14,90% a.a. de juros e volatilidade de R$ 5,35/USD", "Estruturar portfólio em camadas (entrada, core, premium) para ajustar mix rapidamente conforme consumo se torna mais ou menos seletivo", "Firmar acordos de médio prazo com fornecedores críticos, atrelados a índices como IPCA (0,09% em 12 meses) para reduzir choques de preços", "Construir plano regulatório contínuo (ANVISA, rotulagem, logística reversa) para evitar multas e bloqueios que afetem fluxo de caixa"], "early_warning_signals": ["Mudanças na SELIC em relação aos 14,90% a.a. atuais (prolongamento em patamar alto ou nova alta indica ambiente mais restritivo)", "Deslocamentos significativos do câmbio em torno de R$ 5,35/USD, impactando custos de insumos e fretes ligados a petróleo", "Piora dos dados de comércio (-0,30%) e aumento do desemprego acima de 5,60%, sinalizando queda adicional do consumo seletivo premium"]}'::jsonb, '{"summary": "BSC alinha uso dos R$ 2 mi para escalar ecossistema wellness B2B2C com recorrência e margem.", "customer": ["Alcançar NPS ≥ 70 em hóspedes e spas parceiros até 24 meses", "Atingir 10k assinantes ativos de rituais wellness B2C"], "financial": ["Aumentar receita anual para R$ 4 mi em 24 meses pós-captação", "Elevar margem bruta média para 55% com mix B2B2C wellness"], "learning_growth": ["Formar squad multifuncional de produto digital e CX (4-6 pessoas)", "Treinar rede B2B em proposta wellness Santapele em 100% dos parceiros"], "internal_processes": ["Implantar plataforma digital de experiências personalizada em 12 meses", "Estruturar playbook de parcerias com 50 hotéis/spas qualificados"]}'::jsonb, '{"score": "8,2/10", "summary": "A Matriz de Decisão considera três caminhos: (A) Crescimento omnichannel digital-first; (B) Expansão B2B institucional/internacionalização; (C) Foco em eficiência e preservação de caixa. Dado o estágio da Santapele Cosméticos (bootstrapped, receita anual entre R$ 1,5M e R$ 2M, atuação B2B e B2C em nicho premium), a Alternativa A obteve o melhor score (8,2/10), cerca de 18% acima da segunda opção. Ela maximiza o uso dos R$ 2 milhões para criar uma máquina de crescimento integrada, ancorada em marca forte, CRM e canais omnichannel eficientes, o que é crítico em um ambiente de juros altos (SELIC 14,90% a.a.) e câmbio pressionado (USD/BRL 5.3416). A execução recomendada distribui o capital em três blocos: (1) Core de crescimento omnichannel e dados (prioridade 1, maior parte do orçamento); (2) Base produtiva/regulatória e mix premium enxuto (prioridade 2, foco em margem e redução de risco operacional); (3) Governança, instrumentos societários e preparação para a próxima rodada (prioridade 3, maior risco jurídico, exigindo parecer especializado). O ciclo de revisão trimestral, com gatilhos extraordinários (mudanças regulatórias relevantes, bloqueios de licenciamento, decisões judiciais, falhas de compliance e entrada de competidores fortes), garantirá ajustes de rota. Próximos passos: detalhar o plano de uso dos recursos por trimestre, contratar assessoria jurídica para as frentes de LGPD/ANVISA/societário e estabelecer um painel de métricas (financeiras, comerciais e operacionais) para monitorar a execução e sustentar a narrativa para investidores na próxima rodada.", "criteria": ["ROI estimado em 3-4 anos (crescimento de receita, margem e valorização da empresa para próxima rodada)", "Risco financeiro, operacional e regulatório (incluindo ANVISA, LGPD e dependência de terceiros)", "Velocidade de execução e preparo para próxima rodada de captação (claridade de métricas e história para investidores)"], "alternatives": ["Alternativa A - Crescimento omnichannel digital-first (equilíbrio entre e-commerce, B2B e lojas parceiras, com foco em marca e dados próprios)", "Alternativa B - Expansão acelerada B2B institucional e internacionalização piloto (hotéis, spas e exportação seletiva)", "Alternativa C - Eficiência operacional e preservação de caixa (crescimento orgânico mais lento, priorizando margem e redução de risco)"], "review_cycle": {"frequency": "Trimestral", "extraordinary_triggers": ["Mudança regulatória >10% custo", "Bloqueio de licenciamento", "Decisão judicial relevante", "Falha de compliance LGPD/setorial", "Entrada de competidor relevante"]}, "score_comparison": "+18% acima da segunda opção", "monitoring_metrics": ["Receita mensal por canal (B2B e B2C) e crescimento percentual", "CAC e LTV por segmento de cliente (hotelaria/spas vs. consumidor final)", "Margem bruta e EBITDA ajustado, considerando impacto de juros elevados", "Giro de estoque, nível de ruptura e idade média dos produtos em estoque", "Taxa de recompra, NPS e avaliações em canais digitais", "Runway de caixa (meses) e burn multiple em relação à nova receita gerada"], "recommended_option": "Alternativa A - Crescimento omnichannel digital-first (equilíbrio entre e-commerce, B2B e lojas parceiras, com foco em marca e dados próprios)", "final_recommendation": "A melhor opção é a Alternativa A – Crescimento omnichannel digital-first, pois equilibra aceleração de receita, eficiência de capital em ambiente de SELIC 14,90% a.a. e construção de métricas sólidas para viabilizar a próxima rodada de captação.", "priority_recommendations": [{"title": "Construir máquina de crescimento omnichannel e dados próprios (core do plano de R$ 2M)", "budget": "R$900k-1,1M", "priority": 1, "timeline": "18-24 meses", "description": "Alocar a maior parte dos R$ 2 milhões para acelerar o crescimento omnichannel da Santapele Cosméticos, integrando e-commerce, canais B2B (hotelaria/spas) e pontos físicos parceiros. Principais frentes: (1) Performance digital e branding premium com foco em wellness; (2) Estruturação de CRM e dados próprios (first-party data) para personalização de ofertas, retenção e aumento de ticket médio; (3) Fortalecimento da operação B2B com time comercial enxuto, playbook de vendas consultivas e contratos-padrão; (4) Integração mínima de sistemas (ERP, e-commerce, meios de pagamento e logística) para reduzir atrito de compra e melhorar margem em um cenário de SELIC 14,90% a.a. e câmbio USD/BRL 5.3416. Esse bloco deve gerar tração mensurável em até 18-24 meses e construir o case de crescimento para a próxima rodada.", "legal_feasibility": {"risk_level": "Médio", "mitigation_plan": "1) Realizar parecer jurídico específico sobre LGPD e marketing digital antes de escalar campanhas de mídia e automações de CRM; 2) Implementar políticas claras de privacidade, consentimento granular e opt-out em todos os pontos de coleta de dados; 3) Revisar materiais de comunicação para garantir que benefícios alegados estejam alinhados com o enquadramento regulatório de cosméticos; 4) Alternativa de menor risco, se houver restrição regulatória a dados: intensificar canais orgânicos e parcerias B2B com uso mínimo de dados pessoais sensíveis, priorizando segmentação contextual em vez de comportamental profunda.", "requires_legal_opinion": true, "regulatory_dependencies": ["Adequação plena à LGPD para CRM, segmentação e campanhas de marketing", "Observância ao Código de Defesa do Consumidor (CDC) em promoções e políticas de troca", "Regras de publicidade para cosméticos (evitar alegações terapêuticas fora do escopo ANVISA)"], "requires_statutory_change": false}}, {"title": "Fortalecer base produtiva, regulatória e mix premium enxuto", "budget": "R$500-650k", "priority": 2, "timeline": "12-18 meses", "description": "Direcionar parte relevante do capital para consolidar a base produtiva e regulatória da Santapele Cosméticos, com foco em um portfólio premium enxuto, de alta margem e baixa complexidade operacional. Ações: (1) Revisão e priorização de portfólio (foco em linhas com melhor margem e aderência ao posicionamento wellness de nicho); (2) Ajustes de formulação e rotulagem em conformidade com RDCs ANVISA recentes (alérgenos, claims de natural/vegano, etc.); (3) Negociação de contratos de suprimentos mais previsíveis (insumos, embalagens, logística) para reduzir exposição à volatilidade de câmbio e commodities; (4) Construção de mínima inteligência de planejamento de demanda para reduzir ruptura e excesso de estoque. Essa frente melhora margem bruta, reduz risco operacional e reforça a narrativa de sustentabilidade e compliance para investidores.", "legal_feasibility": {"risk_level": "Médio", "mitigation_plan": "1) Solicitar revisão jurídica-regulatória (especialista em ANVISA/HPPC) das fórmulas, rotulagens e claims de marketing antes de lançamento ou reformulação; 2) Incluir cláusulas de compliance regulatório e responsabilidade compartilhada em contratos com fabricantes terceirizados; 3) Estruturar processo interno de revisão periódica de rótulos e materiais técnicos à luz de novas RDCs; 4) Caso o custo de adequação regulatória seja muito elevado em algum item, optar por descontinuar produtos marginais em vez de insistir na regularização, focando no portfólio core mais rentável.", "requires_legal_opinion": true, "regulatory_dependencies": ["Conformidade com RDCs ANVISA aplicáveis a cosméticos e rotulagem", "Atendimento à Lei de Logística Reversa de embalagens", "Adequação a normas de Boas Práticas de Fabricação (BPF) na cadeia produtiva, própria ou terceirizada"], "requires_statutory_change": false}}, {"title": "Preparar governança, instrumentos societários e métricas para a próxima rodada de captação", "budget": "R$250-350k", "priority": 3, "timeline": "9-18 meses", "description": "Usar uma parcela menor, porém estratégica, dos R$ 2 milhões para estruturar governança mínima, instrumentos contratuais e métricas que tornem a Santapele Cosméticos mais investível em 18-24 meses. Ações: (1) Organizar demonstrativos financeiros e KPIs por canal (B2B/B2C) com rotina de reporting; (2) Revisar contrato social, acordos entre sócios e eventual estrutura de incentivos (ex.: phantom shares ou planos de bônus atrelados a metas); (3) Preparar data room jurídico-financeiro para investidores (contratos-chave, licenças, propriedade intelectual, marca); (4) Definir tese e milestones para a próxima rodada (por exemplo, Série A) com base nos resultados do plano atual.", "legal_feasibility": {"risk_level": "Alto", "mitigation_plan": "1) Obter parecer jurídico societário antes de qualquer alteração de contrato social ou estrutura de entrada de investidores; 2) Planejar a entrada de capital por etapas (ex.: primeiro via mútuo conversível com investidor-âncora, depois consolidação societária), reduzindo o risco de litígios entre sócios; 3) Incluir cláusulas claras de solução de conflitos, vesting e governança em acordos de sócios; 4) Garantir que todos os dados e demonstrações usados na captação reflitam a realidade contábil para mitigar risco de responsabilização; 5) Alternativa de menor risco: manter uma estrutura societária simples e usar instrumentos padronizados de mercado (mútuo conversível ou SAFE adaptado à realidade brasileira), adiando estruturas mais complexas para uma rodada posterior e maior.", "requires_legal_opinion": true, "regulatory_dependencies": ["Registro de alterações de contrato social/estatuto na Junta Comercial competente", "Adequação a normas societárias e, se houver estrutura de oferta a múltiplos investidores, eventual análise de enquadramento junto à CVM", "Conformidade trabalhista e tributária associada a eventuais planos de incentivo (bônus, phantom shares etc.)"], "requires_statutory_change": true}}]}'::jsonb, 'completed', NULL, 191866, false, false, false, 'KHQKIHG1', '2025-12-02 02:29:24.162188+00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-02 02:21:07.791726+00'::timestamptz, '2025-12-02 02:29:24.162188+00'::timestamptz, '2025-12-02 02:29:17.82993+00'::timestamptz, NULL)
