-- Row 13/36: 1ff55239-b34c-4928-93de-7fdd1c317e87
INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('1ff55239-b34c-4928-93de-7fdd1c317e87', '5d65929d-2b5f-42a1-b008-4040a462a25d', 'ef2fd271-8ce9-436d-864f-bc7986642efd', NULL, '{"summary": "Base financeira validada e proposta diferenciada; precisa digitalizar, reduzir dependência da fundadora e profissionalizar gestão para crescer com segurança.", "threats": [{"source": "análise de mercado", "content": "Proteger margens de insumos dolarizados com contratos e reajustes", "confidence": "Média"}, {"source": "análise de mercado", "content": "Reforçar proposta premium para não perder espaço a franquias baratas", "confidence": "Média"}, {"source": "análise de mercado", "content": "Fortalecer compliance ANVISA e LGPD com auditorias e treinamentos", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Otimizar CAC digital com segmentação, remarketing e nutrição de leads", "confidence": "Média"}], "strengths": [{"source": "fato", "content": "Alavancar missão e visão claras em toda comunicação externa", "confidence": "Alta"}, {"source": "fato", "content": "Usar modelo bootstrapped para reinvestir em digital e equipe", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Diferenciar-se pela experiência leve e humanizada em bem-estar", "confidence": "Média"}, {"source": "fato", "content": "Usar receita validada para testar pilotos de novos serviços", "confidence": "Alta"}], "weaknesses": [{"source": "fato", "content": "Reduzir dependência da fundadora via protocolos e líderes clínicos", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Estruturar presença digital (site, SEO, redes) para captar demanda", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Mitigar colisão de marca registrando e comunicando Vallen Clinic", "confidence": "Média"}, {"source": "estimativa", "content": "Formalizar rotina de gestão com KPIs e reuniões de performance", "confidence": "Média"}], "opportunities": [{"source": "análise de mercado", "content": "Criar ecossistema digital de bem-estar integral com conteúdo e CRM", "confidence": "Média"}, {"source": "análise de mercado", "content": "Lançar programas de assinatura de cuidados integrados recorrentes", "confidence": "Média"}, {"source": "análise de mercado", "content": "Fechar parcerias com spas, academias e médicos integrativos em SP", "confidence": "Média"}, {"source": "estimativa", "content": "Desenvolver linha própria de produtos sustentáveis da marca Vallen", "confidence": "Baixa"}]}'::jsonb, '{"legal": ["LGPD na saúde exige revisão de prontuários, consentimentos e fluxo digital de dados dos pacientes.", "Normas ANVISA para procedimentos invasivos elevam necessidade de protocolos e treinamentos rígidos.", "Obrigatoriedade de RT, Licença Sanitária e CNES torna dependência de profissionais risco-chave."], "social": ["Busca pós-pandemia por autocuidado integra saúde+beleza, alinhada ao bem-estar integral da Vallen.", "Consumidor endividado prioriza experiências de alto valor percebido, exigindo posicionamento claro.", "Banalização por não-especialistas abre espaço para diferenciar com excelência, RT e segurança."], "summary": "Ambiente regulatório e cambial pressiona margens e compliance, enquanto demanda por bem-estar integral cresce. Vallen deve reforçar diferenciação em segurança e sustentabilidade, digitalizar jornada e estruturar governança para reduzir risco pessoal.", "economic": ["SELIC 14,90% favorece clínica sem dívidas, mas restringe crédito parcelado dos pacientes.", "Dólar a R$5,37 encarece insumos importados, pressionando margens em serviços premium.", "PIB +3,2% e desemprego 5,6% sustentam demanda, mas consumo segue seletivo e exigente."], "political": ["Reformas sanitárias em pauta podem elevar exigências e custos regulatórios da Vallen.", "Novas normas para clínicas de estética aumentam fiscalização e risco de autuações.", "Maior rigor futuro na publicidade estética tende a restringir ações de marketing da marca."], "environmental": ["Tendência de sustentabilidade em cosméticos favorece narrativa de conexão com a natureza da Vallen.", "Pressão por insumos eco-friendly pode elevar custos, exigindo curadoria e precificação cuidadosa.", "Cadeia de suprimentos sensível ao câmbio exige diversificar fornecedores e estoques críticos."], "technological": ["Adoção média de tecnologia exige agendamento online fluido para competir com clínicas boutique.", "CAC digital em alta torna urgente estratégia orgânica e de indicação para reduzir aquisição.", "Teleatendimento e conteúdo remoto ampliam alcance da fundadora sem depender só da presença física."]}'::jsonb, '{"summary": "O nicho de saúde e estética integrativa em SP é promissor, mas com rivalidade intensa, poder do cliente alto e custos sensíveis ao dólar. Vallen deve alavancar diferenciação experiencial, dados e parcerias para proteger margens e crescer com menos dependência da fundadora.", "buyer_power": "Com SELIC a 14,90% e famílias endividadas, consumidor A/B torna-se mais seletivo; prioriza experiências de alto valor percebido, pressionando Vallen a provar resultados e justificar tíquete acima da média.", "supplier_power": "Dependência de insumos dolarizados (USD/BRL 5,37) eleva custo e reduz poder de barganha da Vallen; cadeia estável porém sensível ao câmbio exige repasse seletivo de preços e contratos mais longos com fornecedores-chave.", "disruption_ai_data": "Uso crescente de IA em marketing, CRM e agendamento em clínicas rivais, somado a CAC digital em alta, pode deixar a Vallen atrás; ausência de dados estruturados limita personalização, devendo investir em MarTech segura (LGPD).", "threat_substitutes": "Substitutos fortes: spas, franquias populares e procedimentos baratos por não-especialistas banalizam estética; apps de bem-estar reduzem visitas presenciais, exigindo da Vallen foco em segurança clínica e cuidado integrativo.", "competitive_rivalry": "Alta rivalidade em SP: mercado fragmentado, franquias low-cost e clínicas boutique disputam público A/B; Vallen precisa fortalecer marca autoral, experiência integrativa e preço prêmio para evitar erosão de margem.", "threat_new_entrants": "Acesso moderado a capital e barreiras ANVISA/RT apenas médias permitem expansão de franquias de estética; novos entrantes em SP podem copiar ambientação premium, exigindo da Vallen marca forte e protocolos exclusivos.", "buyer_power_intensity": "Alta", "overall_attractiveness": "Média", "strategic_implications": ["[Reach] Construir presença digital própria (site, SEO local, mídias sociais) para reduzir CAC pago, fortalecer marca Vallen Clinic e mitigar rivalidade em SP.", "[Act] Criar jornadas integrativas corpo-mente com protocolos exclusivos e sustentáveis, documentando resultados clínicos para diferenciar de franquias de baixo custo.", "[Convert] Estruturar oferta de pacotes e assinatura de bem-estar, com pricing baseado em valor, reduzindo sensibilidade a juros altos e estabilizando receita recorrente.", "[Engage] Implantar CRM com IA leve para follow-up, NPS e recomendações personalizadas, organizando dados sob LGPD e diminuindo dependência da fundadora nos relacionamentos."], "supplier_power_intensity": "Média", "disruption_ai_data_intensity": "Alta", "threat_substitutes_intensity": "Alta", "competitive_rivalry_intensity": "Alta", "power_partnerships_ecosystems": "Ecossistemas de saúde integrativa, psicologia, fitness e marcas verdes ganham força; parcerias estratégicas podem reduzir CAC digital alto e ampliar alcance da Vallen em bem-estar 360°, reforçando posicionamento premium sustentável.", "threat_new_entrants_intensity": "Média", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": "90 dias para estruturar o Método Vallen, criar lideranças, implantar gestão básica e lançar um MVP digital com plano de bem-estar integral pronto para validação.", "plan_90_days": [{"focus": "Fundação", "month": "Mês 1", "objective": "Desenhar o Método Vallen e a base organizacional para bem-estar integral", "investment": "R$ 10-20 mil", "key_results": ["Mapear 5 jornadas de cliente em fluxos simples (resp.: Coord. CX)", "Produzir manual v1.0 do Método Vallen com 20+ páginas (resp.: Thalita)", "Definir organograma e 10 descrições de função-chave (resp.: Gestor RH)"], "aligned_recommendation": "Profissionalizar gestão e reduzir dependência da fundadora via Método Vallen"}, {"focus": "Crescimento", "month": "Mês 2", "objective": "Iniciar descolamento da operação da fundadora com líderes e rotinas de gestão", "investment": "R$ 20-40 mil", "key_results": ["Nomear 1 líder clínico e 1 líder operacional com papéis claros (resp.: Thalita)", "Implantar reunião quinzenal de performance com 5 KPIs (resp.: Gestor geral)", "Realizar 2 workshops internos do Método Vallen v1.0 (resp.: Líder clínico)"], "aligned_recommendation": "Formalizar rotina de gestão com KPIs e reduzir dependência da fundadora"}, {"focus": "Consolidação", "month": "Mês 3", "objective": "Lançar MVP digital e 1 plano de bem-estar integral baseado no Método Vallen", "investment": "R$ 30-50 mil", "key_results": ["Publicar site simples com agendamento online e blog (resp.: Mkt digital)", "Desenhar 1 plano de assinatura de bem-estar com escopo definido (resp.: Produto)", "Testar MVP digital e plano com 10 clientes e medir NPS piloto (resp.: Coord. CX)"], "aligned_recommendation": "Criar ecossistema digital e planos de assinatura de bem-estar integral"}], "success_metrics": ["Método Vallen v1.0 documentado e utilizado em pelo menos 1 protocolo-chave", "Líderes clínico e operacional atuando com rotina de KPIs implementada", "Site/MVP digital no ar e 1 plano de assinatura piloto testado com 10 clientes"], "execution_phases": {"scale": {"focus": "Expansão controlada", "duration": "Meses 7-12", "objectives": ["Escalar gradualmente planos de assinatura e ecossistema digital", "Fortalecer posicionamento de bem-estar integral e sustentabilidade em SP"], "key_results": ["Expandir planos de assinatura para 3x o número de clientes do piloto", "Alcançar cobertura digital consistente em 3 canais (site, Instagram, e-mail)"], "prerequisites": ["Validação bem-sucedida do plano de assinatura com NPS alvo atingido", "Processos-chave padronizados e lideranças consolidadas", "Capacidade operacional dimensionada para crescer sem sobrecarga"], "investment_range": "R$ 150-300 mil"}, "foundation": {"focus": "Estruturação", "duration": "Meses 1-3", "objectives": ["Codificar o Método Vallen e reduzir dependência operacional da fundadora", "Organizar estrutura, funções e rotinas mínimas de gestão da clínica"], "key_results": ["Manual do Método Vallen v1.0 concluído e aprovado pela equipe clínica", "Rotina de reuniões de performance definida e testada por 2 ciclos"], "investment_range": "R$ 60-110 mil", "capacity_requirements": {"team": "6-10 pessoas núcleo (fundadora, 2-3 clínicos, gestão, marketing, apoio)", "dependencies": ["Disponibilidade de tempo da fundadora para transferência de conhecimento", "Contratação ou alocação de profissional de marketing digital"], "skills_needed": ["Gestão clínica e de serviços em saúde", "Design de serviços e experiência do cliente", "Marketing digital básico e conteúdo", "Organização de processos e RH"]}}, "validation": {"focus": "Pilotos", "duration": "Meses 4-6", "objectives": ["Validar o plano de assinatura de bem-estar integral em pequena escala", "Ajustar operação, experiência e comunicação com base em feedback real"], "key_results": ["Rodar piloto do plano de assinatura com 20-30 clientes ativos", "Alcançar NPS médio ≥ 70 no piloto e registrar 15+ feedbacks qualitativos"], "prerequisites": ["Fase 1 concluída com Método Vallen v1.0 documentado", "Líder clínico e operacional nomeados e atuantes", "Site/MVP digital e agendamento online publicados"], "investment_range": "R$ 70-130 mil"}}, "total_investment": "R$ 60-110 mil (soma dos 3 meses)", "capacity_assessment": {"blockers": ["Dependência histórica da fundadora para decisões e atendimento chave", "Ausência de time digital interno dedicado (site, conteúdo, CRM)"], "team_readiness": "Média", "budget_adequacy": "Limitado", "stakeholder_alignment": "Parcial"}}'::jsonb, '{"roadmap": ["Curto Prazo (3-6 meses): Documentar Método Vallen, criar site com agendamento, definir 2 líderes e implantar gestão básica com indicadores", "Médio Prazo (6-12 meses): Lançar plano de assinatura de bem-estar, validar MVP digital com 50 clientes, estruturar compliance LGPD e proteção de marca", "Longo Prazo (12+ meses): Escalar modelo com equipe multidisciplinar autônoma, expandir para plataforma digital de conteúdo e parcerias estratégicas"], "key_findings": ["Modelo bootstrapped é vantagem em cenário de SELIC 14.9%, mas exige reinvestimento disciplinado para crescer", "Diferenciação por experiência (leveza, humor, natureza) é defensável se sistematizada em método proprietário", "Digitalização da jornada é pré-requisito para reduzir dependência da fundadora e escalar captação"], "main_findings": ["Força: Faturamento validado e independência financeira permitem investir em estruturação sem pressão de investidores", "Fraqueza: Dependência crítica da fundadora e ausência de presença digital verificável comprometem continuidade e captação", "Oportunidade: Demanda crescente por bem-estar integral pós-pandemia favorece diferenciação experiencial e sustentável", "Ameaça: Rivalidade intensa em SP, custos atrelados ao dólar e CAC digital em alta pressionam margens"], "important_notes": ["Risco de pessoa-chave: operação depende excessivamente de Thalita Mendes - mitigação urgente", "Ausência de site/redes verificáveis representa vulnerabilidade competitiva crítica em 2025", "Homônimos ''Vallen'' em SP podem gerar confusão de marca - avaliar proteção jurídica"], "central_challenge": "Reduzir a dependência crítica da fundadora Thalita Mendes enquanto estrutura governança, digitaliza a jornada do cliente e consolida o posicionamento de bem-estar integral diferenciado.", "executive_summary": "Vallen Clinic possui base financeira sólida (R$1.2-1.5M bootstrapped) e proposta única de bem-estar integral com leveza e sustentabilidade. O risco concentrado na fundadora e a baixa maturidade digital limitam escala. Prioridade: criar Método Vallen proprietário, formar lideranças e lançar MVP digital em 90 dias para validar modelo escalável.", "strategic_priorities": ["Estruturar Método Vallen documentado e treinar equipe para entrega independente", "Lançar presença digital mínima (site + agendamento) em 90 dias", "Formar 2 líderes internos para assumir operação e relacionamento"], "consistency_validation": {"flags": ["Tamanho de equipe não especificado - OKRs assumem capacidade mínima de 5-10 pessoas", "Investimento em digitalização deve ser <10% da receita anual para manter saúde financeira", "Risco de marca homônima requer due diligence jurídica antes de investir em branding"], "legal_alignment": true, "capacity_alignment": true, "financial_alignment": true, "overall_realism_score": 7}, "overall_recommendation": "Executar sprint de 90 dias focado em documentação do método, presença digital básica e formação de liderança. Validar modelo de assinatura antes de qualquer expansão física. Proteger marca juridicamente."}'::jsonb, '{"sam": "", "som": "", "tam": "", "cagr": "", "summary": "", "assumptions": null, "confidence_level": 0, "calculation_notes": "", "estimation_method": ""}'::jsonb, '{"summary": "Vallen se destaca em propósito e nicho premium, mas fica atrás em digital, escala e ofertas de bem-estar integrativo.", "best_practices": ["Missão e visão claras, alinhadas à tendência de bem-estar integrativo e atendimento humanizado.", "Posicionamento boutique focado em experiência e valor percebido, não em guerra de preços com franquias.", "Finanças saudáveis e bootstrapped, menos vulnerável a juros altos que redes alavancadas do setor."], "performance_gaps": ["Presença digital fraca vs. clínicas premium com sites, SEO, reviews e funil de aquisição estruturado.", "Alta dependência da fundadora vs. concorrentes com equipes, protocolos e gestão profissionalizada.", "Portfólio integrativo menor que spas urbanos que combinam estética, terapias, nutrição e saúde mental."], "competitors_analyzed": ["Clínicas de Dermatologia e Estética Premium em SP", "Spas Urbanos de Luxo em SP", "Franquias de Estética Premium/Boutique"]}'::jsonb, '{"raise": ["Protocolos integrativos corpo-mente com equipe multidisciplinar própria", "Experiência sensorial leve, divertida e acolhedora em todos os pontos", "Transparência em dados de resultados clínicos, bem-estar e satisfação"], "create": ["Método Vallen de bem-estar integral independente de profissionais estrelas", "Planos de assinatura com jornadas contínuas de saúde, beleza e autocuidado", "Plataforma digital própria com comunidade, triagem e acompanhamento remoto"], "reduce": ["Dependência operacional e comercial da imagem da Thalita", "Uso de equipamentos importados caros e sensíveis ao dólar", "Promoções de preço que corroem margem e atraem clientes oportunistas"], "summary": "A Vallen sai da disputa por procedimentos e imagem de celebridade para criar um ecossistema de bem-estar integral contínuo. A clínica passa a se apoiar em um Método Vallen proprietário, planos de assinatura e plataforma digital, reduzindo a dependência da fundadora. O diferencial está na combinação de ciência, leveza, humor e conexão com a natureza, ancorada em dados de resultado e numa equipe multidisciplinar que entrega experiências transformadoras e sustentáveis.", "eliminate": ["Foco em procedimentos isolados sem plano de bem-estar integral", "Ambiente clínico frio e impessoal típico de estética premium", "Marketing centrado em antes/depois e padrões estéticos irreais"], "new_value_curve": "Da estética de procedimentos para ecossistema de bem-estar integral contínuo, com método próprio, humor e conexão com natureza."}'::jsonb, '{"summary": "", "leap_loop": {"name": "", "type": "", "steps": null, "metrics": null, "bottleneck": ""}, "scale_loop": {"name": "", "type": "", "steps": null, "metrics": null, "bottleneck": ""}}'::jsonb, '{"realist": {"name": "Cenário Realista", "description": "SELIC em 14,90% e dólar em torno de R$5,37 mantêm margem pressionada e cliente seletivo. PIB cresce perto de 3,2%, sustentando demanda por autocuidado, mas franquias populares disputam preço e clínicas boutique disputam experiência. Fiscalização ANVISA/LGPD eleva custo de compliance. Vallen cresce moderadamente se estruturar governança, foco em valor percebido e jornada digital fluida.", "probability": 60, "required_actions": ["Rever mix de serviços priorizando margens altas e percepção de valor (combos integrativos, planos recorrentes).", "Implantar stack digital mínima: site, agendamento online, CRM, automação de lembretes e pós-consulta.", "Criar comitê clínico e de marca para garantir biossegurança, LGPD e alinhamento à missão em cada procedimento.", "Desenhar trilhas de carreira e metas por profissional para diluir agenda da Thalita e padronizar experiência."]}, "summary": "Riscos centrais: juros e câmbio pressionando margens, aperto regulatório em estética, aumento de CAC e dependência da fundadora. Em cenário base, o mercado de bem-estar segue crescendo, porém seletivo. Preparar-se exige: fortalecer diferenciação em segurança e sustentabilidade, acelerar digitalização da jornada, profissionalizar governança e reduzir risco pessoal concentrado na Thalita.", "optimistic": {"name": "Cenário Otimista", "description": "Com SELIC caindo para 9% e PIB acima de 3,5%, consumo parcelado de classe A/B reage. Dólar recua para R$4,80, reduzindo custo de insumos estéticos. Regras da ANVISA e LGPD estabilizam, punindo concorrentes informais e valorizando segurança, bem-estar integral e sustentabilidade. Vallen consolida posição boutique, menos dependente da fundadora e com forte presença digital.", "probability": 20, "required_actions": ["Acelerar posicionamento em bem-estar integral com protocolos corpo+mente e produtos sustentáveis próprios.", "Escalar presença digital (site, agendamento online, funis de conteúdo) para capturar demanda crescente.", "Formalizar governança: processos padronizados, indicadores e delegação clara para reduzir dependência da Thalita."]}, "pessimistic": {"name": "Cenário Pessimista", "description": "Nova onda regulatória em estética e publicidade, com fiscalização intensa da ANVISA e conselhos, eleva custos e risco de autuações. SELIC acima de 15% e dólar acima de R$5,80 retraem consumo e encarecem insumos importados. Clínicas low cost banalizam procedimentos, ampliando desconfiança. Alta dependência da fundadora trava expansão e dificulta resposta rápida à crise.", "probability": 20, "required_actions": ["Reforçar caixa com corte de custos não essenciais e renegociação de contratos de aluguel, insumos e serviços.", "Repriorizar serviços de maior margem e menor exposição cambial, com foco em segurança e resultados mensuráveis.", "Contratar apoio jurídico/regulatório e formalizar plano de continuidade do negócio sem a presença diária da Thalita."]}, "mitigation_tactics": ["Criar política de compras e estoques com hedge parcial contra câmbio (antecipação de insumos críticos e negociação em reais).", "Implantar programa robusto de compliance (ANVISA, RT, biossegurança, LGPD) com treinamentos periódicos e auditorias internas.", "Diversificar canais de aquisição (orgânico, indicações, parcerias locais, conteúdo) para reduzir dependência de mídia paga e CAC alto.", "Instituir conselho consultivo e plano sucessório, documentando processos-chave e transferindo know-how da fundadora à equipe."], "early_warning_signals": ["SELIC acima de 15% ou dólar sustentado acima de R$5,80, combinados com queda no faturamento médio por cliente.", "Aumento de notificações de fiscalização sanitária ou mudanças nas normas ANVISA/LGPD ligadas a estética e publicidade.", "Crescimento abrupto do CAC digital e queda na taxa de conversão de leads em consultas provenientes de canais online."]}'::jsonb, '{"summary": "O BSC foca em receita recorrente, NPS elevado, método proprietário padronizado, digitalização e fortalecimento da equipe para reduzir dependência da fundadora e sustentar o ecossistema de bem-estar integral.", "customer": ["Alcançar NPS ≥ 85 reforçando leveza, humor e bem-estar integral", "Aumentar em 40% clientes ativos em planos de assinatura do Método Vallen"], "financial": ["Aumentar receita recorrente via planos Vallen em 30% em 24 meses", "Elevar margem líquida em 5 p.p. com mix de serviços premium e digitais"], "learning_growth": ["Desenvolver trilha de formação da equipe em bem-estar integral e dados", "Reduzir dependência da fundadora com 2 líderes técnicos até 2026"], "internal_processes": ["Padronizar o Método Vallen com protocolos e checklists até 2026", "Lançar plataforma digital com agendamento, jornada e teleatendimento"]}'::jsonb, '{"score": "", "summary": "", "criteria": null, "alternatives": null, "review_cycle": {"frequency": "", "extraordinary_triggers": null}, "score_comparison": "", "monitoring_metrics": null, "recommended_option": "", "final_recommendation": "", "priority_recommendations": null}'::jsonb, 'completed', NULL, 301397, false, false, false, '9J4Z9HDE', '2025-12-01 13:54:48.039251+00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-01 13:49:21.213627+00'::timestamptz, '2025-12-01 13:54:48.039251+00'::timestamptz, '2025-12-01 13:54:22.357864+00'::timestamptz, NULL)
