-- Row 17/36: 6670810c-8cd7-496b-8354-68e7b717418e
INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('6670810c-8cd7-496b-8354-68e7b717418e', 'b956c13e-7678-4127-acff-f1a76a51b10f', 'df2cefee-1c5e-4da0-893d-e0d27a6582ba', NULL, '{"summary": "Ativo raro e premiado, mas pouco visível. Priorizar processo competitivo global, tese robusta de exportação premium e fortalecimento regulatório para maximizar valor de saída.", "threats": [{"source": "análise de mercado", "content": "Poucos compradores globais concentrando poder de barganha contra o vendedor", "confidence": "Alta"}, {"source": "fato", "content": "Atrasos ou falhas em requisitos MAPA podem travar exportação e fechar janelas", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Gin e outros destilados premium disputam orçamento de portfólio dos grupos", "confidence": "Média"}, {"source": "análise de mercado", "content": "Cenário de juros altos reduz apetite e múltiplos de M&A em bebidas", "confidence": "Alta"}], "strengths": [{"source": "fato", "content": "Usar escassez do estoque 12 anos como âncora de valuation na negociação", "confidence": "Alta"}, {"source": "fato", "content": "Evidenciar premiações para sustentar posicionamento premium internacional", "confidence": "Alta"}, {"source": "estimativa", "content": "Oferecer infraestrutura operacional pronta reduzindo capex do comprador", "confidence": "Média"}, {"source": "análise de mercado", "content": "Alinhar narrativa de tradição e terroir às tendências de beber menos e melhor", "confidence": "Média"}], "weaknesses": [{"source": "análise de mercado", "content": "Baixa visibilidade global limita alcance de compradores estratégicos", "confidence": "Média"}, {"source": "estimativa", "content": "Tese financeira do ativo pouco formalizada para due diligence rigorosa", "confidence": "Média"}, {"source": "estimativa", "content": "Estrutura de compliance MAPA e exportação pode não estar totalmente robusta", "confidence": "Baixa"}, {"source": "análise de mercado", "content": "Dependência de poucos canais gera baixa leitura de demanda global", "confidence": "Média"}], "opportunities": [{"source": "análise de mercado", "content": "Rodar processo competitivo de venda alvo em grupos globais e fundos de spirits", "confidence": "Média"}, {"source": "análise de mercado", "content": "Desenhar tese de exportação premium focada em EUA, UE e Ásia", "confidence": "Alta"}, {"source": "estimativa", "content": "Aplicar IA para mapear compradores, precificar lotes e testar cenários", "confidence": "Média"}, {"source": "análise de mercado", "content": "Criar data room e materiais em inglês para acelerar diligência de buyers", "confidence": "Alta"}]}'::jsonb, '{"legal": ["Registro de Estabelecimento Produtor no MAPA é ativo, mas falhas documentais podem travar M&A", "Norma MAPA e regras mais rígidas de ''Envelhecida'' valorizam estoque 12 anos bem comprovado", "Acordo Mercosul-UE pode reduzir tarifas e elevar valuation via cenário de exportação futura"], "social": ["Premiumização (''beber menos, melhor'') concentra demanda em rótulos 12 anos, mas reduz base de volume", "Alta coquetelaria adota cachaça envelhecida, abrindo canal com bares e mixologistas globais", "Crescimento do gin artesanal disputa atenção do consumidor premium e espaço em gôndolas"], "summary": "Ambiente macro favorece venda do estoque a players capitalizados e estrangeiros, mas reformas, rastreabilidade MAPA e juros altos exigem tese forte de exportação premium e governança regulatória sólida.", "economic": ["SELIC 11,25% a.a. encarece crédito e restringe compradores alavancados para aquisição do estoque", "Câmbio USD/BRL 5,75 barateia ativos para grupos estrangeiros e pode acelerar ofertas estratégicas", "Crescimento +5% CAGR em spirits premium e PIB +2,9% sustentam tese de valorização da cachaça 12 anos"], "political": ["Estabilidade política moderada aumenta risco-percepção em M&A de ativos alcoólicos no Brasil", "Reforma tributária (IVA Dual) em transição até 2025 gera incerteza na carga sobre destilados", "Novas exigências de rastreabilidade do MAPA para exportação elevam custo e favorecem players estruturados"], "environmental": ["Preços elevados do vidro pressionam margens ou exigem repensar embalagens de menor custo/impacto", "Licenciamento ambiental obrigatório pode alongar due diligence e travar compradores mais avessos a risco", "Cana-de-açúcar com preços estáveis reduz volatilidade de custo da matéria-prima no curto prazo"], "technological": ["Adoção tecnológica média em destilados permite diferenciar com rastreabilidade digital de barris 12 anos", "Exigências de rastreabilidade MAPA podem virar vantagem se Fogo da Cana já tiver controles modernos", "Baixa sofisticação digital do setor abre espaço para e-commerce direto do estoque envelhecido"]}'::jsonb, '{"summary": "Mercado premium de cachaça é atrativo porém competitivo; o estoque 12 anos é ativo escasso, mas poucos compradores globais concentram poder. Maximizar preço exige leilão competitivo, tese financeira robusta e uso intenso de dados e IA para Reach global.", "buyer_power": "Compradores têm poder alto: SELIC 11,25% encarece crédito e força vendedor; ativos brasileiros baratos em USD/BRL 5,75 fortalecem grupos globais. Consumo premium resiliente, mas poucos compradores estratégicos podem impor desconto no múltiplo.", "supplier_power": "Poder de fornecedores é médio: cana estável reduz pressão de custo, mas vidro caro eleva CAPEX de envase. Com cadeia normalizada, impacto é limitado no estoque já envelhecido, favorecendo venda em granel com menor dependência de embalagem.", "disruption_ai_data": "Disrupção por IA/dados é média: adoção tecnológica setorial é “média”, mas IA em e-commerce, CRM e precificação pode ampliar demanda global pelo estoque. Se Fogo da Cana não usar dados para Reach/valuation, compradores capturam todo o upside.", "threat_substitutes": "Substitutos fortes: gin artesanal e whiskies premium disputam gôndola e coquetelaria; grandes players globais de spirits usam portfólios amplos para deslocar cachaça. Em cenário de “beber menos, melhor”, o share da categoria limita prêmio de preço.", "competitive_rivalry": "Rivalidade alta: mercado premium (+5% CAGR) atrai gigantes lançando edições extra-premium; M&A ativo (Campari, Diageo) pressiona valuation da Fogo da Cana, exigindo diferenciação via estoque 12 anos e prêmios internacionais.", "threat_new_entrants": "Ameaça de entrantes é baixa: barreiras de 12 anos de envelhecimento e novas exigências MAPA/rotulagem desincentivam cópias rápidas. Reforma tributária e licenças ambientais elevam custo, tornando o estoque atalho raro para players de spirits.", "buyer_power_intensity": "Alta", "overall_attractiveness": "Média", "strategic_implications": ["Ancorar valuation no tempo de barreira (12 anos) e na economia de CAPEX/juros (SELIC 11,25%), mostrando via laudos que o estoque substitui investimento futuro dos compradores.", "Montar data room com séries de análises MAPA, prêmios e histórico de produção, suportado por modelagem de demanda global (+5% CAGR premium) usando dados e IA para justificar múltiplos.", "Acionar processo competitivo internacional (Campari, Diageo, importadores) via advisors, reduzindo poder de barganha individual e explorando câmbio USD/BRL 5,75 favorável ao investidor estrangeiro.", "Estruturar formatos flexíveis de transação: venda total, lotes em granel e JV de marca com bartenders e canais de exportação, monetizando estoque mesmo diante de alta rivalidade e substitutos."], "supplier_power_intensity": "Média", "disruption_ai_data_intensity": "Média", "threat_substitutes_intensity": "Alta", "competitive_rivalry_intensity": "Alta", "power_partnerships_ecosystems": "Parcerias têm poder alto: IG de cachaça, consórcios de exportação e alianças com mixologia/bares de alta renda ampliam Reach global. Com +5% CAGR no premium, co-branding com grupos como Campari/Diageo pode destravar prêmio sobre o estoque.", "threat_new_entrants_intensity": "Baixa", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": ""}'::jsonb, '{"roadmap": ["Curto Prazo (3-6 meses): Finalizar dossiê regulatório, contratar assessor de M&A com reach global, mapear 10-15 potenciais compradores estratégicos.", "Médio Prazo (6-12 meses): Executar roadshow internacional, estruturar leilão competitivo, negociar LOIs com piso de valor definido.", "Longo Prazo (12+ meses): Fechar transação principal ou executar plano B (tokenização + vendas fracionadas B2B) para garantir liquidez parcial."], "key_findings": ["O estoque 12 anos deve ser posicionado como ativo financeiro escasso, não apenas produto de consumo, para atrair múltiplos perfis de compradores.", "Processo de venda competitivo (leilão estruturado) é essencial para evitar poder de barganha concentrado em poucos players.", "Tese de exportação premium com governança regulatória sólida é o principal driver de valuation para compradores internacionais."], "main_findings": ["FORÇA: Estoque de 12 anos em carvalho é barreira temporal irreplicável, com qualidade atestada por premiações internacionais.", "FRAQUEZA: Marca subvalorizada e dependência de canais de nicho limitam alcance a compradores estratégicos globais.", "OPORTUNIDADE: Câmbio alto torna ativos brasileiros atrativos para grupos estrangeiros (Diageo, Campari, Pernod Ricard).", "AMEAÇA: Juros altos e poucos compradores concentram poder de barganha, risco de desconto relevante sobre os R$ 70M."], "important_notes": ["Dossiê regulatório MAPA é pré-requisito para qualquer deal de exportação ou M&A com grupo internacional.", "Sem processo competitivo estruturado, compradores únicos impõem desconto de 30-50% sobre valor justo.", "Tokenização e leilões exigem estruturação jurídica específica (CVM, contratos internacionais)."], "central_challenge": "Monetizar R$ 70M em estoque de cachaça 12 anos em cenário de juros altos e poucos compradores globais, evitando desconto forçado e maximizando recuperação do capital investido.", "executive_summary": "A Fogo da Cana possui ativo raro e premiado (estoque 12 anos em carvalho), mas enfrenta baixa visibilidade global e mercado concentrado de compradores. A estratégia deve transformar o estoque em classe de ativo colecionável/financeiro, acessando múltiplos canais (leilões globais, tokenização, white-label B2B) para criar competição entre compradores e maximizar valuation de saída.", "strategic_priorities": ["Estruturar dossiê completo: rastreabilidade MAPA, certificações, laudos e histórico de premiações.", "Lançar processo competitivo global: roadshow com Diageo, Campari, Pernod Ricard e fundos de ativos alternativos.", "Preparar canais alternativos de monetização: leilões, tokenização e contratos white-label B2B."], "consistency_validation": {"flags": ["Capacidade interna para M&A global não confirmada - requer assessor especializado externo.", "Estruturação jurídica para tokenização e leilões internacionais não está endereçada - risco de atraso.", "Valuation de R$ 70M é aspiracional; mercado pode precificar entre R$ 25-50M sem competição estruturada.", "Ausência de OKRs definidos impede mensuração de progresso - recomenda-se definir metas trimestrais."], "legal_alignment": false, "capacity_alignment": false, "financial_alignment": true, "overall_realism_score": 6}, "overall_recommendation": "Não aceitar ofertas unilaterais. Criar competição entre compradores via processo estruturado é a única forma de aproximar-se dos R$ 70M. Preparar plano B de monetização fracionada para garantir piso de recuperação."}'::jsonb, '{"sam": "", "som": "", "tam": "", "cagr": "", "summary": "", "assumptions": null, "confidence_level": 0, "calculation_notes": "", "estimation_method": ""}'::jsonb, '{"summary": "Competidores convertem prestígio em escala e preço; Fogo da Cana tem líquido e estoque, mas carece de marca e canais.", "best_practices": ["Estratégia de marca forte com storytelling regional e prêmios, como Weber Haus e Vale Verde.", "Diversificação de canais: e-commerce robusto, clubes, duty free e exportação estruturada.", "Gestão ativa de portfólio com edições limitadas e pricing premium ancorado em escassez."], "performance_gaps": ["Marca pouco conhecida frente a Weber Haus, Magnífica e Vale Verde no segmento premium.", "Baixa presença digital e distribuição limitada, reduzindo velocidade para monetizar estoque.", "Ausência de narrativa forte de luxo e colecionismo que justifique valuation de R$70M."], "competitors_analyzed": ["Weber Haus", "Magnífica", "Vale Verde"]}'::jsonb, '{"raise": ["Posicionamento como ativo financeiro lastreado em estoque", "Transparência via dados, IA e rastreabilidade em tempo real", "Exposição global a fundos, family offices e grupos de spirits"], "create": ["Plataforma de leilões digitais globais do estoque 12 anos", "Veículo de investimento estruturado em barris tokenizados", "Parcerias white-label para blends ultra-premium co-branded"], "reduce": ["Foco em vendas unitárias de garrafas premium", "Complexidade operacional fabril própria", "Gastos dispersos com marketing de varejo"], "summary": "Transformar o estoque 12 anos em classe de ativo colecionável, financeiro e estratégico, vendendo via leilões globais, estruturação tokenizada e deals white‑label com grandes grupos, em vez de competir só como marca de cachaça premium.", "eliminate": ["Venda passiva limitada a compradores locais", "Dependência de distribuidores tradicionais", "Narrativa apenas de destilaria artesanal"], "new_value_curve": "De produtora regional de cachaça para plataforma global de ativos líquidos raros."}'::jsonb, '{"summary": "Usar a autoridade do estoque 12 anos para atrair B2B global, provar demanda, fechar contratos em volume e elevar valuation.", "leap_loop": {"name": "LEAP Loop", "type": "acquisition", "steps": ["Land: Atrair connoisseurs e compradores B2B via PR, mídia especializada, degustações e ABM no LinkedIn.", "Engage: Nutrir leads com storytelling do envelhecimento 12 anos, tours virtuais, reviews e lives com bartenders.", "Activate: Oferecer kit degustação limitado + frete reduzido ou amostras B2B em troca de pedido teste ou reunião.", "Propagate: Programa de indicação p/ mixologistas e clientes VIP + collabs com bares premiados e clubes de assinatura."], "metrics": ["CAC B2C", "CAC B2B", "Visitantes qualificados/mês", "CTR das campanhas", "Taxa degustação→pedido", "Coeficiente viral (K)", "Leads B2B internacionais", "Leads de potenciais compradores M&A"], "bottleneck": "Baixa geração de leads B2B internacionais qualificados para testar volume relevante do estoque 12 anos."}, "scale_loop": {"name": "SCALE Loop", "type": "monetization", "steps": ["Satisfy: Entregar experiência premium: embalagem colecionável, ficha técnica, premiações e suporte à coquetelaria.", "Convert: Upsell de garrafas raras e barris fracionados; contratos B2B de fornecimento e venda antecipada de lotes.", "Loop Back: Clube de membros e contratos sazonais com bares/importadores, garantindo calendário de recompra.", "Expand: Vender direitos exclusivos por região, private label premium e lotes p/ blends de grupos globais."], "metrics": ["NPS / CSAT", "Ticket médio B2C", "Ticket médio B2B", "LTV por segmento", "Taxa de recompra (90/180 dias)", "Receita de upsell/cross-sell", "Receita em contratos recorrentes", "Margem bruta por lote vendido"], "bottleneck": "Dependência de vendas pontuais; poucos contratos recorrentes em volume que acelerem a saída do estoque 12 anos."}}'::jsonb, '{"realist": {"name": "Cenário Realista", "description": "SELIC fica ao redor de 11% em 2025, crédito caro limita compradores financeiros, mas players estratégicos capitalizados seguem ativos. Mercado premium cresce ~5% a.a., porém disputa com gin artesanal pressiona espaço. Câmbio perto de 5,75 favorece exportação granel. Estoque de 12 anos é atrativo, mas desconto sobre os R$ 70M é provável.", "probability": 60, "required_actions": ["Adotar estratégia dual track: negociar venda do controle e, em paralelo, venda parcial do estoque em granel para blends internacionais.", "Obter laudos independentes de avaliação de estoque e de qualidade sensorial para sustentar preço mínimo.", "Modelar estruturas flexíveis (earn-out, opção de recompra de marca, contratos de fornecimento de longo prazo).", "Reforçar governança regulatória (MAPA, ambiental, rastreabilidade) para reduzir riscos percebidos em due diligence."]}, "summary": "O principal risco é ser forçado a vender o estoque de 12 anos em ambiente de juros altos, incerteza tributária e demanda premium pressionada, levando a desconto relevante sobre os R$ 70M. Preparar dossiê regulatório robusto, múltiplos canais de monetização do líquido e piso de valor claro aumenta o poder de barganha em qualquer cenário macro.", "optimistic": {"name": "Cenário Otimista", "description": "SELIC cai para 9%, IPCA converge à meta e câmbio permanece perto de USD/BRL 5,75, mantendo ativos brasileiros baratos. Premiumização acelera (+5% CAGR), acordo Mercosul‑UE reduz tarifas e MAPA estabiliza regras de rastreabilidade. Grupos como Diageo/Campari buscam estoques envelhecidos, elevando múltiplos e permitindo venda próxima aos R$ 70M.", "probability": 20, "required_actions": ["Rodar processo competitivo de M&A com assessoria especializada, priorizando players globais (Diageo, Campari, Pernod).", "Certificar rastreabilidade e conformidade MAPA/UE, com dossiê técnico bilíngue do estoque de 12 anos.", "Estruturar pacote de ativos: venda conjunta de marca + estoque + know-how para maximizar valuation.", "Criar edições limitadas super premium para provar preço por garrafa e reforçar tese de escassez."]}, "pessimistic": {"name": "Cenário Pessimista", "description": "SELIC sobe para 13%, IPCA encosta em 6% e risco fiscal aumenta. Reforma tributária gera insegurança sobre IVA de bebidas, atrasando M&As. Exigências de rastreabilidade MAPA encarecem compliance. Luxo desacelera, gin artesanal ganha share. Compradores exigem forte desconto, forçando venda parcial ou alongamento do horizonte de saída.", "probability": 20, "required_actions": ["Montar plano de sobrevivência de 3–5 anos, priorizando caixa e venda gradual do estoque em lotes menores, inclusive B2C premium.", "Negociar dívida estruturada ou securitização lastreada em estoque, com covenants claros, para evitar venda em liquidação.", "Readequar mix: reduzir custos fixos industriais, terceirizar etapas não críticas e focar em rótulos de maior margem.", "Buscar parceria com player nacional para co-branding e escoamento do líquido em blended brands menos sensíveis a preço."]}, "mitigation_tactics": ["Formalizar piso de preço por litro e cenários de corte (R$ mínimo aceitável) antes das negociações, para evitar concessões emocionais sob pressão macroeconômica.", "Investir imediatamente em dossiê regulatório e de rastreabilidade MAPA completo, reduzindo risco de contingências e descontos em due diligence.", "Diversificar canais de saída do estoque (M&A total, venda de blocos para blends, private label, edições limitadas direto ao consumidor).", "Manter relacionamento ativo com bancos de investimento e boutiques de M&A focadas em bebidas, mapeando constantemente apetite de compradores estratégicos globais."], "early_warning_signals": ["Trajetória da SELIC e Focus: cortes consistentes rumo a 9–10% favorecem cenário otimista; alta para >12% indica viés pessimista.", "Andamento da Reforma Tributária (IVA Dual) e definições específicas para bebidas alcoólicas, incluindo carga e créditos.", "Novas normas do MAPA sobre rastreabilidade e rotulagem de cachaça envelhecida, bem como sinais concretos sobre o acordo Mercosul‑UE."]}'::jsonb, '{"summary": "BSC foca em monetizar o estoque 12 anos como ativo global via M&A, leilões, tokenização e parcerias white-label, alinhando finanças, clientes, processos e capacidades internas.", "customer": ["Atrair compradores estratégicos globais de spirits premium", "Posicionar estoque como ativo colecionável raro e seguro"], "financial": ["Maximizar valor de venda do estoque 12 anos em R$ ou USD", "Gerar liquidez via M&A, leilões globais e deals white-label"], "learning_growth": ["Desenvolver competência em finanças estruturadas e tokenização", "Criar rede de advisors M&A, jurídico e tributário especializada"], "internal_processes": ["Estruturar processos para leilões internacionais e compliance", "Desenhar estrutura legal e fiscal para tokenização do estoque"]}'::jsonb, '{"score": "", "summary": "", "criteria": null, "alternatives": null, "review_cycle": {"frequency": "", "extraordinary_triggers": null}, "score_comparison": "", "monitoring_metrics": null, "recommended_option": "", "final_recommendation": "", "priority_recommendations": null}'::jsonb, 'completed', NULL, 257214, false, false, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-29 03:12:36.685196+00'::timestamptz, '2025-11-29 03:16:53.787967+00'::timestamptz, '2025-11-29 03:16:53.641287+00'::timestamptz, NULL)
