INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('349ac99a-9e69-4622-8927-a6a4b33c1c90', '22ef2079-68a1-4922-a1cf-c8f677a735dc', 'f8f9d78c-b3f5-4847-9f7b-e3bab4f1dcf4', NULL, '{"summary": "A Fogo da Cana possui um ativo valioso (cachaça 12 anos) com potencial de venda a grandes players, impulsionado por cenário externo. Desafia a liquidez e a valorização da marca, exigindo estratégia de M&A focada.", "threats": [{"source": "fato", "content": "Desafios regulatórios e fiscais (Reforma Tributária, IN MAPA) exigem atenção.", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Concorrência de destilados premium nacionais (Gin artesanal) e importados.", "confidence": "Média"}, {"source": "estimativa", "content": "Risco de desvalorização do ativo caso a venda demore ou não se concretize.", "confidence": "Média"}, {"source": "estimativa", "content": "Custos de manutenção do estoque e infraestrutura até a venda.", "confidence": "Baixa"}], "strengths": [{"source": "fato", "content": "Estoque único de cachaça 12 anos, alta barreira de entrada e valorização.", "confidence": "Alta"}, {"source": "fato", "content": "Qualidade do produto atestada por premiações internacionais.", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Reconhecimento da cachaça como IG e tendência de premiumização global.", "confidence": "Média"}, {"source": "estimativa", "content": "Potencial de uso em mixologia de alta coquetelaria, ampliando mercado.", "confidence": "Baixa"}], "weaknesses": [{"source": "análise de mercado", "content": "Marca ''Fogo da Cana'' subvalorizada em relação ao ativo de R$ 70M.", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Desafio de liquidez para venda do estoque de R$ 70M sem escala global.", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Dependência de canais de nicho para distribuição atual.", "confidence": "Média"}, {"source": "estimativa", "content": "Não especificado o tamanho da empresa/equipe para gerir venda complexa.", "confidence": "Baixa"}], "opportunities": [{"source": "análise de mercado", "content": "Câmbio favorável à exportação, atraindo compradores estrangeiros.", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Juros altos favorecem quem tem caixa para aquisições estratégicas.", "confidence": "Média"}, {"source": "análise de mercado", "content": "Aquisição por grandes players (Diageo, Campari) que buscam ativos premium.", "confidence": "Média"}, {"source": "estimativa", "content": "Parcerias estratégicas para distribuição e acesso a novos mercados.", "confidence": "Baixa"}]}'::jsonb, '{"legal": ["Novas exigências de rastreabilidade MAPA para exportação: Impacta processos e custos para acesso a mercados externos.", "Regras mais rígidas para rotulagem ''Envelhecida'': Exige conformidade rigorosa, valorizando a autenticidade da Fogo da Cana.", "Instrução Normativa MAPA sobre padrões de identidade: Garante qualidade e tipicidade da cachaça, protegendo o produto."], "social": ["Premiumização (beber menos, beber melhor): Alinha-se diretamente ao produto envelhecido de alta qualidade da Fogo da Cana.", "Reconhecimento internacional da Cachaça: Aumenta valor percebido e demanda por produtos premium como o da Fogo da Cana.", "Sentimento do consumidor resiliente para luxo/premium: Garante mercado para cachaça de 12 anos, apesar da retração geral."], "summary": "A Fogo da Cana, com seu estoque de cachaça envelhecida de 12 anos, está em um ponto estratégico. O cenário econômico com juros altos e câmbio favorável à exportação cria um ambiente propício para aquisições por grandes players. A premiumização e o reconhecimento internacional da cachaça reforçam o valor do ativo. Desafios regulatórios e fiscais exigem atenção, mas a qualidade do produto é um diferencial.", "economic": ["SELIC 11.25% a.a. (restritivo): Encarece crédito, favorecendo compradores estratégicos com caixa para aquisição.", "USD/BRL 5.75 (favorece exportação): Torna ativos brasileiros atraentes para grupos estrangeiros e impulsiona vendas externas.", "Cenário de juros altos: Desafia liquidez para manter estoque e infraestrutura, pressionando a venda."], "political": ["Reforma Tributária (IVA Dual) em transição: Impacto incerto na precificação e competitividade da cachaça premium.", "Estabilidade Política Moderada: Atenção ao fiscal pode afetar confiança de investidores e consumo de luxo.", "Acordo Mercosul-UE: Potencial redução de tarifas para exportação, abrindo novos mercados para Fogo da Cana."], "environmental": ["Licenciamento Ambiental: Requisito de compliance que pode gerar custos e atrasos se não estiver em dia.", "Sustentabilidade na produção: Crescente demanda por práticas ESG, influenciando percepção e valor da marca.", "Preços da cana-de-açúcar estáveis: Garante custo de matéria-prima previsível para a produção contínua."], "technological": ["Tecnologia de controle de qualidade moderno: Essencial para manter padrão de excelência e certificações internacionais.", "Média adoção tecnológica no setor: Foco em tradição, mas exige modernização para rastreabilidade e eficiência.", "Inovação em mixologia de alta coquetelaria: Cria demanda por cachaças envelhecidas, como as da Fogo da Cana."]}'::jsonb, '{"summary": "A Fogo da Cana possui um ativo único (estoque de 12 anos) com alta barreira de entrada. O cenário econômico favorece compradores estratégicos. A empresa enfrenta rivalidade e substitutos, mas tem grande potencial em parcerias e exportação. O desafio é monetizar o valor do estoque.", "buyer_power": "Poder de compradores Médio. Consumidor premium é resiliente, mas juros altos (SELIC 11.25%) e inflação (IPCA 4.5%) podem impactar o poder de compra. Compradores estratégicos (conglomerados) têm caixa e são favorecidos pelo câmbio alto (USD/BRL 5.75) para aquisições.", "supplier_power": "Poder de fornecedores Baixo. Cana-de-açúcar tem preços estáveis. O vidro (embalagem) com preços elevados impacta custos, mas não compromete a produção principal da cachaça envelhecida, cujo valor está no tempo e estoque.", "disruption_ai_data": "Disrupção por IA/Dados Baixa. A indústria foca em tradição e qualidade. Tecnologia é mais para controle de qualidade. IA/dados podem otimizar logística ou marketing digital, mas não alteram o core do negócio de cachaça envelhecida, que é o tempo e o processo artesanal.", "threat_substitutes": "Ameaça de substitutos Média. O crescimento do Gin artesanal nacional compete diretamente pelo share de gôndola premium e atenção do consumidor. Outros destilados premium importados também são concorrentes indiretos, embora a cachaça tenha um nicho cultural forte.", "competitive_rivalry": "Rivalidade Média. Fogo da Cana atua em nicho premium, competindo com Weber Haus e 51 Reserva. Grandes marcas lançam edições limitadas extra-premium, elevando a barra. O mercado artesanal é fragmentado, mas a presença de players fortes exige diferenciação contínua.", "threat_new_entrants": "Ameaça de novos entrantes Baixa. O tempo de envelhecimento de 12 anos é uma barreira de entrada quase intransponível a curto prazo. Regulamentações do MAPA e certificações de origem também elevam o custo e complexidade para novos players no segmento premium.", "buyer_power_intensity": "Média", "overall_attractiveness": "Média", "strategic_implications": ["Focar em M&A com conglomerados globais (Diageo, Campari) que buscam destilados locais premium, aproveitando o câmbio favorável (USD/BRL 5.75) e o cenário de juros altos que favorece compradores com caixa.", "Alavancar o estoque envelhecido de 12 anos como diferencial competitivo e barreira de entrada, utilizando-o como principal ativo na negociação de venda da empresa ou do estoque em massa.", "Explorar ativamente parcerias para exportação, visando o mercado europeu com o potencial Acordo Mercosul-UE e capitalizando o reconhecimento internacional da cachaça como Indicação Geográfica.", "Investir em marketing e posicionamento da marca para elevar seu valor percebido e competir com edições limitadas de grandes players, mitigando a ameaça de substitutos como o Gin artesanal."], "supplier_power_intensity": "Baixa", "disruption_ai_data_intensity": "Baixa", "threat_substitutes_intensity": "Média", "competitive_rivalry_intensity": "Média", "power_partnerships_ecosystems": "Poder de parcerias Alto. A premiumização e o reconhecimento internacional da cachaça (Indicação Geográfica) abrem portas para alianças estratégicas e distribuição global. Acordo Mercosul-UE pode reduzir tarifas, favorecendo exportação via parcerias.", "threat_new_entrants_intensity": "Baixa", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": "Plano de 90 dias focado na estruturação da oferta e prospecção inicial de compradores B2B para o estoque de cachaça envelhecida, preparando a Fogo da Cana para uma transação de alto valor e futura expansão premium.", "plan_90_days": [{"focus": "Fundação", "month": "Mês 1", "objective": "Estruturar a oferta de venda do estoque envelhecido e preparar a marca para prospecção B2B.", "investment": "R$ 35-50 mil", "key_results": ["Completar 100% do prospecto detalhado do estoque (laudos, certificações, volume).", "Identificar e qualificar 50+ contatos de grandes players globais de bebidas (M&A/Compras).", "Desenvolver 1 pitch deck de venda B2B focado no ativo de luxo e potencial de blend/marca própria."], "aligned_recommendation": "Estruturação de Oferta para Venda de Estoque Envelhecido (Bulk)"}, {"focus": "Crescimento", "month": "Mês 2", "objective": "Iniciar a prospecção ativa de compradores B2B e fortalecer o posicionamento premium da marca.", "investment": "R$ 40-60 mil", "key_results": ["Realizar 10+ reuniões iniciais com potenciais compradores internacionais (Diageo, Pernod Ricard, Campari).", "Lançar 1 campanha de marketing digital focada no storytelling da cachaça 12 anos para B2B/premium.", "Obter 3+ leads qualificados para parcerias de co-branding ou joint venture."], "aligned_recommendation": "Estruturação de Oferta para Venda de Estoque Envelhecido (Bulk)"}, {"focus": "Consolidação", "month": "Mês 3", "objective": "Avançar nas negociações B2B e solidificar a percepção de luxo da marca Fogo da Cana.", "investment": "R$ 50-70 mil", "key_results": ["Apresentar 3+ propostas formais de venda de estoque para players globais.", "Participar de 1 feira internacional de destilados (virtual ou presencial, se viável) para networking B2B.", "Desenvolver 1 plano de ação para otimização da venda direta em canais premium (e-commerce, empórios)."], "aligned_recommendation": "Otimização da Venda Direta e Canais de Distribuição Premium"}], "success_metrics": ["Número de propostas de venda de estoque formalizadas.", "Número de reuniões com C-level de grandes conglomerados de bebidas.", "Engajamento e alcance das campanhas de marketing B2B/premium."], "execution_phases": {"scale": {"focus": "Fechamento de Negócios e Expansão de Canais", "duration": "Meses 7-12", "objectives": ["Concluir a venda de parte ou totalidade do estoque envelhecido.", "Estabelecer parcerias de distribuição internacional e/ou co-branding.", "Otimizar e escalar a venda direta em canais premium."], "key_results": ["1+ contrato de venda de estoque ou parceria estratégica assinado.", "3+ distribuidores internacionais parceiros para a linha premium.", "Aumento de 20% nas vendas diretas online da cachaça 12 anos em mercados-alvo."], "prerequisites": ["Validação bem-sucedida da Fase 2 (LOI/MOU em andamento ou piloto de venda direta promissor).", "Métricas de engajamento e interesse do mercado B2B/premium atingidas."], "investment_range": "R$ 180-300 mil"}, "foundation": {"focus": "Estruturação e Prospecção Inicial", "duration": "Meses 1-3", "objectives": ["Preparar a Fogo da Cana para uma transação de alto valor.", "Identificar e engajar os primeiros potenciais compradores/parceiros."], "key_results": ["100% dos materiais de venda B2B (prospecto, pitch deck) concluídos e aprovados.", "50+ contatos de M&A/Compras de grandes players globais mapeados e contatados.", "15+ reuniões iniciais com potenciais compradores/parceiros realizadas."], "investment_range": "R$ 125-180 mil", "capacity_requirements": {"team": "1 Gerente de Projeto (interno/externo), 1 Analista de M&A/Mercado, 1 Designer/Marketing", "dependencies": ["Acesso a dados de estoque e laudos de qualidade", "Aprovação da diretoria para estratégias de preço e negociação", "Suporte jurídico para contratos e regulamentações de exportação"], "skills_needed": ["Análise Financeira e de Mercado", "Negociação Internacional", "Marketing Estratégico B2B", "Jurídico (Contratos Internacionais)"]}}, "validation": {"focus": "Negociação e Validação de Mercado", "duration": "Meses 4-6", "objectives": ["Avançar negociações com os leads mais promissores para venda de estoque.", "Testar a receptividade do mercado premium à marca Fogo da Cana em canais diretos."], "key_results": ["2+ Termos de Confidencialidade (NDAs) assinados com potenciais compradores.", "1+ Carta de Intenções (LOI) ou Memorando de Entendimento (MOU) em negociação.", "Lançamento de 1 piloto de venda direta online para o produto 12 anos em mercado-alvo (ex: EUA/Europa)."], "prerequisites": ["Fase 1 concluída (prospecto, pitch, contatos iniciais)", "Pelo menos 3 propostas de venda de estoque em análise por players globais."], "investment_range": "R$ 100-180 mil"}}, "total_investment": "R$ 125-180 mil", "capacity_assessment": {"blockers": ["Complexidade e duração do processo de M&A/venda de ativos.", "Dependência de consultoria externa especializada em M&A e jurídico internacional.", "Disponibilidade da diretoria para reuniões e decisões estratégicas."], "team_readiness": "Média", "budget_adequacy": "Suficiente", "stakeholder_alignment": "Alinhado"}}'::jsonb, '{"roadmap": ["Curto Prazo (3-6 meses): Estruturar oferta e iniciar prospecção B2B.", "Médio Prazo (6-12 meses): Expandir presença internacional e parcerias.", "Longo Prazo (12+ meses): Concluir venda e explorar novos mercados."], "key_findings": ["O estoque de cachaça é um ativo de luxo com alta barreira de entrada.", "O cenário econômico atual favorece compradores com caixa.", "Necessidade de maximizar a valorização da marca."], "main_findings": ["Estoque de cachaça envelhecida de alto valor agregado.", "Desafio de liquidez e marca subvalorizada.", "Cenário econômico favorável para exportação e premiumização.", "Riscos regulatórios e fiscais que exigem atenção."], "important_notes": ["Necessidade de parcerias estratégicas para venda.", "Monitoramento constante do macro-ambiente é crucial.", "Liquidez pode ser um desafio crítico."], "central_challenge": "Vender o estoque de cachaça envelhecida de 12 anos para recuperar o investimento de R$ 70M.", "executive_summary": "Fogo da Cana deve reposicionar seu estoque de cachaça envelhecida como um ativo de luxo global, explorando canais B2B exclusivos e experiências premium. O foco é atrair grandes investidores e conglomerados de bebidas, aproveitando o cenário econômico favorável à exportação e premiumização do produto.", "strategic_priorities": ["Reforçar o posicionamento premium.", "Expandir canais de venda B2B.", "Atração de investidores estratégicos."], "consistency_validation": {"legal_alignment": true, "capacity_alignment": true, "financial_alignment": true, "overall_realism_score": 8}, "overall_recommendation": "Foco em valorização do estoque e atração de investidores estratégicos."}'::jsonb, '{"sam": "R$ 200M - 400M", "som": "R$ 2M - 10M", "tam": "R$ 4.0B - 6.0B", "cagr": "+5% a.a. (baseado em: Mercado Premium, Macro-Contexto)", "summary": "Mercado de cachaças premium no Brasil é robusto, com Fogo da Cana posicionado para capturar fatia significativa do segmento ultra-premium devido ao estoque envelhecido.", "assumptions": ["TAM: Mercado total de bebidas destiladas premium no Brasil (ABRABE, Expocachaça).", "SAM: 5-7% do TAM representa o segmento de cachaças envelhecidas ultra-premium (MAPA, ABRABE).", "SOM: 0.5-2.5% do SAM para player de nicho com estoque único (Análise de concorrentes)."], "som_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 4M - 7M", "market_share": "1.0% - 1.8%"}, "optimistic": {"probability": 20, "value_range": "R$ 7M - 10M", "market_share": "1.8% - 2.5%"}, "conservative": {"probability": 30, "value_range": "R$ 2M - 4M", "market_share": "0.5% - 1.0%"}}, "tam_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 4.8B - 5.5B"}, "optimistic": {"probability": 20, "value_range": "R$ 5.5B - 6.0B"}, "conservative": {"probability": 30, "value_range": "R$ 4.0B - 4.8B"}}, "confidence_level": 65, "calculation_notes": "Extrapolação do mercado de destilados premium e cachaças envelhecidas no Brasil, com base em dados setoriais e comparativo com concorrentes.", "data_sources_used": {"proxy_calculations": ["Estimativa de mercado de destilados premium no Brasil", "Participação de cachaças envelhecidas no segmento premium", "Market share de players de nicho com produtos de alto valor agregado"], "benchmark_extrapolations": ["Growth rate do mercado premium (+5% CAGR)"]}, "estimation_method": "proxy_concorrentes", "baseline_recommendation": "realistic"}'::jsonb, '{"summary": "Fogo da Cana possui um ativo valioso (estoque envelhecido), mas enfrenta desafios de liquidez e reconhecimento de marca. Competidores como Weber Haus e Velho Barreiro (Premium) demonstram o potencial de valorização no segmento. A empresa deve focar em estratégias de M&A e branding para capitalizar seu diferencial.", "best_practices": ["Aproveitar o estoque envelhecido como barreira de entrada e diferencial competitivo único.", "Utilizar premiações internacionais para fortalecer a narrativa de qualidade e valor da marca.", "Focar em M&A com grandes players globais para valorizar o ativo e expandir o alcance."], "performance_gaps": ["Marca subvalorizada vs. qualidade/valor do estoque envelhecido. Potencial de branding inexplorado.", "Dependência de canais de nicho. Expansão para distribuição global/conglomerados é crucial.", "Desafio de liquidez para R$70M. Necessidade de estratégia de saída clara e compradores estratégicos."], "competitors_analyzed": ["Weber Haus", "Cachaça Velho Barreiro (Linhas Premium)", "Cachaça 51 (Reserva/Exportação)", "Magnífica", "Vale Verde"]}'::jsonb, '{"raise": ["Percepção de exclusividade e luxo da cachaça envelhecida.", "Parcerias estratégicas com redes de hotéis e restaurantes de luxo.", "Presença em leilões e eventos internacionais de bebidas finas."], "create": ["Experiências imersivas de ''Cachaça de Colecionador'' com tours e degustações.", "Plataforma global B2B para venda de estoque a grandes grupos de bebidas.", "Programa de ''Apadrinhamento de Barris'' com acesso exclusivo e NFTs."], "reduce": ["Custos de estoque de produtos com giro lento.", "Dependência de mercado interno e flutuações econômicas.", "Esforços em canais de venda com baixa margem."], "summary": "Reinventar Fogo da Cana como um ativo de luxo global, vendendo o estoque de 12 anos através de canais exclusivos B2B e experiências premium, atraindo investidores e grandes conglomerados de bebidas.", "eliminate": ["Produção de cachaças jovens de baixo valor agregado.", "Marketing genérico focado em volume de vendas.", "Distribuição pulverizada em pequenos varejistas."], "new_value_curve": "Foco em exclusividade, experiência e valor de investimento, transformando cachaça em ativo de luxo global e oportunidade de M&A."}'::jsonb, '{"summary": "Estratégia focada em atrair grandes investidores e compradores de nicho para o estoque premium, maximizando o valor via negociação direta e expansão global.", "leap_loop": {"name": "LEAP Loop", "type": "acquisition", "steps": ["Land: Atrair investidores/compradores estratégicos via M&A e connoisseurs de cachaça.", "Engage: Apresentar o valor do estoque e prêmios, degustações exclusivas e storytelling da marca.", "Activate: Negociação direta, ofertas personalizadas, due diligence facilitada.", "Propagate: Testemunhos de compradores, mídia especializada, eventos de alto padrão."], "metrics": ["Leads Qualificados (M&A/HNI)", "Taxa de Engajamento (Propostas)", "Taxa de Conversão (Vendas/Acordos)"], "bottleneck": "Identificação e acesso a compradores estratégicos/investidores com capital."}, "scale_loop": {"name": "SCALE Loop", "type": "monetization", "steps": ["Satisfy: Entrega de produto premium, experiência de compra exclusiva e suporte pós-venda.", "Convert: Venda direta do estoque (B2B/B2C) ou participação acionária na empresa.", "Loop Back: Programas de fidelidade para compradores B2C, parcerias B2B de longo prazo.", "Expand: Lançar edições limitadas, co-branding com marcas de luxo, exportação direta."], "metrics": ["LTV (B2C/B2B)", "Receita por Cliente/Acordo", "Receita de Expansão (Novos Mercados)"], "bottleneck": "Liquidez e escala para monetizar R$ 70M do estoque de forma eficiente."}}'::jsonb, '{"realist": {"name": "Cenário Realista: Venda Parcial do Estoque ou Busca por Sócio", "description": "Juros altos (SELIC 11.25%) limitam o capital de risco. O câmbio USD/BRL 5.75 atrai, mas a instabilidade política modera o apetite. A Fogo da Cana negocia a venda de parte do estoque envelhecido para um blended whiskey/cachaça ou atrai um sócio estratégico com capital para expansão e que possa valorizar o ativo em R$ 70M a longo prazo. O crescimento do mercado premium (+5% CAGR) sustenta o interesse, mas o valor total é um desafio de liquidez.", "probability": 60, "required_actions": ["Segmentar o estoque: oferecer lotes menores para blenders e lotes premium para engarrafamento próprio.", "Elaborar um pitch detalhado sobre o potencial de valorização do estoque restante e da marca.", "Focar em investidores estratégicos do setor de bebidas que buscam ativos de maturação longa.", "Otimizar a estrutura de custos para aumentar a rentabilidade e atrair investidores."]}, "summary": "A Fogo da Cana possui um ativo valioso (estoque de cachaça 12 anos), mas o desafio de liquidez para um valuation de R$70M é significativo. O cenário atual de juros altos e câmbio favorável cria oportunidades para compradores estratégicos com caixa, mas também riscos de desvalorização se a venda não for concretizada. A estratégia deve focar na valorização do ativo, diversificação de saídas e monitoramento constante do macro-ambiente para maximizar a recuperação do investimento.", "optimistic": {"name": "Cenário Otimista: Aquisição Estratégica e Valorização", "description": "Juros em queda (SELIC abaixo de 9%), impulsionando o crédito e o apetite por M&A. Um grande player global (Diageo/Pernod Ricard) adquire a Fogo da Cana, reconhecendo o valor do estoque de 12 anos e a tendência de premiumização, pagando próximo ao valuation de R$70M. A Reforma Tributária (IVA Dual) simplifica exportações, e o Acordo Mercosul-UE reduz tarifas, abrindo novos mercados.", "probability": 20, "required_actions": ["Preparar due diligence completa e data room para potenciais compradores internacionais.", "Intensificar networking com bancos de investimento e consultorias especializadas em M&A de bebidas.", "Destacar certificações de origem e conformidade com novas exigências MAPA para exportação.", "Explorar parcerias estratégicas para distribuição internacional imediata após a aquisição."]}, "pessimistic": {"name": "Cenário Pessimista: Dificuldade na Venda e Desvalorização", "description": "Juros permanecem altos, câmbio desfavorável (USD/BRL abaixo de 5.00), e a instabilidade fiscal aumenta. A Reforma Tributária gera incerteza. A competição do gin artesanal cresce, e os preços do vidro continuam elevados. A falta de compradores estratégicos dispostos a pagar R$70M força a venda do estoque a preços menores ou a liquidação gradual, recuperando apenas parcialmente o investimento.", "probability": 20, "required_actions": ["Reavaliar o valuation de R$70M e considerar cenários de venda com desconto.", "Desenvolver um plano de vendas diretas e e-commerce robusto para monetizar o estoque de forma gradual.", "Buscar financiamento alternativo (ex: securitização do estoque) para aliviar a pressão de caixa.", "Explorar nichos de mercado (alta coquetelaria) para maximizar o valor unitário da cachaça premium."]}, "mitigation_tactics": ["Diversificar canais de venda: além do M&A, fortalecer e-commerce e exportação direta para reduzir dependência de um único comprador.", "Otimizar a gestão do estoque: implementar estratégias de rotação e precificação dinâmica para diferentes segmentos (blend vs. garrafa premium).", "Construir valor de marca: investir em marketing e storytelling para aumentar o reconhecimento da ''Fogo da Cana'' e justificar o preço premium.", "Monitorar ativamente o cenário econômico e regulatório: ajustar estratégias de venda e precificação conforme mudanças na SELIC, câmbio e legislação tributária/MAPA."], "early_warning_signals": ["Variações na taxa SELIC (queda indica maior apetite por aquisições, alta dificulta).", "Movimentações de M&A de grandes players (Diageo, Campari) no setor de destilados no Brasil.", "Alterações na taxa de câmbio USD/BRL (câmbio alto favorece compradores estrangeiros).", "Mudanças na legislação tributária ou regulamentações do MAPA sobre exportação de cachaça."]}'::jsonb, '{"summary": "Reinventar Fogo da Cana como ativo de luxo global, vendendo estoque de 12 anos via B2B e experiências premium para atrair investidores e conglomerados, recuperando R$ 70M.", "customer": ["Atrair investidores e conglomerados de bebidas", "Estabelecer parcerias B2B exclusivas"], "financial": ["Maximizar valor de venda da empresa/estoque", "Recuperar R$ 70M de investimento"], "learning_growth": ["Capacitar equipe em negociação M&A/B2B", "Pesquisar mercados de luxo global"], "internal_processes": ["Otimizar gestão do estoque de cachaça", "Desenvolver canais de venda B2B premium"]}'::jsonb, '{"score": "8.2/10", "summary": "O dilema da Fogo da Cana exige uma estratégia multifacetada que capitalize no seu ativo mais valioso: o estoque de cachaça envelhecida. A venda total da empresa é complexa e demorada, com alto risco de desvalorização em um mercado de M&A restritivo. A venda parcial do estoque (bulk) para grandes players oferece a melhor combinação de recuperação de investimento, menor risco e tempo de execução. Complementarmente, a valorização da marca através de canais premium e a prospecção de parcerias estratégicas criam saídas adicionais e fortalecem a posição da empresa. O ciclo de revisão trimestral, com gatilhos extraordinários, garantirá a agilidade necessária para adaptar a estratégia às condições de mercado. Próximos passos incluem a contratação de consultoria especializada em M&A e jurídico para estruturar as ofertas e negociações.", "criteria": ["Potencial de Recuperação do Investimento (ROI)", "Risco de Mercado e Jurídico", "Tempo para Conclusão da Transação"], "alternatives": ["Venda Total da Empresa (Fogo da Cana)", "Venda Parcial do Estoque de Cachaça Envelhecida (Bulk/Granel)", "Parceria Estratégica / Joint Venture"], "review_cycle": {"frequency": "Trimestral", "extraordinary_triggers": ["Mudança regulatória >10% custo", "Bloqueio de licenciamento", "Decisão judicial relevante", "Falha de compliance LGPD/setorial", "Entrada de competidor relevante", "Variação cambial superior a 5% em um mês", "Recebimento de proposta de aquisição formal", "Alteração significativa na taxa SELIC"]}, "score_comparison": "+18% acima da segunda opção", "monitoring_metrics": ["Volume de Cachaça Envelhecida Vendida (litros)", "Receita Gerada pela Venda de Estoque (R$)", "Número de Contatos Qualificados com Potenciais Compradores/Parceiros", "Crescimento da Receita de E-commerce / Venda Direta", "Margem de Lucro por Litro Vendido", "Custo de Aquisição de Cliente (CAC) para canais premium", "Taxa de Conversão de Propostas em Negócios Fechados"], "recommended_option": "Venda Parcial do Estoque de Cachaça Envelhecida (Bulk/Granel)", "final_recommendation": "A melhor opção é focar na venda estratégica e fracionada do estoque de cachaça envelhecida, aproveitando seu alto valor intrínseco e o cenário macroeconômico favorável para compradores com caixa. Esta abordagem minimiza riscos e maximiza a recuperação do investimento, enquanto se explora a valorização da marca.", "priority_recommendations": [{"title": "Estruturação de Oferta para Venda de Estoque Envelhecido (Bulk)", "budget": "R$150-250k (Consultoria M&A, Jurídico, Marketing)", "priority": 1, "timeline": "6-9 meses", "description": "Elaborar um prospecto detalhado do estoque de cachaça envelhecida (12 anos), incluindo laudos de qualidade, certificações, volume disponível e condições de venda. Prospectar ativamente grandes players globais de bebidas (Diageo, Pernod Ricard, Campari) ou destilarias de whisky/rum que buscam diversificar seus portfólios com um destilado premium brasileiro para blends ou engarrafamento sob marca própria. Foco em contratos de médio a longo prazo para escoamento gradual.", "legal_feasibility": {"risk_level": "Baixo", "requires_legal_opinion": false, "regulatory_dependencies": ["Contratos de compra e venda internacional", "Regulamentação de exportação (MAPA, Receita Federal)", "Requisitos de rastreabilidade"], "requires_statutory_change": false}}, {"title": "Otimização da Venda Direta e Canais de Distribuição Premium", "budget": "R$80-120k (Marketing Digital, Eventos, Design)", "priority": 2, "timeline": "9-12 meses", "description": "Reforçar a marca ''Fogo da Cana'' no mercado premium e de luxo, explorando canais de e-commerce, empórios gourmet e distribuidores especializados em bebidas finas. Participar de feiras internacionais de destilados para aumentar a visibilidade e buscar parcerias de distribuição em mercados-chave (EUA, Europa). Desenvolver storytelling da marca focado na exclusividade do envelhecimento e qualidade premiada. Esta ação valoriza o ativo remanescente e a marca, preparando para futuras negociações.", "legal_feasibility": {"risk_level": "Baixo", "requires_legal_opinion": false, "regulatory_dependencies": ["Legislação de publicidade de bebidas alcoólicas", "Regulamentação de e-commerce", "Contratos de distribuição"], "requires_statutory_change": false}}, {"title": "Prospecção de Parceria Estratégica para Co-Branding ou Joint Venture", "budget": "R$40-60k (Consultoria Jurídica e de Negócios)", "priority": 3, "timeline": "12-18 meses", "description": "Identificar empresas com forte presença no mercado de destilados premium ou luxo que possam se interessar em uma parceria de co-branding para uma linha ultra-premium ou uma joint venture para exploração do estoque envelhecido. Esta alternativa permite diluir o risco e o investimento, aproveitando a expertise de um parceiro para escalar a distribuição e o marketing, mantendo parte do controle e valorização do ativo. Avaliar a viabilidade de uma ''marca secundária'' para o estoque, licenciando-o.", "legal_feasibility": {"risk_level": "Médio", "mitigation_plan": "Parecer jurídico aprofundado sobre a estrutura da parceria, cláusulas de saída e proteção de propriedade intelectual. Definição clara de responsabilidades e divisão de lucros.", "requires_legal_opinion": true, "regulatory_dependencies": ["Contratos de parceria/JV", "Acordos de licenciamento de marca", "Aspectos societários"], "requires_statutory_change": false}}]}'::jsonb, 'completed', NULL, 40757, false, false, false, 'Y3S0VVCK', '2025-11-29 03:14:39.422189+00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-29 03:13:27.211923+00'::timestamptz, '2025-11-29 03:14:39.422189+00'::timestamptz, '2025-11-29 03:14:07.599956+00'::timestamptz, NULL)
