-- Row 24/36: 7d8db8b2-ed64-4dc5-8ad4-3299d5ae38c4
INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('7d8db8b2-ed64-4dc5-8ad4-3299d5ae38c4', 'a54a62d6-02cb-4192-a023-44c8b5b29a6c', '8f97e6a4-7e09-4915-b390-7f1b6fff6e6e', NULL, '{"summary": "Startup ágil com proposta diferenciada, mas PMF não validado é risco crítico. Janela de oportunidade em PMEs exige execução rápida antes da comoditização.", "threats": [{"source": "análise de mercado", "content": "Comoditização acelerada de LLMs comprime margens e reduz diferenciação técnica", "confidence": "Alta"}, {"source": "fato", "content": "Big Techs integrando IA nativamente (Copilot, Gemini) capturam mercado enterprise", "confidence": "Alta"}, {"source": "fato", "content": "Volatilidade cambial (USD/BRL ~5.80) eleva custos de APIs e infraestrutura cloud", "confidence": "Alta"}, {"source": "análise de mercado", "content": "PMEs cautelosas com OpEx exigem ROI em <6 meses, dificultando ciclo de vendas", "confidence": "Média"}], "strengths": [{"source": "fato", "content": "Agilidade de startup permite pivots rápidos e adaptação ao feedback de mercado", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Proposta de governança estratégica contínua diferencia de wrappers genéricos de IA", "confidence": "Média"}, {"source": "fato", "content": "Liderança técnica com visão clara de produto (plataforma de inteligência em tempo real)", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Timing favorável: entrada antes da comoditização completa do mercado de IA B2B", "confidence": "Média"}], "weaknesses": [{"source": "fato", "content": "Ausência de Product-Market Fit validado - risco crítico de burn rate sem tração", "confidence": "Alta"}, {"source": "fato", "content": "Marca desconhecida em mercado onde confiança é barreira de entrada principal", "confidence": "Alta"}, {"source": "fato", "content": "Modelo de negócios indefinido dificulta precificação e projeções de receita", "confidence": "Alta"}, {"source": "estimativa", "content": "Estrutura de capital limitada (bootstrapping) restringe velocidade de go-to-market", "confidence": "Média"}], "opportunities": [{"source": "análise de mercado", "content": "Nicho PME carente de soluções de IA acessíveis com ROI demonstrável", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Compliance antecipado ao Marco Legal de IA como diferencial competitivo", "confidence": "Média"}, {"source": "estimativa", "content": "Parcerias com consultorias e contadores para distribuição escalável em PMEs", "confidence": "Média"}, {"source": "análise de mercado", "content": "Mercado brasileiro líder em adoção de IA na LatAm (+20% CAGR)", "confidence": "Alta"}]}'::jsonb, '{"legal": ["LGPD impõe RIPD obrigatório para sistemas de IA com dados pessoais; compliance by design é requisito, não diferencial", "ISO/IEC 42001 (Gestão de IA) emerge como padrão; certificação futura pode ser barreira de entrada ou selo de confiança", "Classificação de risco para IA e transparência algorítmica em discussão; arquitetura deve permitir auditabilidade nativa"], "social": ["Brasil lidera adoção de IA generativa na LatAm; mercado educado reduz ciclo de vendas mas aumenta exigência de diferenciação", "Desemprego em mínima histórica (6.4%) aquece mercado de talentos tech; retenção de desenvolvedores será desafio crítico", "PMEs buscam democratização de inteligência estratégica antes restrita a grandes consultorias; timing favorável para proposta"], "summary": "Cenário favorável para IA B2B no Brasil, mas alta volatilidade cambial e juros pressionam custos. Regulação de IA iminente exige compliance by design. Diferenciação crítica ante comoditização de LLMs. Foco em ROI rápido para PMEs cautelosas.", "economic": ["SELIC 11.25% a.a. encarece capital; bootstrapping exige foco em receita recorrente rápida e unit economics positivo desde MVP", "Dólar USD/BRL ~5.80 eleva custos de APIs (OpenAI, Azure) e GPUs; precificação deve absorver volatilidade cambial", "Empresas buscam ROI rápido em OpEx; proposta de valor deve demonstrar payback < 6 meses para conquistar PMEs cautelosas"], "political": ["Marco Legal de IA (PL 2338/2023) em tramitação no Senado pode criar barreiras regulatórias ou vantagem competitiva para early adopters", "Reforma Tributária em regulamentação gera incerteza fiscal para startups; modelo de negócio deve prever cenários tributários distintos", "Estabilidade política moderada com atenção ao cenário fiscal pode impactar investimentos em tecnologia e captação de recursos"], "environmental": ["Consumo energético de IA sob escrutínio global; transparência em pegada de carbono pode ser diferencial ESG para clientes B2B", "Tendência Privacy-first AI alinha-se com demanda por processamento local/soberano; oportunidade de posicionamento green-tech", "Pressão por sustentabilidade em cadeias de fornecedores pode criar demanda por dashboards ESG integrados à plataforma"], "technological": ["Comoditização de LLMs (GPT Wrappers) acelera; diferenciação exige camada proprietária de dados ou workflow especializado", "Hiperautomação e IA Generativa B2B são trends validados; posicionamento como ''governança estratégica'' evita competição direta", "Custos de nuvem AWS/Azure crescentes; arquitetura deve prever otimização de inferência e possível uso de modelos open-source"]}'::jsonb, '{"summary": "Mercado de IA brasileiro é atrativo (+20% CAGR) mas intensamente competitivo. ImensIAH enfrenta alta rivalidade de wrappers e Big Techs, compradores exigentes por ROI rápido, e baixas barreiras técnicas. Oportunidade está em nicho PME com plataforma de governança estratégica contínua, diferenciando-se por dados proprietários, compliance antecipado e parcerias de distribuição. Urgente: validar PMF com early adopters antes da comoditização completa do mercado.", "buyer_power": "Alta: empresas cautelosas com OpEx, exigem ROI rápido. SELIC 11.25% encarece capital. PMEs sensíveis a preço. Necessário modelo de precificação baseado em valor entregue, não em horas ou tokens.", "supplier_power": "Média-Alta: dependência de APIs (OpenAI, Anthropic) com custos flutuantes. GPUs caras (dólar R$5.80). Cloud AWS/Azure com preços crescentes. Mitigação: arquitetura multi-modelo e otimização de custos de inferência.", "disruption_ai_data": "Crítica: Brasil lidera adoção de IA na LatAm (+20% CAGR). Sovereign AI e Privacy-first são tendências. Regulação PL 2338 exigirá transparência algorítmica. Quem dominar governança de dados terá vantagem competitiva sustentável.", "threat_substitutes": "Média-Alta: comoditização de LLMs acelera. Ferramentas no-code (Zapier, Make) e IA nativa em ERPs/CRMs substituem soluções pontuais. Diferencial: inteligência estratégica contínua vs. automação genérica.", "competitive_rivalry": "Alta rivalidade: explosão de GPT Wrappers e integração nativa de IA por Big Techs (Copilot, Gemini). Mercado fragmentado em serviços, mas dominado em infra. Consultorias (Accenture, Deloitte) adquirindo boutiques. Diferenciação por nicho PME é crítica.", "threat_new_entrants": "Alta: barreira técnica inicial baixa (APIs públicas). Qualquer desenvolvedor cria wrapper em dias. Barreira real: confiança, dados proprietários e compliance LGPD/PL 2338. Vantagem para quem construir moat de dados.", "buyer_power_intensity": "Alta", "overall_attractiveness": "Média", "strategic_implications": ["Construir moat de dados proprietários focado em PMEs brasileiras para criar barreira defensável contra entrantes", "Desenvolver modelo de precificação baseado em outcomes (ROI mensurável) para superar resistência de compradores cautelosos", "Estabelecer parcerias estratégicas com ERPs/contabilidades para PMEs, reduzindo CAC e acelerando distribuição", "Antecipar compliance PL 2338/LGPD como diferencial competitivo, posicionando-se como solução ''Privacy-first'' e transparente"], "supplier_power_intensity": "Média", "disruption_ai_data_intensity": "Alta", "threat_substitutes_intensity": "Média", "competitive_rivalry_intensity": "Alta", "power_partnerships_ecosystems": "Alta relevância: ecossistema de IA exige parcerias (integradores, ERPs, contadores). Oportunidade em white-label para consultorias. ISO 42001 como diferencial de confiança. Alianças aceleram GTM e reduzem CAC.", "threat_new_entrants_intensity": "Alta", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": "Plano 90 dias focado em validar PMF com 8-10 pilotos pagos, estruturar compliance como diferencial e testar pricing baseado em ROI. Investimento R$50-76k.", "plan_90_days": [{"focus": "Fundação", "month": "Mês 1", "objective": "Estruturar bases jurídicas, operacionais e iniciar prospecção de pilotos pagos com PMEs selecionadas", "investment": "R$ 12-18 mil", "key_results": ["Contratos e termos de uso LGPD-compliant validados por advogado especializado", "Pipeline de 15-20 PMEs qualificadas em varejo/serviços profissionais mapeadas", "3 reuniões de apresentação realizadas com potenciais pilotos pagos"], "aligned_recommendation": "Programa de Pilotos Pagos com 5-10 PMEs Selecionadas"}, {"focus": "Crescimento", "month": "Mês 2", "objective": "Converter primeiros pilotos pagos e iniciar desenvolvimento do framework de compliance antecipado", "investment": "R$ 18-28 mil", "key_results": ["3-5 contratos de piloto assinados (R$2-5k/mês cada)", "Parecer jurídico sobre PL 2338/2023 contratado e em andamento", "Dashboard de ROI básico implementado para acompanhamento dos pilotos"], "aligned_recommendation": "Framework de Compliance Antecipado (PL 2338/2023 + LGPD)"}, {"focus": "Consolidação", "month": "Mês 3", "objective": "Validar modelo de pricing baseado em ROI e consolidar 8-10 clientes pagantes com cases documentados", "investment": "R$ 20-30 mil", "key_results": ["8-10 clientes pagantes ativos gerando MRR de R$20-40k", "Calculadora de ROI transparente lançada e testada com 5 clientes", "2 case studies completos com métricas de ROI comprovado documentados"], "aligned_recommendation": "Modelo de Pricing Baseado em ROI Mensurável"}], "success_metrics": ["8-10 clientes pagantes ativos ao final dos 90 dias", "MRR entre R$20-40k validando disposição de pagamento", "NPS mínimo de 40 entre clientes piloto indicando product-market fit inicial"], "execution_phases": {"scale": {"focus": "Expansão controlada e construção de barreiras competitivas", "duration": "Meses 7-12", "objectives": ["Escalar para 50-80 clientes ativos", "Desenvolver dados proprietários como moat competitivo", "Buscar captação seed se necessário para acelerar"], "key_results": ["50-80 clientes ativos com MRR R$150-250k", "Base de dados proprietária com insights de 50+ empresas", "Captação seed de R$1-2M (se estratégia de crescimento acelerado)"], "prerequisites": ["Unit economics validados (LTV/CAC > 3)", "Processo de vendas replicável documentado", "Equipe mínima estruturada (4-6 pessoas)"], "investment_range": "R$ 200-400 mil"}, "foundation": {"focus": "Estruturação jurídica, primeiros pilotos e validação de proposta de valor", "duration": "Meses 1-3", "objectives": ["Estabelecer infraestrutura legal e operacional compliant", "Validar hipótese de valor com 8-10 clientes pagantes", "Documentar aprendizados e ajustar oferta"], "key_results": ["Contratos e políticas LGPD aprovados", "8-10 pilotos pagos ativos", "2 case studies com ROI mensurável"], "investment_range": "R$ 50-76 mil", "capacity_requirements": {"team": "2-3 pessoas dedicadas (fundador + 1-2 apoios)", "dependencies": ["Advogado especializado em tech/LGPD", "Acesso a decisores de PMEs nos setores-alvo"], "skills_needed": ["Vendas consultivas B2B", "Desenvolvimento de produto/IA", "Conhecimento jurídico básico (ou terceirizado)"]}}, "validation": {"focus": "Pilotos expandidos e refinamento do modelo de negócios", "duration": "Meses 4-6", "objectives": ["Expandir base para 20-25 clientes pagantes", "Validar unit economics (CAC, LTV, churn)", "Lançar framework de compliance como diferencial de marketing"], "key_results": ["20-25 clientes ativos com MRR R$60-100k", "LTV/CAC > 3 validado", "Churn mensal < 5%"], "prerequisites": ["Mínimo 5 clientes pagantes satisfeitos (NPS > 30)", "Framework de compliance v1 documentado", "Modelo de pricing testado com feedback"], "investment_range": "R$ 80-120 mil"}}, "total_investment": "R$ 50-76 mil", "capacity_assessment": {"blockers": ["Orçamento bootstrapping limita velocidade de go-to-market", "Marca desconhecida exige esforço extra em credibilidade inicial", "Dependência de contratação de apoio jurídico especializado"], "team_readiness": "Média", "budget_adequacy": "Limitado", "stakeholder_alignment": "Alinhado"}}'::jsonb, '{"roadmap": ["Curto Prazo (0-3 meses): Fechar 8-10 pilotos pagos, validar ICP e pricing, estruturar compliance básico. Meta: R$30-50k MRR.", "Médio Prazo (3-9 meses): Escalar para 50+ clientes, automatizar onboarding, construir dados proprietários como moat. Meta: R$150k MRR.", "Longo Prazo (9-18 meses): Expandir para verticais adjacentes, parcerias de distribuição (contabilidades, ERPs), buscar seed round. Meta: R$500k MRR."], "key_findings": ["Mercado favorável mas hipercompetitivo: diferenciação por dados proprietários brasileiros e acompanhamento contínuo é viável, porém requer validação rápida.", "ICP ideal: PMEs tech (50-200 funcionários) com dor de governança estratégica e orçamento para SaaS — nicho suficiente para PMF inicial.", "Modelo freemium com expansão por módulos permite entrada com baixa fricção e upsell baseado em ROI comprovado."], "main_findings": ["FORÇA: Proposta única de governança estratégica viva com monitoramento em tempo real, escapando do oceano vermelho de wrappers genéricos de IA.", "FRAQUEZA: PMF não validado e marca desconhecida em mercado onde confiança é crítica — risco existencial se não corrigido em 90 dias.", "OPORTUNIDADE: PMEs brasileiras buscam ROI rápido em automação; compliance antecipado e dados proprietários locais criam barreiras de switching.", "AMEAÇA: Comoditização acelerada de LLMs + Big Techs integrando IA nativamente podem erodir diferenciação antes da escala."], "important_notes": ["Investimento de R$50-76k exige ao menos 3-4 pilotos pagos para breakeven — validar pricing urgentemente.", "Marco Legal de IA (PL 2338/2023) pode virar vantagem competitiva se compliance for implementado antes dos concorrentes.", "SELIC 11,25% e dólar volátil pressionam custos de API — precificar com margem de segurança cambial."], "central_challenge": "Validar Product-Market Fit em mercado de IA em rápida comoditização, diferenciando-se como plataforma de governança estratégica contínua antes que a janela de oportunidade se feche (90 dias críticos).", "executive_summary": "ImensIAH tem proposta diferenciada (Strategic-Ops-as-a-Service) em mercado aquecido (+20% CAGR), mas enfrenta corrida contra comoditização de LLMs e PMF não validado. Janela de 90 dias para provar valor tangível com 8-10 pilotos pagos em PMEs tech. Investimento R$50-76k viável se pricing baseado em ROI demonstrável. Compliance antecipado (Marco Legal IA/LGPD) é diferencial defensável. Execução rápida é imperativa.", "strategic_priorities": ["Validar PMF com 8-10 pilotos pagos em PMEs tech nos próximos 90 dias.", "Implementar compliance by design (LGPD + Marco Legal IA) como diferencial competitivo.", "Definir pricing baseado em ROI mensurável com trial de valor rápido (< 30 dias)."], "consistency_validation": {"flags": ["Equipe de 1-5 pessoas pode não suportar 8-10 pilotos simultâneos — considerar priorizar 5 pilotos de alta qualidade ou contratar suporte.", "Receita pré-operacional exige que primeiros pilotos sejam pagos (mesmo que com desconto) para validar willingness-to-pay real.", "Custos de API em dólar não estão claramente mitigados no modelo de pricing — risco de margem negativa se câmbio disparar."], "legal_alignment": true, "capacity_alignment": false, "financial_alignment": true, "overall_realism_score": 7}, "overall_recommendation": "Executar sprint de 90 dias focado exclusivamente em validação de PMF com PMEs tech. Cada semana sem cliente pagante aumenta risco de comoditização. Compliance antecipado e dados locais são os únicos moats defensáveis — priorizá-los desde o dia zero."}'::jsonb, '{"sam": "R$ 850M - 1.5B", "som": "R$ 4.2M - 15M", "tam": "R$ 8.5B - 12.5B", "cagr": "+20-25% a.a. (baseado em: IDC LatAm AI Market + macro_context growth_rate)", "summary": "Mercado de IA para PMEs em expansão (R$850M-1.5B SAM). Oportunidade real mas competitiva. SOM conservador R$2-4M viável em 3 anos. Diferenciação crítica: governança estratégica contínua vs. ferramentas pontuais.", "assumptions": ["Mercado IA Brasil 2024: R$8-12B (IDC/Gartner LatAm, +20% CAGR setor)", "PMEs representam ~10% do gasto em IA B2B (proxy: 6.4M PMEs SEBRAE)", "Plataformas SaaS estratégicas capturam 0.5-1% do SAM em 3 anos (benchmark)"], "sam_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 850M - 1.5B"}, "optimistic": {"probability": 20, "value_range": "R$ 1.5B - 2.2B"}, "conservative": {"probability": 30, "value_range": "R$ 600M - 850M"}}, "som_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 4.2M - 15M", "market_share": "0.5-1%"}, "optimistic": {"probability": 20, "value_range": "R$ 15M - 37M", "market_share": "1-2.5%"}, "conservative": {"probability": 30, "value_range": "R$ 2M - 4.2M", "market_share": "0.3-0.5%"}}, "tam_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 8.5B - 12.5B"}, "optimistic": {"probability": 20, "value_range": "R$ 12.5B - 18B"}, "conservative": {"probability": 30, "value_range": "R$ 6.5B - 8.5B"}}, "caveat_message": "⚠️ Confidence 45%: Estimativas baseadas em benchmarks setoriais e proxies. Recomenda-se validação com pesquisa primária de mercado (entrevistas com 50+ PMEs) antes de decisões de investimento. Mercado de ''inteligência estratégica para PMEs via IA'' ainda emergente - poucos dados diretos disponíveis.", "confidence_level": 45, "calculation_notes": "TAM: Mercado IA Brasil (SaaS+Serviços B2B). SAM: Segmento PMEs buscando inteligência estratégica/automação. SOM: Market share realista startup early-stage em 3 anos.", "data_sources_used": {"direct_data": ["Gartner/IDC Tech Trends Brazil (macro_context)", "SEBRAE - 6.4M PMEs no Brasil"], "proxy_calculations": ["PMEs = ~10% do mercado B2B de IA (proxy por número de empresas)", "Ticket médio SaaS estratégico PME: R$500-2000/mês"], "benchmark_extrapolations": ["SaaS B2B Brasil: TAM R$50-80B, IA representa ~15-20%", "Startups early-stage: 0.5-1% market share em 3 anos (benchmark VC)"]}, "estimation_method": "benchmark_setorial", "baseline_recommendation": "conservative"}'::jsonb, '{"summary": "ImensIAH enfrenta competição em três frentes: SaaS de automação (Zapier/Make) com escala e preço acessível; consultorias estabelecidas com credibilidade e metodologias; e startups ágeis de IA. O diferencial proposto (governança estratégica contínua para PMEs) é único, mas requer validação urgente. Gaps críticos: ausência de PMF, marca desconhecida e modelo de negócio indefinido. Recomendação: adotar práticas de onboarding simplificado dos SaaS, metodologia proprietária das consultorias, e foco vertical das startups bem-sucedidas. Prioridade imediata: validar proposta com 10-20 PMEs piloto antes de investir em escala.", "best_practices": ["Zapier/Make: Onboarding self-service com freemium, reduzindo CAC e acelerando adoção em PMEs", "Consultorias líderes: Metodologias proprietárias certificadas (ISO 42001) que geram confiança e justificam premium", "Startups IA exitosas: Foco vertical inicial (1 nicho) antes de expandir, garantindo PMF antes de escalar"], "performance_gaps": ["Ausência de marca estabelecida e cases de sucesso documentados vs. consultorias com portfólio consolidado", "Falta de PMF validado enquanto concorrentes SaaS já possuem milhões de usuários e métricas claras de retenção", "Modelo de precificação indefinido vs. competidores com pricing transparente e escalável (Zapier: $19-$799/mês)"], "competitors_analyzed": ["Zapier/Make (SaaS Automação)", "Agências de IA Boutique (Brasil)", "Consultorias de Transformação Digital", "Startups de IA Generativa locais"]}'::jsonb, '{"raise": ["Inteligência contextual brasileira (dados locais, LGPD, regulação)", "Frequência de insights estratégicos (de trimestral para tempo real)", "Transparência algorítmica e rastreabilidade de recomendações"], "create": ["Governança estratégica contínua como serviço (Strategic-Ops-as-a-Service)", "Alertas preditivos de mudanças de mercado e concorrência para PMEs", "Ecossistema de dados proprietários setoriais brasileiros"], "reduce": ["Complexidade técnica visível ao usuário PME (simplificar interface)", "Tempo de implementação inicial (de meses para dias)", "Custo de entrada para primeiros clientes (modelo freemium validador)"], "summary": "A ImensIAH escapa do oceano vermelho de wrappers genéricos criando uma categoria nova: Strategic-Ops-as-a-Service. Enquanto concorrentes vendem projetos de IA ou ferramentas de automação isoladas, a ImensIAH oferece governança estratégica viva — uma plataforma que não apenas gera planos, mas os monitora, detecta mudanças de cenário e propõe adaptações em tempo real. O diferencial está em três pilares: (1) dados proprietários do contexto brasileiro (regulação, mercado local, setores específicos), (2) compliance antecipado com Marco Legal de IA e LGPD como vantagem competitiva, e (3) modelo de acompanhamento contínuo que transforma PMEs em organizações estrategicamente adaptativas. Isso cria barreiras de switching através de dados acumulados e histórico decisório, fugindo da comoditização que ameaça soluções baseadas apenas em LLMs genéricos.", "eliminate": ["Projetos de IA pontuais e descontinuados (modelo consultoria tradicional)", "Dependência de APIs genéricas de Big Techs sem diferenciação", "Relatórios estratégicos estáticos e desatualizados em semanas"], "new_value_curve": "De consultoria pontual para copiloto estratégico contínuo: IA que monitora, alerta e adapta planos em tempo real para PMEs brasileiras."}'::jsonb, '{"summary": "Foco em nicho específico de PMEs tech para validar PMF, aquisição via conteúdo educativo e trial com valor rápido, monetização freemium com expansão por módulos e ROI demonstrável.", "leap_loop": {"name": "LEAP Loop", "type": "acquisition", "steps": ["Land: Conteúdo educativo sobre IA estratégica no LinkedIn + SEO para ''inteligência estratégica PME'' + parcerias com aceleradoras e contadores", "Engage: Diagnóstico estratégico gratuito de 5 min via chatbot no site + webinars semanais sobre desafios reais de PMEs com IA", "Activate: Trial de 14 dias com onboarding guiado + primeiro relatório estratégico personalizado entregue em 48h após cadastro", "Propagate: Programa ''Indique e Ganhe'' com mês grátis + cases de sucesso compartilháveis + badge ''Empresa Estratégica'' para clientes"], "metrics": ["CAC (Custo de Aquisição de Cliente)", "Taxa de Conversão Visitante→Trial", "Taxa de Ativação (Trial→Uso Ativo)", "Coeficiente Viral (K-factor)", "Tempo até Primeiro Valor (Time-to-Value)"], "bottleneck": "Validação do ICP: sem PMF definido, o funil atrai leads dispersos, aumentando CAC e reduzindo conversão. Priorizar nicho específico (ex: PMEs de serviços tech)."}, "scale_loop": {"name": "SCALE Loop", "type": "monetization", "steps": ["Satisfy: Entregar insights acionáveis semanais + alertas de mercado em tempo real + dashboard intuitivo com recomendações priorizadas", "Convert: Freemium com limite de alertas → Plano Pro (R$297/mês) com governança completa + Plano Enterprise com consultoria inclusa", "Loop Back: Check-ins mensais automatizados + relatórios de progresso + notificações de novas funcionalidades alinhadas ao desafio do cliente", "Expand: Upsell para módulos adicionais (concorrência, compliance) + seats extras para equipe + serviços de implementação estratégica"], "metrics": ["LTV (Lifetime Value)", "MRR (Receita Recorrente Mensal)", "Churn Rate (Taxa de Cancelamento)", "NRR (Net Revenue Retention)", "ARPU (Receita Média por Usuário)"], "bottleneck": "Demonstração de ROI tangível: PMEs precisam ver resultados financeiros claros em 30-60 dias para justificar assinatura. Criar métricas de impacto visíveis no dashboard."}}'::jsonb, '{"realist": {"name": "Cenário Realista", "description": "SELIC mantém-se em 11,25%, PMEs cautelosas exigem ROI em menos de 6 meses. Dólar oscila entre R$5,75-5,85, pressionando custos de nuvem. PL 2338/2023 avança lentamente, criando incerteza regulatória. Mercado saturado de wrappers força diferenciação por nicho. Desemprego baixo (6,4%) dificulta contratação técnica. Crescimento setorial de +20% existe, mas concentrado em grandes players.", "probability": 60, "required_actions": ["Definir ICP ultra-específico (ex: PMEs de serviços com 20-100 funcionários)", "Criar modelo de pricing baseado em resultado/ROI mensurável", "Desenvolver compliance by design para LGPD e futuro Marco de IA", "Estabelecer parcerias com consultorias para distribuição"]}, "summary": "ImensIAH opera em mercado de alto crescimento (+20% CAGR) mas enfrenta tríplice pressão: macroeconômica (SELIC 11,25%, dólar volátil), competitiva (comoditização de LLMs, Big Techs) e regulatória (PL 2338/2023 iminente). O cenário realista (60%) exige foco obsessivo em PMF com ICP específico, pricing baseado em ROI mensurável e compliance antecipado. A diferenciação via governança estratégica em tempo real é promissora, mas requer validação rápida com 5-10 pilotos pagos antes que a janela de oportunidade se feche. Prioridade zero: provar valor tangível para PMEs cautelosas em menos de 90 dias.", "optimistic": {"name": "Cenário Otimista", "description": "SELIC recua para 9% até 2025, liberando orçamento de PMEs para inovação. Marco Legal de IA aprovado com regras brandas favorece startups. Dólar estabiliza em R$5,40, reduzindo custos de APIs. Crescimento de IA LatAm acelera para +25% CAGR. ImensIAH captura early adopters com proposta de governança estratégica diferenciada, escapando da comoditização de GPT Wrappers.", "probability": 20, "required_actions": ["Acelerar captação pre-seed aproveitando janela de otimismo do mercado", "Fechar 5-10 pilotos pagos com PMEs para validar PMF rapidamente", "Investir em certificação ISO/IEC 42001 como diferencial competitivo"]}, "pessimistic": {"name": "Cenário Pessimista", "description": "SELIC sobe para 13% por pressão fiscal, congelando investimentos em inovação. Dólar dispara para R$6,50+, inviabilizando custos de API. Marco Legal de IA impõe classificação de risco rigorosa e RIPDs custosos. Big Techs (Microsoft Copilot, Google) dominam com IA nativa gratuita. Comoditização total de LLMs elimina margens. PMEs cortam gastos com tecnologia experimental.", "probability": 20, "required_actions": ["Pivotar para modelo de consultoria/serviços com menor dependência de APIs", "Reduzir burn rate ao mínimo, estender runway para 18+ meses", "Explorar parcerias com players maiores como canal de sobrevivência"]}, "mitigation_tactics": ["Arquitetura multi-modelo: diversificar fornecedores de LLM (OpenAI, Anthropic, modelos open-source) para reduzir dependência e negociar custos", "Compliance by design: implementar governança de dados e transparência algorítmica desde o MVP, antecipando exigências do PL 2338/2023", "Modelo de receita híbrido: combinar SaaS recorrente com success fees baseados em ROI comprovado para reduzir fricção de vendas", "Hedge cambial operacional: negociar contratos anuais com provedores de cloud em reais ou buscar alternativas locais (Oracle Cloud, Huawei)"], "early_warning_signals": ["Movimentação da SELIC acima de 12% ou abaixo de 10% - monitorar atas do COPOM mensalmente", "Votação do PL 2338/2023 no Senado - acompanhar pauta semanal e emendas propostas", "Anúncios de integração de IA gratuita por Big Techs (Microsoft 365, Google Workspace) - monitorar releases trimestrais", "Variação do USD/BRL acima de R$6,00 por mais de 30 dias consecutivos", "Aquisições de boutiques de IA brasileiras por consultorias (Accenture, Deloitte) - sinal de consolidação acelerada"]}'::jsonb, '{"summary": "O BSC alinha a busca por PMF com a proposta de Strategic-Ops-as-a-Service: financeiramente valida receita recorrente; em clientes, cria lock-in por valor acumulado; em processos, diferencia via compliance e monitoramento real-time; em aprendizado, constrói barreiras proprietárias de dados brasileiros.", "customer": ["Converter 10 PMEs em clientes-piloto com NPS >50 para validar Product-Market Fit", "Reduzir churn <5% através de switching costs por dados acumulados e histórico"], "financial": ["Atingir R$ 500k ARR em 18 meses validando modelo SaaS de governança estratégica", "Alcançar margem bruta >70% com receita recorrente de acompanhamento contínuo"], "learning_growth": ["Construir base proprietária de dados do contexto brasileiro (regulação/setores)", "Desenvolver capacidade de adaptação estratégica contínua na plataforma"], "internal_processes": ["Implementar motor de detecção de mudanças de cenário com alertas em tempo real", "Estruturar compliance LGPD e Marco Legal de IA como diferencial competitivo"]}'::jsonb, '{"score": "8.2/10", "summary": "A ImensIAH deve adotar a Estratégia de Validação Rápida por três razões críticas: (1) O cenário macroeconômico com SELIC alta torna PMEs avessas a investimentos sem ROI comprovado - pilotos pagos com garantia de 30 dias reduzem fricção; (2) A janela de oportunidade antes da comoditização completa de LLMs exige velocidade sobre perfeição - 90 dias para provar valor tangível; (3) O compliance antecipado ao PL 2338/2023 pode se tornar vantagem competitiva sustentável enquanto concorrentes ignoram regulação. Próximos passos imediatos: (a) Definir ICP específico em 7 dias (sugestão: PMEs de serviços profissionais com 20-100 funcionários); (b) Criar landing page de pilotos com proposta de valor clara em 14 dias; (c) Prospectar 30 empresas para converter 5 pilotos em 45 dias. Risco principal: dispersão de foco tentando atender múltiplos segmentos. Mitigação: disciplina obsessiva em um único ICP até atingir 10 clientes pagantes satisfeitos.", "criteria": ["Velocidade para Validação de PMF (Peso 40%)", "Eficiência de Capital / ROI em 90 dias (Peso 35%)", "Risco Regulatório e Jurídico (Peso 25%)"], "alternatives": ["Estratégia de Validação Rápida (Pilotos Pagos com PMEs)", "Estratégia de Plataforma SaaS Self-Service", "Estratégia de Parceria com Consultorias Estabelecidas"], "review_cycle": {"frequency": "Quinzenal nos primeiros 90 dias, depois Mensal", "extraordinary_triggers": ["Aprovação ou mudança significativa no PL 2338/2023", "Mudança regulatória que exija >10% de ajuste de custo operacional", "Falha de compliance LGPD ou incidente de dados", "Entrada de Big Tech (Microsoft/Google) com solução similar para PMEs Brasil", "Churn de >30% dos pilotos em qualquer mês", "Variação cambial USD/BRL >10% em 30 dias (impacto em custos de API)", "Decisão judicial relevante sobre responsabilidade de sistemas de IA"]}, "score_comparison": "+31% acima da segunda opção (Plataforma SaaS: 6.3/10)", "monitoring_metrics": ["Taxa de Conversão de Pilotos para Clientes Pagantes (%)", "Net Revenue Retention (NRR) mensal", "Time-to-Value: dias até cliente reportar primeiro ROI tangível", "CAC (Custo de Aquisição de Cliente) por canal", "NPS (Net Promoter Score) dos pilotos", "Burn Rate vs. Runway em meses", "Índice de Conformidade Regulatória (checklist PL 2338 + LGPD)"], "recommended_option": "Estratégia de Validação Rápida (Pilotos Pagos com PMEs)", "final_recommendation": "Priorizar validação rápida com 5-10 pilotos pagos em PMEs, pricing baseado em ROI mensurável e compliance antecipado como diferencial. Janela de oportunidade: 90 dias.", "priority_recommendations": [{"title": "Programa de Pilotos Pagos com 5-10 PMEs Selecionadas", "budget": "R$25-40k", "priority": 1, "timeline": "0-90 dias", "description": "Lançar programa estruturado de pilotos pagos (R$2-5k/mês) com PMEs em setores específicos (varejo, serviços profissionais, indústria leve). Foco em demonstrar ROI mensurável em até 30 dias através de dashboards de governança estratégica. Incluir cláusula de case study para validação social. Priorizar empresas com dor clara de tomada de decisão e disposição para feedback intensivo. Meta: 5 clientes pagantes em 60 dias, 10 em 90 dias.", "legal_feasibility": {"risk_level": "Baixo", "mitigation_plan": "Utilizar contratos de prestação de serviços padrão com cláusulas de confidencialidade e tratamento de dados. Template jurídico simples suficiente.", "requires_legal_opinion": false, "regulatory_dependencies": ["Adequação LGPD para coleta de dados empresariais", "Termos de uso e política de privacidade"], "requires_statutory_change": false}}, {"title": "Framework de Compliance Antecipado (PL 2338/2023 + LGPD)", "budget": "R$15-25k", "priority": 2, "timeline": "30-120 dias", "description": "Desenvolver framework interno de governança de IA alinhado ao PL 2338/2023 antes da aprovação. Criar documentação de transparência algorítmica, classificação de risco dos outputs e RIPD simplificado. Transformar compliance em diferencial competitivo: ''IA Responsável para PMEs''. Posicionar-se como referência em governança de IA antes que concorrentes se adaptem.", "legal_feasibility": {"risk_level": "Médio", "mitigation_plan": "Contratar parecer jurídico especializado em IA (R$5-8k) para validar framework. Estabelecer parceria com escritório de advocacia tech-focused para atualizações regulatórias trimestrais.", "requires_legal_opinion": true, "regulatory_dependencies": ["Monitoramento ativo do PL 2338/2023", "Adequação contínua à LGPD", "Possível necessidade de DPO"], "requires_statutory_change": false}}, {"title": "Modelo de Pricing Baseado em ROI Mensurável", "budget": "R$10-20k", "priority": 3, "timeline": "45-90 dias", "description": "Desenvolver calculadora de ROI transparente e modelo de precificação híbrido: fee fixo baixo (R$1-2k/mês) + success fee atrelado a métricas acordadas (economia de tempo em decisões, redução de reuniões improdutivas, velocidade de resposta a mudanças de mercado). Criar garantia de satisfação de 30 dias para reduzir fricção de entrada. Documentar casos de uso com ROI comprovado para escalar vendas.", "legal_feasibility": {"risk_level": "Baixo", "mitigation_plan": "Cláusulas contratuais claras sobre métricas de success fee e condições de garantia. Evitar promessas de resultado absoluto para mitigar risco de responsabilidade civil.", "requires_legal_opinion": false, "requires_statutory_change": false}}]}'::jsonb, 'completed', NULL, 166021, true, false, false, 'NN1RVPBI', '2025-11-28 14:26:25.274609+00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-28 13:24:20.400897+00'::timestamptz, '2025-11-28 15:51:25.660442+00'::timestamptz, '2025-11-28 15:51:25.377857+00'::timestamptz, NULL)
