-- Row 27/36: 777cdf77-4ffe-4757-b0a7-ee1f83c3cebb
INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('777cdf77-4ffe-4757-b0a7-ee1f83c3cebb', '06e024dd-8dbd-47a8-acb9-4a420f806a9a', 'e8908e08-c713-4847-a93b-b03113dede66', '8b2acd51-93de-46a0-ba94-dc2f952668bd', '{"summary": "Posição estratégica favorável para escala digital-first. Priorizar Social Commerce e B2B asset-light antes de franquias. Marca forte é ativo defensivo.", "threats": [{"source": "análise de mercado", "content": "CAC crescente no digital com competição intensa de Chilli Beans e marcas asiáticas", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Entrada de players asiáticos com logística local rápida e preços agressivos", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Consolidação de grandes redes ópticas pode reduzir espaço para marcas independentes", "confidence": "Média"}, {"source": "fato", "content": "Volatilidade do dólar e petróleo/acetato pode comprimir margens inesperadamente", "confidence": "Média"}], "strengths": [{"source": "fato", "content": "Identidade de marca diferenciada com posicionamento sustentável único no mercado de eyewear brasileiro", "confidence": "Alta"}, {"source": "fato", "content": "Maturidade digital elevada (8/10) com e-commerce Shopify otimizado e presença omnichannel validada", "confidence": "Alta"}, {"source": "fato", "content": "Estrutura bootstrapped garante controle estratégico e ausência de pressão de investidores externos", "confidence": "Alta"}, {"source": "fato", "content": "Presença física em pontos premium (Jardins, Iguatemi, Campos do Jordão) valida aceitação de mercado", "confidence": "Alta"}], "weaknesses": [{"source": "análise de mercado", "content": "Capital limitado para expansão física agressiva em cenário de SELIC 11,25% e crédito caro", "confidence": "Alta"}, {"source": "estimativa", "content": "Exposição cambial significativa (USD/BRL 5,80) impacta margens por dependência de importação", "confidence": "Média"}, {"source": "análise de mercado", "content": "Complexidade logística crescente para atender múltiplos canais (e-commerce, lojas, B2B)", "confidence": "Média"}, {"source": "estimativa", "content": "Falta de maturidade operacional documentada para modelo de franquias escalável", "confidence": "Média"}], "opportunities": [{"source": "análise de mercado", "content": "TikTok Shop e Social Commerce como canais de baixo CAPEX com alto potencial de conversão", "confidence": "Alta"}, {"source": "fato", "content": "Taxação de importações (Remessa Conforme) beneficia players locais contra dropshipping asiático", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Parcerias B2B asset-light com óticas e concept stores para escala física sem investimento próprio", "confidence": "Média"}, {"source": "estimativa", "content": "Regulamentação do mercado de carbono pode amplificar diferencial sustentável da marca", "confidence": "Baixa"}]}'::jsonb, '{"legal": ["LGPD exige governança de dados robusta: base de clientes e-commerce é ativo estratégico que requer proteção", "Normas ANVISA (UV400) e certificações de sustentabilidade são compliance obrigatório e diferencial de qualidade", "Modelo de franquias demanda estruturação jurídica complexa (COF, registro INPI): custo de entrada relevante"], "social": ["Consumidor cauteloso busca custo-benefício + propósito: posicionamento sustentável da Tuc é diferencial competitivo real", "Social Commerce (TikTok Shop/Pinterest) em alta: canal alinhado ao DNA digital da marca e ao público-alvo lifestyle", "Tendência Phygital exige integração on/off impecável: quiosques e loja física devem amplificar experiência digital"], "summary": "Cenário favorece foco digital (TikTok Shop, marketplaces) com expansão física seletiva. SELIC alta e dólar elevado penalizam lojas próprias. Diferencial sustentável é ativo estratégico. Franquias exigem maturidade operacional prévia.", "economic": ["SELIC 11.25% a.a. encarece capital: expansão via lojas próprias/franquias demanda maior ROI para viabilidade financeira", "Dólar ~R$5.80 pressiona custos de importação de acetato/componentes, comprimindo margens do modelo atual", "Desemprego 6.4% e massa salarial aquecida sustentam consumo discricionário B2C, favorecendo ticket médio de eyewear"], "political": ["Reforma Tributária em transição: incerteza sobre carga fiscal no varejo pode impactar precificação e margens em 2025-2026", "Taxação de importações (Remessa Conforme) beneficia Tuc Glasses vs dropshipping chinês, fortalecendo competitividade local", "Estabilidade política moderada com risco fiscal: cenário exige cautela em expansão física alavancada"], "environmental": ["Regulamentação do mercado de carbono em pauta: certificação do programa de reflorestamento pode virar ativo de marca", "Volatilidade em petróleo/plástico (acetato) impacta custo de produção: explorar materiais alternativos sustentáveis", "Apelo ambiental como decisor de compra cresce: narrativa Amazônia é barreira competitiva difícil de replicar"], "technological": ["Provadores virtuais e CRM integrado são padrão do setor: Tuc precisa manter maturidade digital (score 8) como vantagem", "CAC crescente em Meta/TikTok ameaça rentabilidade do e-commerce puro: diversificação de canais mitiga risco", "Shopify garante agilidade, mas escala omnichannel exige investimento em ERP/logística integrada"]}'::jsonb, '{"summary": "O setor de eyewear apresenta atratividade média para Tuc Glasses. A rivalidade competitiva é intensa (Chilli Beans, CAC crescente), mas o posicionamento sustentável diferencia a marca. O cenário macro (SELIC 11,25%, dólar R$5,80) desfavorece expansão via lojas próprias com capital de dívida. A recomendação estratégica é priorizar canais de baixo CAPEX (Social Commerce, parcerias B2B) e avaliar franquias como modelo de escala física asset-light. A maturidade digital (8/10) e identidade de marca forte são ativos defensivos contra novos entrantes e substitutos asiáticos.", "buyer_power": "Poder alto: Consumidor cauteloso busca custo-benefício e propósito. IPCA 4,62% e SELIC 11,25% limitam consumo discricionário. Apelo sustentável da marca pode justificar premium, mas sensibilidade a preço é real.", "supplier_power": "Poder médio-alto: Dólar a R$5,80 e volatilidade do acetato (petróleo) pressionam custos de importação. Dependência cambial expõe margens. Diversificação de fornecedores e hedge cambial são mitigadores essenciais.", "disruption_ai_data": "Disrupção média-alta: Provadores virtuais e CRM integrado são padrão do setor. IA pode otimizar CAC e personalização. Maturidade digital 8/10 da Tuc é vantagem, mas concorrentes investem pesado em tech.", "threat_substitutes": "Ameaça média-alta: Players asiáticos com logística local rápida e preços agressivos ameaçam segmento de entrada. Provadores virtuais e social commerce mudam comportamento de compra. Experiência phygital é defesa.", "competitive_rivalry": "Rivalidade alta: Chilli Beans domina shoppings com quiosques e expande para óticas de grau. CAC digital crescente (Meta/TikTok) pressiona margens. Diferenciação via branding sustentável é vantagem competitiva crítica para Tuc Glasses.", "threat_new_entrants": "Ameaça média: Barreiras baixas no digital, mas escalar físico é difícil. Taxação de importações (Remessa Conforme) beneficia players locais vs. dropshipping chinês. Marca forte e omnichannel são diferenciais defensivos.", "buyer_power_intensity": "Alta", "overall_attractiveness": "Média", "strategic_implications": ["Priorizar Social Commerce (TikTok Shop/Pinterest) como canal de crescimento de baixo CAPEX antes de expansão física, dado SELIC 11,25% e custo de capital alto", "Desenvolver modelo de franquias asset-light para escalar presença física usando capital de terceiros, mitigando risco de dívida em cenário de juros elevados", "Implementar hedge cambial e diversificar base de fornecedores para proteger margens contra volatilidade do dólar (R$5,80) e custos de importação", "Fortalecer parcerias B2B estratégicas em pontos premium (shoppings, destinos turísticos) para ampliar distribuição sem investimento direto em lojas próprias"], "supplier_power_intensity": "Média", "disruption_ai_data_intensity": "Média", "threat_substitutes_intensity": "Média", "competitive_rivalry_intensity": "Alta", "power_partnerships_ecosystems": "Poder estratégico alto: Parcerias B2B (Óptica Morison, Nomad Trancoso) ampliam alcance sem CAPEX. TikTok Shop e Pinterest são ecossistemas de crescimento. Modelo de franquias pode alavancar capital de terceiros.", "threat_new_entrants_intensity": "Média", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": "Plano 90 dias: Mês 1 estrutura Social Commerce, Mês 2 ativa canais e otimiza físico, Mês 3 escala digital e prepara fundação para franquias futuras.", "plan_90_days": [{"focus": "Fundação", "month": "Mês 1", "objective": "Estruturar infraestrutura técnica e estratégica para expansão multicanal no Social Commerce", "investment": "R$ 25.000 - R$ 35.000", "key_results": ["Integrar catálogo Shopify com TikTok Shop e Pinterest Shopping até dia 30", "Criar 15 conteúdos UGC com storytelling Amazônia para biblioteca de ativos", "Mapear e documentar jornada omnichannel dos 3 pontos físicos atuais no CRM"], "aligned_recommendation": "Aceleração Digital Multicanal com Social Commerce"}, {"focus": "Crescimento", "month": "Mês 2", "objective": "Ativar canais de Social Commerce e otimizar performance das operações físicas existentes", "investment": "R$ 35.000 - R$ 50.000", "key_results": ["Lançar loja oficial no Mercado Livre com fulfillment otimizado e 50+ SKUs ativos", "Alcançar 500 vendas via TikTok Shop + Pinterest combinados no mês", "Implementar CRM integrado capturando 80% dos clientes físicos no funil digital"], "aligned_recommendation": "Consolidação e Otimização da Operação Física Existente"}, {"focus": "Consolidação", "month": "Mês 3", "objective": "Escalar canais validados e iniciar documentação de processos para fundação de franquias", "investment": "R$ 30.000 - R$ 45.000", "key_results": ["Aumentar receita digital em 15% vs. média dos 2 meses anteriores", "Reduzir dependência de Meta Ads para menos de 60% do tráfego pago total", "Documentar 100% dos processos operacionais dos quiosques em manual padronizado"], "aligned_recommendation": "Construção de Fundação para Franquias (Preparação sem Execução)"}], "success_metrics": ["Receita digital crescendo 40% ao final do trimestre vs. trimestre anterior", "3+ canais de venda digital ativos e gerando receita recorrente", "100% dos processos operacionais físicos documentados para futura escalabilidade"], "total_investment": "R$ 90.000 - R$ 130.000"}'::jsonb, '{"roadmap": ["Curto Prazo (3-6 meses): Estruturar Social Commerce (TikTok Shop, Pinterest), ativar CRM para base existente, otimizar operação dos quiosques atuais", "Médio Prazo (6-12 meses): Escalar canais digitais validados, testar Mercado Livre, implementar Clube Tuc para receita recorrente, atingir R$4M+ faturamento", "Longo Prazo (12+ meses): Avaliar modelo de franquias de quiosques asset-light após atingir R$5M+ e consolidar operação, certificar diferencial sustentável"], "key_findings": ["Social Commerce é o caminho de menor risco e maior potencial de escala para o perfil atual da Tuc Glasses (bootstrapped, marca forte, produto visual)", "Modelo de quiosques em pontos premium valida presença física sem comprometer caixa - manter e otimizar antes de expandir", "Concorrentes como Chilli Beans competem por localização; Tuc Glasses deve competir por propósito, comunidade e conveniência digital-first"], "main_findings": ["FORÇA: Identidade de marca proprietária forte (conceito Amazônia) e maturidade digital alta (8/10) são ativos defensivos contra concorrentes e novos entrantes", "FRAQUEZA: Capital limitado (bootstrapped) e exposição cambial na importação restringem capacidade de expansão física agressiva", "OPORTUNIDADE: Social Commerce (TikTok Shop, Pinterest) oferece aquisição orgânica e viral com CAC reduzido, alinhado ao perfil da marca", "AMEAÇA: SELIC 11,25% + dólar R$5,80 + CAC crescente podem comprimir margens simultaneamente se houver expansão física mal planejada"], "important_notes": ["Cenário macro atual penaliza fortemente lojas próprias com capital de dívida - evitar esse caminho no curto prazo", "Diferencial sustentável deve ser certificado e comunicado ativamente como barreira competitiva", "Franquias exigem maturidade operacional prévia - modelo viável apenas após consolidação digital"], "central_challenge": "Definir o caminho de crescimento ideal entre e-commerce/social commerce, lojas próprias ou franquias, considerando restrições de capital (bootstrapped) e cenário macro desfavorável para expansão física intensiva.", "executive_summary": "Tuc Glasses possui posição estratégica favorável para escala digital-first. Com marca forte, maturidade digital alta (8/10) e diferencial sustentável único, a recomendação é priorizar Social Commerce (TikTok Shop, Pinterest) e marketplaces no curto prazo, manter quiosques como expansão física asset-light, e adiar franquias até atingir R$5M+ de faturamento e maturidade operacional consolidada.", "strategic_priorities": ["Escalar aquisição via TikTok Shop e viralidade orgânica, reduzindo dependência de CAC pago", "Monetizar base existente com bundles, CRM ativo e modelo de assinatura (Clube Tuc)", "Construir reserva de caixa e maturidade operacional antes de qualquer expansão física agressiva"], "overall_recommendation": "Priorizar escala digital via Social Commerce no curto prazo. Manter quiosques como modelo físico de baixo risco. Adiar franquias e lojas próprias até consolidar operação e caixa. O diferencial sustentável é seu maior ativo estratégico - invista em certificação e comunicação."}'::jsonb, '{"sam": "R$ 850M - 1,5B", "som": "R$ 25M - 45M", "tam": "R$ 8,5B - 12B", "cagr": "+8-12% a.a. (baseado em: crescimento e-commerce moda + social commerce trends)", "summary": "Mercado de óculos fashion no Brasil é robusto (R$8-12B), com oportunidade clara no nicho D2C sustentável. Tuc Glasses captura <0.1% hoje, com potencial de 10-18x crescimento no SOM via expansão omnichannel.", "assumptions": ["Mercado óptico brasileiro ~R$25B; óculos de sol fashion = 35-48% (ABIOPTICA 2024)", "SAM: segmento D2C sustentável + classes AB urbanas = 10-12% do TAM", "SOM: market share realista 3-4% do SAM em 5 anos (challenger de nicho)"], "confidence_level": 62, "calculation_notes": "TAM baseado em mercado óptico BR com foco em sunglasses fashion. SAM filtrado por perfil D2C/sustentável urbano. SOM considera posição challenger vs Chilli Beans (~R$1.5B receita).", "data_sources_used": {"direct_data": ["Receita Tuc Glasses: R$2.5M/ano (declarado)", "Setor varejo óptico Brasil: ~R$25B (ABIOPTICA)"], "proxy_calculations": ["Chilli Beans ~R$1.5B receita = ~12% market share sunglasses", "Segmento sustentável/D2C cresce 2x média do setor"], "benchmark_extrapolations": ["Varejo moda/acessórios Brasil: TAM R$1.5-2T, eyewear = 0.5-0.6%", "E-commerce fashion CAGR +15-18% (EBIT/ABComm)"]}, "estimation_method": "proxy_concorrentes"}'::jsonb, '{"summary": "Tuc Glasses possui diferenciação de marca superior (propósito sustentável + design amazônico) mas opera em desvantagem de escala e distribuição. Chilli Beans domina o varejo físico com modelo de franquias maduro; Zerezes compete no mesmo nicho premium-sustentável com estratégia asset-light mais ágil. O gap mais crítico é a ausência em Social Commerce (TikTok Shop), canal que cresce 40% a.a. no Brasil e alinha perfeitamente com o público jovem da marca. Recomendação: priorizar caminho híbrido — escalar e-commerce via marketplaces e TikTok Shop (baixo CAPEX) enquanto testa modelo de franquia/licenciamento para expansão física sem comprometer caixa. Lojas próprias devem ser flagship para branding, não motor de crescimento.", "best_practices": ["Zerezes: Modelo asset-light com pop-ups sazonais em destinos turísticos premium, validando demanda antes de investir fixo.", "Chilli Beans: Franquia com royalties baixos (5%) e suporte robusto, permitindo expansão rápida com capital de terceiros.", "LBA Shop: Integração nativa com marketplaces (ML, Amazon) e fulfillment terceirizado, reduzindo custo logístico em 30%."], "performance_gaps": ["Capilaridade física: Chilli Beans tem +900 PDVs vs. 4 da Tuc. Escala de distribuição limita awareness e conversão offline.", "Social Commerce: Ausência no TikTok Shop enquanto concorrentes asiáticos e Chilli Beans já operam com live commerce ativo.", "Programa de fidelidade: Concorrentes oferecem cashback e clube de benefícios; Tuc não possui CRM estruturado para recompra."], "competitors_analyzed": ["Chilli Beans", "Zerezes", "LBA Shop", "Ui! Gafas"]}'::jsonb, '{"raise": ["Presença em Social Commerce (TikTok Shop, Pinterest, Live Shopping)", "Programa de embaixadores e creators alinhados ao lifestyle sustentável", "Experiência phygital com provador virtual AR no e-commerce e WhatsApp"], "create": ["Modelo de franquia de quiosques com baixo investimento e alta replicabilidade", "Assinatura ''Tuc Club'': troca anual de óculos com benefícios exclusivos", "Certificado de impacto ambiental rastreável por QR Code em cada produto"], "reduce": ["Exposição cambial via diversificação de fornecedores nacionais de acetato", "SKUs de baixo giro para liberar capital e simplificar operação", "Custos fixos de pontos físicos próprios (migrar para modelo asset-light)"], "summary": "A estratégia Oceano Azul da Tuc Glasses abandona o modelo tradicional de expansão física intensiva em capital, criando um ecossistema de crescimento baseado em três pilares: (1) Social Commerce como motor de aquisição orgânica e viral, reduzindo dependência de CAC pago; (2) Franquias de quiosques como modelo asset-light para presença física escalável sem comprometer caixa; (3) Diferenciação radical através de rastreabilidade do impacto ambiental e modelo de assinatura que fideliza e gera receita recorrente. Esta combinação cria uma curva de valor única no mercado de eyewear brasileiro, onde concorrentes como Chilli Beans competem por localização e volume, enquanto Tuc Glasses compete por propósito, comunidade e conveniência digital-first.", "eliminate": ["Investimento em lojas próprias de alto CAPEX em shoppings tradicionais", "Dependência de tráfego pago caro em Meta/Google como canal principal", "Estoque físico descentralizado em múltiplos pontos sem integração"], "new_value_curve": "Escala asset-light via franquias e social commerce, com diferenciação radical por propósito ambiental rastreável e comunidade engajada."}'::jsonb, '{"summary": "Escalar aquisição via TikTok Shop e viralidade orgânica, reduzindo CAC. Monetizar com bundles, CRM ativo e Clube Tuc para aumentar LTV e recorrência em categoria de compra esporádica.", "leap_loop": {"name": "LEAP Loop", "type": "acquisition", "steps": ["Land: Prospects chegam via TikTok/Instagram orgânico com conteúdo lifestyle Amazônia, Pinterest shoppable e tráfego pago segmentado por interesse em moda sustentável.", "Engage: Quiz interativo ''Qual Tuc combina com você?'' + conteúdo UGC de clientes em momentos coloridos + provador virtual AR no site.", "Activate: Oferta de primeira compra com frete grátis + desconto 10% via pop-up + checkout simplificado com PIX e parcelamento sem juros.", "Propagate: Programa ''Indique e Ganhe'' (R$50 para quem indica e indicado) + unboxing instagramável com cartão para compartilhar + hashtag #MomentosTuc."], "metrics": ["CAC por canal (Meta, TikTok, Pinterest, Orgânico)", "Taxa de conversão do quiz para compra", "Coeficiente viral (indicações/cliente)", "CTR e CPC por criativo"], "bottleneck": "CAC crescente no digital com saturação de tráfego pago; necessidade de escalar canais orgânicos e virais para reduzir dependência de mídia paga."}, "scale_loop": {"name": "SCALE Loop", "type": "monetization", "steps": ["Satisfy: Entrega rápida com embalagem premium sustentável + certificado de árvore plantada personalizado + atendimento humanizado via WhatsApp.", "Convert: Ticket médio elevado com bundles (2 óculos com desconto) + upsell de acessórios (cases, cordões) + óculos de grau como extensão de linha.", "Loop Back: Régua de CRM com lançamentos sazonais + programa de fidelidade com pontos + remarketing para coleções novas a cada 3 meses.", "Expand: Assinatura anual ''Clube Tuc'' com óculos exclusivo + acesso antecipado + parcerias B2B com hotéis/resorts para gift corporativo."], "metrics": ["LTV (Lifetime Value) por cohort", "Taxa de recompra em 12 meses", "Ticket médio por pedido", "NPS e taxa de indicação espontânea"], "bottleneck": "Baixa recorrência natural do produto (óculos = compra esporádica); necessidade de criar motivos de recompra via coleções, acessórios e clube de assinatura."}}'::jsonb, '{"realist": {"name": "Cenário Realista", "description": "SELIC mantém-se entre 10-11%, crédito caro inviabiliza expansão física agressiva. Dólar a R$5.80 pressiona margens de importação. CAC digital continua subindo com Chilli Beans e asiáticos investindo pesado em tráfego. Consumidor cauteloso busca custo-benefício, mas valoriza propósito. Reforma tributária gera incerteza no curto prazo. Cenário favorece consolidação digital com expansão física cirúrgica via quiosques de baixo CAPEX.", "probability": 60, "required_actions": ["Priorizar marketplaces (Mercado Livre, Amazon) para diluir CAC e ganhar escala", "Manter estrutura de quiosques (baixo investimento) ao invés de lojas próprias", "Renegociar contratos de importação ou buscar fornecedores nacionais para reduzir exposição cambial", "Investir em CRM e retenção para aumentar LTV e compensar CAC crescente"]}, "summary": "A Tuc Glasses opera em cenário que favorece foco digital com expansão física seletiva. O maior risco é a combinação de SELIC alta + dólar elevado + CAC crescente, que pode comprimir margens simultaneamente. A recomendação estratégica é: (1) Priorizar e-commerce e marketplaces no curto prazo, (2) Manter quiosques como modelo de expansão física de baixo risco, (3) Adiar franquias até atingir maturidade operacional e faturamento de R$5M+, (4) Proteger-se contra câmbio e construir reserva de caixa antes de qualquer movimento agressivo. O diferencial sustentável é ativo estratégico que deve ser certificado e comunicado ativamente.", "optimistic": {"name": "Cenário Otimista", "description": "SELIC recua para 9% até 2026, aquecendo consumo discricionário. Taxação de importações (Remessa Conforme) elimina concorrência de dropshipping chinês. TikTok Shop decola no Brasil e Tuc captura early-adopters. Regulamentação do mercado de carbono valoriza marcas sustentáveis, criando diferencial competitivo imbatível. CAC digital estabiliza com maturação dos algoritmos. Cenário ideal para escalar digital e testar 1-2 lojas próprias em pontos premium.", "probability": 20, "required_actions": ["Acelerar entrada no TikTok Shop e Pinterest com orçamento agressivo de conteúdo", "Negociar ponto próprio em shopping premium (Iguatemi/JK) aproveitando crédito mais barato", "Obter certificação de sustentabilidade reconhecida (B Corp ou similar) para capitalizar regulação de carbono", "Estruturar operação para dobrar capacidade logística em 6 meses"]}, "pessimistic": {"name": "Cenário Pessimista", "description": "SELIC sobe para 13%+ com descontrole fiscal. Dólar ultrapassa R$6.50, inviabilizando importações. Players asiáticos com logística local (Shein, Shopee) dominam eyewear de entrada. CAC digital explode, tornando aquisição insustentável. Reforma tributária aumenta carga sobre varejo. Consumo discricionário contrai com inflação acima de 6%. Chilli Beans acelera consolidação e pressiona pontos físicos. Cenário exige modo sobrevivência e preservação de caixa.", "probability": 20, "required_actions": ["Cortar investimento em mídia paga e focar 100% em orgânico e comunidade", "Encerrar operações físicas deficitárias imediatamente", "Desenvolver linha com produção 100% nacional para eliminar risco cambial", "Buscar parceria estratégica ou M&A com player maior para garantir sobrevivência"]}, "mitigation_tactics": ["Hedge cambial: Contratar operações de proteção para 50% do volume de importação previsto para 12 meses", "Diversificação de canais: Nunca depender de mais de 40% da receita em um único canal (e-commerce próprio, marketplaces, físico)", "Estrutura de custos flexível: Priorizar quiosques e pop-ups com contratos curtos ao invés de lojas próprias com compromissos longos", "Reserva de caixa: Manter 4-6 meses de custo fixo em caixa antes de qualquer expansão física"], "early_warning_signals": ["SELIC: Monitorar decisões do COPOM - aumento acima de 12% sinaliza cenário pessimista", "Dólar: Ultrapassar R$6.20 por mais de 30 dias consecutivos indica necessidade de ativar hedge e revisar precificação", "CAC Digital: Aumento de mais de 25% no custo por aquisição em 90 dias exige revisão imediata de estratégia de mídia", "Concorrência: Chilli Beans ou player asiático lançando linha sustentável/amazônica indica necessidade de acelerar diferenciação"]}'::jsonb, '{"summary": "O BSC alinha a estratégia Oceano Azul da Tuc Glasses integrando Social Commerce como motor de crescimento orgânico (redução de CAC), franquias de quiosques como expansão asset-light (preservando caixa bootstrapped), e diferenciação por propósito ambiental (fidelização e recorrência). As perspectivas se conectam: aprendizado em conteúdo viral alimenta aquisição de clientes, processos enxutos viabilizam escala sem capital intensivo, e a comunidade engajada sustenta receita recorrente.", "customer": ["Elevar NPS para 75+ com rastreabilidade de impacto ambiental por compra", "Atingir 50k seguidores engajados em TikTok/Pinterest como comunidade ativa"], "financial": ["Aumentar receita recorrente via modelo de assinatura para 20% do faturamento", "Reduzir CAC em 35% através de aquisição orgânica via Social Commerce"], "learning_growth": ["Capacitar equipe em Social Commerce e criação de conteúdo viral", "Desenvolver playbook de franquias replicável para escala nacional"], "internal_processes": ["Implementar modelo asset-light de franquias de quiosques em 6 meses", "Integrar operação omnichannel unificada (estoque, CRM, logística)"]}'::jsonb, '{"score": "8.2/10", "summary": "A análise multicriterial indica que o Foco Digital é a estratégia superior para a Tuc Glasses no cenário atual, considerando: (1) Capital bootstrapped limitado vs. SELIC de 11,25% que encarece expansão física via dívida; (2) Maturidade digital alta da empresa (score 8/10) como vantagem competitiva a ser explorada; (3) Tendência de Social Commerce alinhada ao DNA de marca storytelling/sustentabilidade; (4) Exposição cambial que exige preservação de caixa. A estratégia de Lojas Próprias deve ser defensiva (otimizar existentes), não expansionista. Franquias são prematuras - exigem escala, padronização e capital que a empresa ainda não possui. Próximos passos imediatos: (1) Ativar TikTok Shop em 60 dias; (2) Auditar performance dos quiosques atuais; (3) Criar reserva cambial de 3 meses de importação.", "criteria": ["ROI e Eficiência de Capital (Peso 40%) - Retorno sobre investimento considerando capital bootstrapped e SELIC a 11,25%", "Risco Operacional e Financeiro (Peso 35%) - Exposição cambial, CAC, comprometimento de caixa e reversibilidade", "Velocidade de Escala e Time-to-Market (Peso 25%) - Capacidade de crescer receita no curto/médio prazo mantendo controle"], "alternatives": ["Foco Total no E-commerce e Marketplaces (TikTok Shop, Pinterest, Mercado Livre)", "Expansão via Lojas Próprias e Quiosques", "Modelo de Franquias"], "review_cycle": {"frequency": "Trimestral (Março, Junho, Setembro, Dezembro)", "extraordinary_triggers": ["Variação cambial USD/BRL superior a 15% em 60 dias (impacto direto em margens de importação)", "CAC digital aumentar mais de 25% sem aumento proporcional de LTV", "Entrada de competidor relevante no segmento sustentável de eyewear com funding significativo", "Mudança regulatória na tributação de e-commerce ou importações (Reforma Tributária)", "Oportunidade de aquisição ou parceria estratégica com rede de distribuição"]}, "score_comparison": "+31% acima da segunda opção (Lojas Próprias: 6.3/10) e +58% acima de Franquias (5.2/10)", "monitoring_metrics": ["CAC (Custo de Aquisição de Cliente) por canal - Meta: manter abaixo de R$ 45", "LTV/CAC Ratio - Meta: mínimo 3:1 para canais digitais", "Receita por Canal (% e-commerce vs. físico vs. B2B) - Meta: 60% digital", "Margem de Contribuição por SKU considerando câmbio - Meta: mínimo 55%", "ROAS (Return on Ad Spend) por plataforma - Meta: mínimo 4:1", "Taxa de Recompra em 12 meses - Meta: 25%+", "Reserva de Caixa em meses de operação - Meta: mínimo 6 meses"], "recommended_option": "Foco Total no E-commerce e Marketplaces (TikTok Shop, Pinterest, Mercado Livre)", "final_recommendation": "Priorizar e-commerce e marketplaces (TikTok Shop, Pinterest, ML) no curto prazo. Manter quiosques como expansão física de baixo risco. Adiar franquias até R$5M+ de faturamento. Construir reserva de caixa de 6 meses antes de movimentos agressivos.", "priority_recommendations": [{"title": "Aceleração Digital Multicanal com Social Commerce", "budget": "R$ 80.000 - R$ 120.000", "priority": 1, "timeline": "3-6 meses", "description": "Implementar presença robusta no TikTok Shop e Pinterest Shopping nos próximos 6 meses, integrando catálogo Shopify. Ativar loja oficial no Mercado Livre com estratégia de fulfillment otimizado. Investir em conteúdo UGC (User Generated Content) explorando o storytelling da Amazônia e sustentabilidade. Meta: aumentar receita digital em 40% e diversificar fontes de tráfego para reduzir dependência de Meta Ads (CAC crescente)."}, {"title": "Consolidação e Otimização da Operação Física Existente", "budget": "R$ 60.000 - R$ 100.000", "priority": 2, "timeline": "6-12 meses", "description": "Maximizar performance dos quiosques atuais (Iguatemi Campinas e Campos do Jordão) e loja Jardins antes de qualquer nova abertura. Implementar CRM integrado omnichannel para capturar dados de clientes físicos no funil digital. Negociar contratos de quiosque com cláusulas de saída flexíveis. Avaliar expansão de 1-2 quiosques em shoppings premium apenas se ROI dos atuais superar 25% a.a."}, {"title": "Construção de Fundação para Franquias (Preparação sem Execução)", "budget": "R$ 40.000 - R$ 70.000", "priority": 3, "timeline": "12-18 meses", "description": "Documentar processos operacionais, criar manuais de marca e operação, e estruturar modelo financeiro de franquia como preparação estratégica. NÃO lançar franquias até atingir faturamento de R$ 5M+ e ter pelo menos 3 unidades próprias com operação padronizada e lucrativa por 18+ meses. Proteger marca via registro e certificar diferenciais sustentáveis (selo de reflorestamento auditado)."}]}'::jsonb, 'completed', NULL, 129532, true, false, false, '2B0TKL1D', '2025-11-27 13:44:55.688293+00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-27 13:36:58.491092+00'::timestamptz, '2025-11-28 11:18:16.034256+00'::timestamptz, '2025-11-28 11:18:15.864317+00'::timestamptz, NULL)
