INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('70045530-9e53-491e-b9cd-94f2541cc279', '913d8f65-dc52-44a6-9bf2-0c7ac18652c1', '696e1b2d-1418-4d82-9f50-5be8458d4147', '167a9a37-a34e-4363-9300-0653c334af64', '{"summary": "Ativo único com timing favorável. Foco em criar competição entre Diageo/Campari/Pernod via processo estruturado de M&A, explorando câmbio e escassez do produto.", "threats": [{"source": "fato", "content": "Juros altos (SELIC 11.25%) filtram compradores nacionais sem caixa disponível", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Crescimento do gin artesanal compete por share de gôndola premium no Brasil", "confidence": "Média"}, {"source": "análise de mercado", "content": "Liquidez limitada - poucos players globais com apetite para ticket de R$70M", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Instabilidade fiscal brasileira pode atrasar decisões de M&A de grupos estrangeiros", "confidence": "Média"}], "strengths": [{"source": "fato", "content": "Estoque irreplicável de cachaça 12 anos em carvalho - barreira temporal impossível de copiar", "confidence": "Alta"}, {"source": "fato", "content": "Premiações internacionais (Bruxelas, Expocachaça) validam qualidade do líquido", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Ativo estratégico para blends premium de grandes grupos (Diageo, Campari, Pernod)", "confidence": "Alta"}, {"source": "fato", "content": "Infraestrutura produtiva estabelecida desde 2007 com know-how consolidado", "confidence": "Média"}], "weaknesses": [{"source": "análise de mercado", "content": "Marca subvalorizada vs. valor real do estoque - gap de percepção dificulta precificação", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Dependência de canais de nicho limita exposição a compradores estratégicos globais", "confidence": "Média"}, {"source": "fato", "content": "Maturidade digital baixa (nota 5) reduz visibilidade internacional da oportunidade", "confidence": "Alta"}, {"source": "estimativa", "content": "Faturamento estimado R$5-15M não sustenta valuation de R$70M por múltiplos tradicionais", "confidence": "Média"}], "opportunities": [{"source": "fato", "content": "Câmbio USD/BRL 5.75 torna ativo barato para grupos estrangeiros - janela de oportunidade", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Tendência global de premiumização em spirits valoriza estoques envelhecidos raros", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Campari e Diageo em modo aquisição ativa de destilados locais premium", "confidence": "Média"}, {"source": "análise de mercado", "content": "Acordo Mercosul-UE pode reduzir tarifas e aumentar atratividade para exportação", "confidence": "Baixa"}]}'::jsonb, '{"legal": ["IN MAPA sobre padrões de identidade da Cachaça valida autenticidade do produto envelhecido 12 anos para exportação", "Regras rígidas de rotulagem ''Envelhecida'' protegem contra concorrência desleal e sustentam premium pricing", "Análises obrigatórias de contaminantes (Cobre, Carbamato de Etila) certificam qualidade para mercados exigentes (UE, EUA)"], "social": ["Tendência global de premiumização (''beber menos, beber melhor'') valoriza estoques envelhecidos irreplicáveis a curto prazo", "Cachaça ganha reconhecimento como Indicação Geográfica brasileira, elevando percepção internacional similar ao Cognac", "Alta coquetelaria adota cachaça envelhecida em mixologia premium, ampliando demanda B2B para hotéis e bares de luxo"], "summary": "Cenário favorável para M&A: câmbio atrativo para estrangeiros, juros altos filtram compradores sem caixa, e tendência de premiumização valoriza estoque irreplicável de 12 anos. Foco em Diageo, Campari e Pernod como alvos prioritários.", "economic": ["SELIC 11.25% encarece crédito local, favorecendo compradores com caixa (Diageo, Campari) em detrimento de fundos alavancados", "Câmbio USD/BRL 5.75 torna ativo de R$70M equivalente a ~US$12M, preço atrativo para multinacionais de spirits", "Mercado premium cresce +5% CAGR enquanto massa retrai - estoque envelhecido 12 anos é hedge contra commoditização"], "political": ["Reforma Tributária (IVA Dual) em transição pode alterar carga fiscal sobre destilados, impactando valuation para compradores", "Estabilidade política moderada com atenção ao fiscal gera cautela em investidores estrangeiros para M&A de médio porte", "Acordo Mercosul-UE em negociação pode reduzir tarifas e valorizar ativos de exportação para grupos europeus (Campari, Pernod)"], "environmental": ["Licenciamento ambiental em dia é pré-requisito para due diligence de multinacionais com ESG rigoroso", "Tonéis de carvalho americano têm pegada de carbono rastreável, alinhado com tendências de sustentabilidade em spirits", "Localização em SC (Vale do Itajaí) oferece água de qualidade e clima favorável, ativos intangíveis para storytelling"], "technological": ["Maturidade digital baixa (score 5/10) limita alcance direto ao consumidor, mas não impacta valor do ativo físico (estoque)", "Controle de qualidade moderno com tradição artesanal atende exigências de due diligence de grandes grupos", "Rastreabilidade MAPA para exportação exige investimentos em sistemas, potencial custo pós-aquisição para comprador"]}'::jsonb, '{"summary": "Setor altamente atrativo para M&A. Fogo da Cana possui ativo irreplicável (estoque 12 anos) em momento de câmbio favorável e apetite de conglomerados globais. Barreiras de entrada protegem valor. Estratégia deve focar em maximizar poder de negociação via múltiplos compradores estratégicos (Diageo, Campari, Pernod Ricard), explorando janela macroeconômica atual.", "buyer_power": "Poder médio. Consumidor premium resiliente (sentiment positivo), mas compradores B2B (Diageo, Campari) têm alto poder de negociação. Câmbio 5.75 favorece estrangeiros na aquisição.", "supplier_power": "Poder baixo. Cana-de-açúcar com preços estáveis, supply chain normalizado. Único risco: vidro com preços elevados impactando margens de engarrafamento premium.", "disruption_ai_data": "Impacto baixo. Setor com adoção tecnológica média, foco em tradição. IA pode otimizar precificação e matching com compradores, mas não disrupta o core (envelhecimento físico).", "threat_substitutes": "Ameaça média. Gin artesanal nacional cresce e compete por gôndola premium. Whiskies single malt são referência, mas cachaça 12 anos compete em preço-qualidade.", "competitive_rivalry": "Rivalidade média-alta no premium. Mercado fragmentado no topo, mas Campari/Diageo buscam aquisições. Weber Haus e Velho Barreiro Premium competem, porém estoque 12 anos é diferencial irreplicável.", "threat_new_entrants": "Ameaça baixa. Barreira temporal de 12 anos é intransponível. Regulação MAPA rigorosa e exigências de rastreabilidade para exportação elevam custos de entrada.", "buyer_power_intensity": "Média", "overall_attractiveness": "Alta", "strategic_implications": ["Priorizar abordagem direta a Diageo, Pernod Ricard e Campari, aproveitando câmbio favorável (USD/BRL 5.75) e apetite por M&A no setor", "Estruturar venda parcial do estoque (bulk) para grandes grupos como alternativa à venda integral, reduzindo risco de liquidez", "Explorar Acordo Mercosul-UE para valorizar estoque via contratos de exportação de longo prazo com distribuidores europeus", "Posicionar cachaça 12 anos como competidor direto de whiskies premium em feiras internacionais (Bruxelas, Tales of the Cocktail)"], "supplier_power_intensity": "Baixa", "disruption_ai_data_intensity": "Baixa", "threat_substitutes_intensity": "Média", "competitive_rivalry_intensity": "Média", "power_partnerships_ecosystems": "Poder alto. M&A ativo (Campari, Diageo buscando destilados locais). Acordo Mercosul-UE pode reduzir tarifas. Ecossistema de mixologia valoriza cachaça envelhecida.", "threat_new_entrants_intensity": "Baixa", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": "90 dias para transformar ativo de cachaça envelhecida em processo competitivo de M&A, gerando múltiplas propostas de compradores estratégicos globais.", "plan_90_days": [{"focus": "Fundação", "month": "Mês 1", "objective": "Estruturar o processo de venda com documentação profissional e mapeamento inicial de compradores estratégicos", "investment": "R$ 80-120 mil (retainer M&A, tradução técnica, produção de amostras certificadas)", "key_results": ["Contratar boutique de M&A especializada em bebidas e assinar contrato de assessoria até dia 15", "Preparar 50 kits de amostras certificadas com laudos técnicos em inglês e português", "Mapear e qualificar lista de 25 potenciais compradores (Diageo, Pernod Ricard, Campari, LVMH, engarrafadores)"], "aligned_recommendation": "Processo Formal de M&A com Assessoria Especializada"}, {"focus": "Crescimento", "month": "Mês 2", "objective": "Iniciar prospecção ativa B2B e construir Data Room virtual para due diligence", "investment": "R$ 60-90 mil (viagens internacionais, logística de amostras, Data Room, consultoria)", "key_results": ["Enviar amostras e proposta comercial para 15 grupos de bebidas internacionais", "Finalizar Information Memorandum (IM) e Data Room virtual com 100% dos documentos", "Agendar pelo menos 5 reuniões/calls com decisores de M&A de conglomerados-alvo"], "aligned_recommendation": "Estruturação de Venda B2B de Estoque a Granel"}, {"focus": "Consolidação", "month": "Mês 3", "objective": "Gerar competição entre compradores e posicionar marca para maximizar valuation", "investment": "R$ 70-100 mil (feira internacional, valuation independente, assessoria jurídica)", "key_results": ["Receber pelo menos 3 LOIs (Letters of Intent) ou propostas formais de interesse", "Participar de 1 feira internacional (ProWein ou equivalente) com stand de posicionamento premium", "Obter valuation independente validado e ajustar faixa de negociação para R$ 25-45M"], "aligned_recommendation": "Fortalecimento de Marca e Canal de Exportação"}], "success_metrics": ["Mínimo de 3 propostas formais (LOI) de compradores qualificados ao final dos 90 dias", "Data Room completo e IM aprovado por assessoria de M&A", "Pipeline de 15+ contatos ativos com decisores de conglomerados globais de bebidas"], "total_investment": "R$ 210-310 mil"}'::jsonb, '{"roadmap": ["Curto Prazo (3-6 meses): Preparar data room, contratar assessor de M&A especializado em spirits, iniciar prospecção ativa com Diageo, Campari e Pernod Ricard", "Médio Prazo (6-12 meses): Conduzir roadshows, gerar LOIs competitivas, negociar deal structures (earnout, equity roll), executar vendas a granel para liquidez", "Longo Prazo (12+ meses): Fechar transação de M&A, estruturar transição operacional, monitorar gatilhos de valorização (Acordo Mercosul-UE, queda de SELIC)"], "key_findings": ["Reposicionar de ''cachaça à venda'' para ''reserva estratégica de aged spirit'' muda percepção de compradores globais", "Processo competitivo com múltiplos compradores (Diageo, Campari, Pernod) maximiza poder de negociação", "Venda parcial de estoque a granel pode gerar liquidez enquanto M&A se desenvolve em 12-18 meses"], "main_findings": ["FORÇA: Estoque de 12 anos é barreira temporal absoluta — impossível de replicar com dinheiro, apenas com tempo", "FRAQUEZA: Marca subvalorizada e dependência de canais de nicho limitam poder de negociação individual", "OPORTUNIDADE: Câmbio favorável e apetite de conglomerados globais por destilados autênticos criam janela de M&A", "AMEAÇA: Mercado de M&A restritivo e juros altos podem prolongar negociação para 12-18 meses"], "important_notes": ["Expectativa de R$70M provavelmente irrealista — mercado precifica entre R$25-40M", "Janela de câmbio favorável pode fechar — urgência em iniciar processo de M&A", "Acordo Mercosul-UE pode valorizar ativo se aprovado — monitorar cronograma"], "central_challenge": "Recuperar parcialmente investimento de R$70M via venda de empresa ou estoque de cachaça 12 anos, em mercado de M&A restritivo com valuation realista entre R$25-40M.", "executive_summary": "Fogo da Cana possui ativo irreplicável: estoque de cachaça 12 anos em carvalho que nenhum concorrente pode recriar sem uma década de espera. O momento é favorável: câmbio a R$5,75 torna o ativo barato para Diageo, Campari e Pernod Ricard. A estratégia deve criar competição entre compradores via processo estruturado de M&A, ajustando expectativas de R$70M para faixa realista de R$25-40M, enquanto venda parcial a granel gera liquidez imediata.", "strategic_priorities": ["Estruturar processo de M&A com roadshow para 3 conglomerados globais prioritários", "Ajustar valuation para faixa R$25-40M com deal structures flexíveis", "Iniciar venda a granel paralela para gerar caixa imediato"], "overall_recommendation": "Iniciar imediatamente processo estruturado de M&A com assessoria especializada, criando competição entre Diageo, Campari e Pernod Ricard. Ajustar expectativas para R$25-40M e usar venda a granel como ponte de liquidez. A janela de câmbio favorável exige ação nos próximos 90 dias."}'::jsonb, '{"sam": "R$ 1.8B - 3.5B", "som": "R$ 90M - 175M", "tam": "R$ 18B - 25B", "cagr": "+5% a.a. (baseado em: ABRABE/Expocachaça - segmento premium spirits)", "summary": "Mercado premium de cachaça em expansão (+5% CAGR). Estoque 12 anos é ativo estratégico raro. Potencial de M&A com grupos globais (Diageo/Campari/Pernod) que buscam spirits locais premium. Valuation de R$70M plausível se estoque >500k litros.", "assumptions": ["Mercado brasileiro de cachaça ~R$18-25B (ABRABE 2024, 1.3B litros/ano × preço médio)", "Segmento Premium/Envelhecida = 10-14% do mercado total (tendência premiumização +5% CAGR)", "SOM considera estoque 12 anos como ativo único + capacidade de captura 5% do SAM"], "confidence_level": 62, "calculation_notes": "TAM: mercado cachaça Brasil (ABRABE). SAM: segmento premium/envelhecida 10-14%. SOM: market share realista considerando ativo único (estoque 12 anos) e potencial M&A com grande grupo.", "data_sources_used": {"direct_data": ["ABRABE - produção anual 1.3B litros cachaça", "Expocachaça Reports - crescimento premium +5% CAGR", "MAPA - 40.000 produtores registrados, 4.000 marcas"], "proxy_calculations": ["Preço médio litro cachaça R$14-19 (massa) a R$150-400 (premium 12 anos)", "Weber Haus/Magnífica faturamento estimado R$30-80M (referência competidores premium)", "Estoque 12 anos: ~500.000-700.000 litros estimados para justificar R$70M (R$100-140/litro bulk)"], "benchmark_extrapolations": ["Múltiplo M&A spirits premium: 2-4x receita ou 1-1.5x valor estoque envelhecido", "Diageo/Campari pagaram 3-5x receita em aquisições de nicho premium globalmente"]}, "estimation_method": "proxy_concorrentes"}'::jsonb, '{"summary": "Fogo da Cana possui ativo único (estoque 12 anos) mas carece de infraestrutura de marca e distribuição dos líderes. Weber Haus lidera em experiência e storytelling; Velho Barreiro em escala exportadora; Magnífica em posicionamento bartender. Para viabilizar venda a R$70M, necessita: (1) auditoria independente do estoque, (2) valuation por consultoria especializada em spirits, (3) roadshow para Diageo/Campari/Pernod Ricard que buscam ativamente cachaças premium para portfólio global. O gap crítico é transformar estoque físico em narrativa de valor para compradores estratégicos.", "best_practices": ["Weber Haus: Turismo de experiência na destilaria gera brand equity e justifica preços premium.", "Magnífica: Parcerias com bartenders renomados e presença em competições internacionais de drinks.", "Velho Barreiro Premium: Estrutura de M&A pronta com due diligence e valuation auditado para investidores."], "performance_gaps": ["Marca subvalorizada vs. Weber Haus que possui forte presença digital e storytelling premium consolidado.", "Ausência de canais de distribuição globais estruturados, diferente da Velho Barreiro com rede exportadora ativa.", "Baixa visibilidade em mixologia de alta coquetelaria, segmento dominado por Magnífica e Vale Verde."], "competitors_analyzed": ["Weber Haus", "Cachaça Velho Barreiro (Linhas Premium)", "Magnífica", "Vale Verde", "Cachaça 51 (Reserva/Exportação)"]}'::jsonb, '{"raise": ["Visibilidade internacional via roadshow com Diageo, Campari e Pernod Ricard", "Documentação de due diligence pronta (auditoria de estoque, laudos, IP)", "Urgência competitiva: criar leilão silencioso entre múltiplos interessados"], "create": ["Narrativa de ''Liquid Gold'': ativo irreplicável com 12 anos de barreira temporal", "Modelo de venda híbrido: empresa inteira OU estoque a granel para blends premium", "Parceria com banco de investimento especializado em spirits M&A global"], "reduce": ["Foco em vendas B2C diretas que diluem percepção de escala", "Exposição a um único comprador potencial (evitar exclusividade prematura)", "Complexidade operacional que afaste compradores estratégicos"], "summary": "A estratégia transforma a Fogo da Cana de uma operação de venda tradicional para um processo de M&A estruturado com competição entre compradores. O oceano azul está em reposicionar o ativo não como ''empresa de cachaça à venda'', mas como ''reserva estratégica de liquid aged spirit'' que conglomerados globais precisam para competir no segmento ultra-premium. A janela de câmbio (R$5,75/USD) e o apetite de Diageo/Campari por destilados locais autênticos criam urgência. A diferenciação radical: ninguém pode replicar 12 anos de envelhecimento — isso é tempo, não dinheiro.", "eliminate": ["Dependência de canais de distribuição regionais e fragmentados", "Posicionamento como ''mais uma cachaça premium'' no mercado doméstico", "Negociação passiva esperando compradores virem até a empresa"], "new_value_curve": "De produtor regional para ativo estratégico global: estoque irreplicável + câmbio favorável + múltiplos compradores = máximo poder de negociação."}'::jsonb, '{"summary": "Estratégia de exit via M&A: prospectar conglomerados globais de spirits com roadshows e PR especializado, oferecendo ativo único de 12 anos com deal structures flexíveis.", "leap_loop": {"name": "LEAP Loop", "type": "acquisition", "steps": ["Land: Prospecção ativa em feiras de M&A (Spirits), roadshows para Diageo/Campari/Pernod Ricard e fundos de private equity focados em F&B premium.", "Engage: Degustações exclusivas com amostras do estoque 12 anos para decisores, apresentando certificações, medalhas e laudo de avaliação do ativo.", "Activate: Oferecer due diligence facilitada com data room virtual completo, proposta de deal structures flexíveis (venda total, parcial ou licenciamento).", "Propagate: Gerar buzz via PR em veículos especializados (Drinks International, Shanken News) e cases de aquisições similares no setor."], "metrics": ["Número de LOIs (Cartas de Intenção) recebidas", "Taxa de conversão de reunião para proposta formal", "Alcance de mídia especializada (impressões qualificadas)"], "bottleneck": "Acesso limitado a decisores de grandes conglomerados internacionais de bebidas e fundos especializados em M&A de spirits."}, "scale_loop": {"name": "SCALE Loop", "type": "monetization", "steps": ["Satisfy: Entregar ativo único e irreplicável (12 anos de envelhecimento), com documentação completa de qualidade, origem e potencial de branding.", "Convert: Estruturar deal em tranches (estoque + marca + operação) ou venda de granel para blending, maximizando valor percebido por litro envelhecido.", "Loop Back: Oferecer contrato de fornecimento contínuo pós-venda (produção futura) para criar relacionamento de longo prazo com comprador.", "Expand: Negociar royalties sobre marca ou participação minoritária em operação futura para capturar upside de valorização pós-aquisição."], "metrics": ["Valor por litro negociado (R$/L de cachaça 12 anos)", "Percentual do investimento recuperado (meta: >50% dos R$70M)", "Valor de contratos recorrentes pós-venda"], "bottleneck": "Liquidez do ativo: converter R$70M em estoque físico requer comprador com escala global ou fragmentar venda, diluindo valor."}}'::jsonb, '{"realist": {"name": "Cenário Realista", "description": "SELIC em 11.25% mantém compradores nacionais afastados. Grupos estrangeiros demonstram interesse moderado, mas priorizam due diligence longa (12-18 meses). Valuation negociado entre R$ 25-40M, com desconto de 40-60% sobre claim de R$ 70M. Venda parcial do estoque a granel para blenders internacionais emerge como alternativa para gerar caixa imediato enquanto M&A avança.", "probability": 60, "required_actions": ["Iniciar prospecção paralela de venda de estoque a granel para importadores europeus e americanos", "Ajustar expectativa de valuation para faixa R$ 30-45M baseado em múltiplos de mercado de spirits", "Estruturar operação híbrida: venda de 30% do estoque para liquidez + M&A do restante", "Engajar consultor tributário para otimizar estrutura fiscal da transação sob novo IVA Dual"]}, "summary": "O cenário mais provável (60%) aponta para negociação prolongada de 12-18 meses com valuation entre R$ 25-40M, significativamente abaixo do claim de R$ 70M. A estratégia deve combinar prospecção ativa de M&A com venda parcial de estoque a granel para gerar liquidez. O ativo irreplicável (12 anos de envelhecimento) é diferencial competitivo, mas o mercado de M&A está restritivo. Recomenda-se ajustar expectativas, diversificar canais de saída e monitorar sinais macroeconômicos (SELIC, câmbio, Acordo Mercosul-UE) para identificar janelas de oportunidade.", "optimistic": {"name": "Cenário Otimista", "description": "Diageo ou Campari aceleram estratégia de aquisição de destilados premium brasileiros, atraídos pelo câmbio USD/BRL 5.75 e estoque irreplicável de 12 anos. Acordo Mercosul-UE é ratificado, reduzindo tarifas e valorizando ativos exportáveis. Valuation atinge R$ 50-60M com múltiplo premium pelo tempo de envelhecimento. Negociação fecha em 6-9 meses com earn-out.", "probability": 20, "required_actions": ["Contratar banco de investimento boutique especializado em spirits para conduzir processo competitivo entre Diageo, Campari e Pernod", "Preparar data room completo com laudos de qualidade, certificações MAPA e histórico de premiações internacionais", "Estruturar proposta de earn-out vinculada a performance pós-aquisição para maximizar valor total"]}, "pessimistic": {"name": "Cenário Pessimista", "description": "Crise fiscal brasileira eleva risco-país, afastando investidores estrangeiros. Gin artesanal captura share premium, reduzindo apetite por cachaça. Reforma tributária aumenta carga sobre destilados. Grandes grupos pausam M&A aguardando estabilidade. Valuation despenca para R$ 15-20M. Estoque envelhece além do ponto ótimo, perdendo valor. Liquidação forçada a preços de commodity.", "probability": 20, "required_actions": ["Acelerar venda de estoque a granel antes de depreciação, mesmo com desconto de 50%", "Explorar joint-venture com distribuidor internacional para monetizar marca sem venda total", "Reduzir custos operacionais ao mínimo para preservar caixa durante período de espera"]}, "mitigation_tactics": ["Diversificar canais de saída: M&A completo, venda parcial de estoque, licenciamento de marca e joint-venture simultâneos", "Criar urgência artificial com deadline de exclusividade para compradores prioritários (Diageo, Campari, Pernod)", "Obter avaliação independente de terceiro (ex: KPMG, Deloitte) para ancorar negociação em valuation defensável", "Desenvolver plano B de monetização via exportação direta para mercados premium (EUA, Europa) caso M&A fracasse"], "early_warning_signals": ["Movimento de SELIC: queda abaixo de 10% reativa compradores nacionais; alta acima de 12% congela mercado", "Anúncios de M&A no setor de spirits por Diageo/Campari/Pernod indicam apetite ativo para aquisições", "Ratificação do Acordo Mercosul-UE sinaliza janela de valorização de ativos exportáveis brasileiros", "Volatilidade cambial acima de USD/BRL 6.00 pode acelerar interesse estrangeiro ou indicar fuga de capital", "Mudanças na tributação de destilados na Reforma Tributária impactam diretamente valuation do estoque"]}'::jsonb, '{"summary": "BSC alinhado para transformar venda tradicional em processo competitivo de M&A, alavancando a escassez temporal do ativo (12 anos irreplicáveis) e o câmbio favorável para atrair compradores globais e maximizar recuperação do investimento.", "customer": ["Atrair Diageo, Campari e Pernod Ricard como leads qualificados até Q2/2025", "Posicionar estoque como ''liquid aged spirit'' irreplicável para mercado ultra-premium"], "financial": ["Maximizar valuation para atingir recuperação mínima de 50% do investimento (R$35M)", "Criar competição entre 3+ compradores estratégicos para elevar múltiplo de venda"], "learning_growth": ["Mapear decisores de aquisição em 5 conglomerados globais de bebidas", "Desenvolver pitch deck bilíngue destacando barreira temporal de 12 anos"], "internal_processes": ["Estruturar data room completo com due diligence pronta em 60 dias", "Contratar advisor de M&A com track record em spirits para conduzir processo"]}'::jsonb, '{"score": "7.8/10", "summary": "A estratégia híbrida maximiza chances de recuperação parcial do investimento ao combinar duas frentes: (1) liquidez de curto prazo via venda B2B de estoque envelhecido para grandes grupos, aproveitando o câmbio favorável e a escassez global de cachaça premium 12 anos; (2) processo estruturado de M&A com valuation realista, preparando a empresa para capturar oportunidades quando o mercado de fusões e aquisições se aquecer. A expectativa de recuperar R$ 70M é improvável no cenário atual; a meta realista situa-se entre R$ 30-50M considerando ambas as frentes. Próximos passos: (i) contratar assessor de M&A até 30 dias; (ii) preparar kit de vendas B2B internacional até 60 dias; (iii) agendar reuniões com Diageo, Campari e Pernod Ricard até 90 dias.", "criteria": ["Recuperação do Capital Investido (ROI)", "Velocidade de Liquidez (Tempo)", "Risco de Execução e Dependência de Terceiros"], "alternatives": ["Venda Integral da Empresa (M&A Completo)", "Venda Parcial de Estoque a Granel + Manutenção da Operação", "Estratégia Híbrida: Liquidez via Granel + Prospecção M&A Paralela"], "review_cycle": {"frequency": "Trimestral", "extraordinary_triggers": ["Proposta formal de aquisição recebida (LOI/NBO)", "Variação cambial USD/BRL superior a 15% em 60 dias", "Aprovação do Acordo Mercosul-UE", "Mudança na SELIC superior a 200 bps", "Venda de estoque a granel superior a R$ 5M em único trimestre", "Entrada de novo player estratégico no mercado de cachaça premium"]}, "score_comparison": "+18% acima da segunda opção (Venda Parcial de Estoque)", "monitoring_metrics": ["Volume de estoque vendido a granel (litros/mês)", "Receita líquida de vendas B2B e B2C (R$/mês)", "Número de NDAs assinados com potenciais compradores", "Pipeline de M&A (leads qualificados em due diligence)", "Cotação USD/BRL (média móvel 30 dias)", "Taxa SELIC e custo de capital de compradores", "Engajamento internacional (leads de exportação, participação em feiras)"], "recommended_option": "Estratégia Híbrida: Liquidez via Granel + Prospecção M&A Paralela", "final_recommendation": "Adotar estratégia híbrida: gerar liquidez imediata via venda de estoque a granel (20-30% em 12 meses) enquanto conduz processo formal de M&A com expectativa ajustada de R$ 25-45M. Monitorar janelas macro.", "priority_recommendations": [{"title": "Estruturação de Venda B2B de Estoque a Granel", "budget": "R$ 180-280k (consultoria de M&A, tradução, amostras, viagens internacionais)", "priority": 1, "timeline": "6-12 meses", "description": "Mapear e prospectar ativamente grandes grupos de bebidas (Diageo, Pernod Ricard, Campari, LVMH) e engarrafadores premium nacionais para venda de cachaça envelhecida a granel. Preparar amostras certificadas, laudos técnicos e proposta comercial em inglês. Meta: converter 20-30% do estoque em caixa nos primeiros 12 meses, gerando liquidez de R$ 8-15M."}, {"title": "Processo Formal de M&A com Assessoria Especializada", "budget": "R$ 250-400k (success fee de 2-4% sobre transação + retainer)", "priority": 2, "timeline": "12-18 meses", "description": "Contratar boutique de M&A com experiência no setor de bebidas para conduzir processo competitivo. Preparar Information Memorandum (IM), Data Room virtual e valuation independente. Ajustar expectativa de valuation para faixa realista de R$ 25-45M, posicionando o ativo irreplicável (12 anos) como diferencial. Monitorar janelas de oportunidade (câmbio favorável, Acordo Mercosul-UE)."}, {"title": "Fortalecimento de Marca e Canal de Exportação", "budget": "R$ 120-200k (feiras, certificações, marketing digital internacional)", "priority": 3, "timeline": "9-15 meses", "description": "Investir em posicionamento premium da marca Fogo da Cana para aumentar valor percebido em eventual M&A. Participar de feiras internacionais (ProWein, Tales of the Cocktail), buscar certificações de origem e ampliar presença em e-commerce internacional. Objetivo: criar narrativa de valor que justifique múltiplo superior no valuation."}]}'::jsonb, 'completed', NULL, 133973, true, false, false, 'TSSYYATW', '2025-11-27 14:04:17.024839+00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-27 13:59:59.805469+00'::timestamptz, '2025-11-28 05:44:03.770068+00'::timestamptz, '2025-11-27 14:02:13.469027+00'::timestamptz, NULL)
