INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('7d8af360-c9d7-47b1-987e-e00e1dc7482a', 'cd710384-da5e-4af3-8f23-c44df2d2f546', 'e3910f99-a382-4072-96b5-0070cfd7957e', '6868ecf3-f173-410a-9ab6-6adf138a7fd4', '{"summary": "Boutique bem posicionada em nicho aquecido (LGPD/IA), mas crescimento limitado por dependência do fundador e ausência de estrutura comercial. Automação e profissionalização da gestão são críticos.", "threats": [{"source": "análise de mercado", "content": "Softwares CLM e consultorias de TI substituindo serviços jurídicos básicos (commoditização)", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Concorrentes investindo em IA proprietária para análise contratual, pressionando margens", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Grandes bancas adquirindo boutiques digitais para absorver know-how e clientes", "confidence": "Média"}, {"source": "fato", "content": "SELIC alta (10.75%) encarece expansão e pressiona clientes a reduzir gastos jurídicos fixos", "confidence": "Alta"}], "strengths": [{"source": "fato", "content": "Expertise consolidada em Direito Digital e LGPD com 19 anos de mercado (fundação 2006)", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Alta maturidade digital (score 8/10) e presença ativa em marketing de conteúdo jurídico", "confidence": "Alta"}, {"source": "fato", "content": "Clareza estratégica em metas financeiras: lucratividade >40% e controle de markup definidos", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Posicionamento de nicho especializado permite pricing premium vs. bancas generalistas", "confidence": "Média"}], "weaknesses": [{"source": "fato", "content": "Alta dependência do sócio fundador para vendas e reputação da marca", "confidence": "Alta"}, {"source": "fato", "content": "Ausência de estrutura comercial ativa (100% crescimento orgânico, sem outbound)", "confidence": "Alta"}, {"source": "fato", "content": "Board formado apenas por advogados operacionais, sem visão de gestão empresarial", "confidence": "Alta"}, {"source": "fato", "content": "Processos de precificação, controle de horas e lucratividade por conta não padronizados", "confidence": "Média"}], "opportunities": [{"source": "análise de mercado", "content": "Regulamentação de IA (PL 2338/23) criará demanda massiva por compliance em 2025-26", "confidence": "Alta"}, {"source": "fato", "content": "Endurecimento da ANPD gera onda de contencioso e adequação LGPD em empresas médias", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Escassez de talentos sêniores em Direito Digital permite atrair via plano de carreira estruturado", "confidence": "Média"}, {"source": "estimativa", "content": "Parcerias com ecossistemas tech (startups, VCs, aceleradoras) como canal de aquisição B2B", "confidence": "Média"}]}'::jsonb, '{"legal": ["ANPD endurecendo fiscalização e dosimetria de penas - demanda crescente por assessoria LGPD e contencioso administrativo", "PL 2338/23 regulamenta IA - oportunidade de liderar mercado de compliance em inteligência artificial para clientes tech", "Provimento 205/2021 limita marketing jurídico - restrição à estruturação de área comercial outbound tradicional"], "social": ["Escassez de talentos sêniores em Direito Digital - barreira crítica para escalar equipe sem perder qualidade técnica", "Empresas cautelosas com gastos fixos - oportunidade para modelos de honorários flexíveis e pacotes de valor percebido", "Hiperespecialização como diferencial competitivo - posicionamento em IA Compliance pode atrair novos segmentos B2B"], "summary": "Ambiente regulatório aquecido (LGPD, IA) favorece crescimento, mas SELIC alta e escassez de talentos exigem eficiência operacional. Automação e diferenciação por Legal Design são críticos para escalar sem comprometer margem de 40%.", "economic": ["SELIC 10.75% encarece expansão alavancada - crescimento deve ser via capital próprio, preservando meta de lucratividade 40%", "Dólar a R$5.85 pressiona clientes tech que importam - risco de inadimplência e renegociação de honorários recorrentes", "PIB +2.6% com empresas buscando ''mais por menos'' - pressão por eficiência jurídica exige automação e controle de horas"], "political": ["Reforma Tributária impacta ISS sobre serviços advocatícios - risco de aumento de carga tributária em sociedades de advogados", "MP 1.318/2025 cria regime especial para datacenters - oportunidade de assessoria jurídica para clientes tech em expansão", "Estabilidade política moderada com foco regulatório - ambiente favorável para demandas de compliance e adequação normativa"], "environmental": ["Custo elevado de cloud computing impacta infraestrutura digital - pressão nas margens de clientes e do próprio escritório", "ESG como critério de seleção de fornecedores por grandes corporações - oportunidade de posicionamento sustentável", "Tendência de trabalho híbrido reduz custos fixos de escritório - possibilidade de realocar recursos para crescimento"], "technological": ["Concorrentes investindo em IA proprietária - risco de perda de competitividade em margem sem automação de processos", "CLMs substituindo advogados júnior - ameaça à pirâmide de talentos e modelo de precificação por hora trabalhada", "Legal Design e Visual Law como padrão de entrega - diferenciação possível para aumentar percepção de valor pelo cliente"]}'::jsonb, '{"summary": "Setor com crescimento de 8.5% CAGR, mas forças competitivas intensas. Rivalidade alta exige diferenciação via IA e hiperespecialização. Compradores com alto poder pressionam por eficiência. Ameaça de substitutos (CLM, consultorias TI) é crítica. Parcerias em ecossistemas tech são alavanca de crescimento. Disrupção por IA é inevitável: quem não automatizar perderá margem. Atratividade média condicionada à execução de transformação digital e estruturação comercial.", "buyer_power": "Poder alto: Empresas cautelosas buscam ''mais por menos''. IPCA 4.8% e SELIC 10.75% pressionam orçamentos. Clientes tech exigem eficiência, transparência em horas e alta percepção de valor.", "supplier_power": "Poder médio: Escassez de talentos sêniores em Direito Digital eleva custos de retenção. Custo de cloud computing alto (USD/BRL 5.85) pressiona investimentos em tecnologia e automação.", "disruption_ai_data": "Disrupção alta: IA generativa transforma análise contratual e processual. Concorrentes investem pesado em IA proprietária. Escritórios sem automação perdem competitividade em margem e velocidade.", "threat_substitutes": "Ameaça alta: Softwares CLM substituem advogados júnior. Consultorias de TI oferecem ''compliance'' sem advogados. Commoditização de serviços básicos acelera com IA generativa.", "competitive_rivalry": "Rivalidade alta: Opice Blum, Patricia Peck e LBCA investem em IA proprietária. Mercado fragmentado com consolidação de grandes bancas. Diferenciação exige hiperespecialização e automação para manter margem >40%.", "threat_new_entrants": "Ameaça média: Barreira de capital baixa, mas reputacional alta. Regulação OAB e Provimento 205/2021 limitam marketing agressivo. Novas boutiques surgem, mas sem expertise consolidada.", "buyer_power_intensity": "Alta", "overall_attractiveness": "Média", "strategic_implications": ["Investir em IA proprietária para análise contratual e processual, protegendo margem e diferenciando da commoditização", "Estruturar área comercial outbound com parcerias em ecossistemas tech (aceleradoras, VCs, consultorias) para reduzir dependência orgânica", "Implementar precificação baseada em valor (não horas) com markup padronizado e controle de lucratividade por conta/advogado", "Desenvolver programa de retenção de talentos sêniores com plano de carreira claro e equity para reduzir poder de fornecedores"], "supplier_power_intensity": "Média", "disruption_ai_data_intensity": "Alta", "threat_substitutes_intensity": "Alta", "competitive_rivalry_intensity": "Alta", "power_partnerships_ecosystems": "Poder médio-alto: Parcerias com consultorias tech e integradoras de sistemas ampliam alcance. Ecossistema de startups demanda legal design. Alianças estratégicas reduzem dependência de vendas orgânicas.", "threat_new_entrants_intensity": "Média", "power_partnerships_ecosystems_intensity": "Média"}'::jsonb, '{"summary": "90 dias para implantar gestão operacional, estruturar vendas outbound e iniciar redução da dependência do fundador, mantendo margem >40%.", "plan_90_days": [{"focus": "Fundação", "month": "Mês 1", "objective": "Estabelecer infraestrutura de gestão operacional e diagnóstico do board para sustentar crescimento controlado", "investment": "R$ 25.000 - R$ 40.000", "key_results": ["Selecionar e contratar software de timesheet integrado (Astrea, ADVBOX ou Themis) até dia 15", "Mapear 100% das horas trabalhadas vs. faturadas dos últimos 3 meses por advogado e cliente", "Realizar assessment DISC de 100% dos sócios do board e entregar relatório de gaps de competências"], "aligned_recommendation": "Implementação de Sistema de Gestão e Controle Operacional"}, {"focus": "Crescimento", "month": "Mês 2", "objective": "Operacionalizar controles financeiros, iniciar estruturação comercial e definir plano de carreira", "investment": "R$ 35.000 - R$ 55.000", "key_results": ["Implementar markup mínimo de 3.5x e dashboard de lucratividade por cliente/advogado funcionando", "Contratar 1 SDR e definir ICP documentado com playbook de prospecção e cadências de e-mail", "Publicar plano de carreira com 5 níveis e critérios claros de promoção para 100% da equipe"], "aligned_recommendation": "Estruturação de Máquina de Vendas B2B (Outbound Controlado)"}, {"focus": "Consolidação", "month": "Mês 3", "objective": "Consolidar métricas de rentabilidade, validar máquina de vendas e iniciar transição de dependência do fundador", "investment": "R$ 30.000 - R$ 45.000", "key_results": ["Atingir 10 reuniões qualificadas geradas pelo SDR com taxa de conversão mínima de 15% em propostas", "Reduzir índice de retrabalho em 20% comparado à média dos 3 meses anteriores ao projeto", "Transferir 3 relacionamentos-chave do fundador para outros sócios com plano documentado de handover"], "aligned_recommendation": "Programa de Sucessão e Fortalecimento de Marca Institucional"}], "success_metrics": ["Sistema de gestão operacional 100% implementado com dashboards de lucratividade ativos", "Máquina de vendas outbound gerando mínimo 10 reuniões qualificadas/mês ao final do ciclo", "Plano de sucessão iniciado com 3+ relacionamentos transferidos e assessment do board concluído"], "total_investment": "R$ 90.000 - R$ 140.000"}'::jsonb, '{"roadmap": ["Curto Prazo (3-6 meses): Implementar sistema de gestão operacional (horas, markup, lucratividade por conta), definir produtos/entregáveis e iniciar estruturação comercial com 1 SDR", "Médio Prazo (6-12 meses): Lançar plano de carreira, estabelecer OKRs trimestrais, automatizar processos repetitivos e desenvolver primeiros modelos de receita recorrente", "Longo Prazo (12+ meses): Consolidar marca institucional independente do fundador, expandir equipe com qualidade, atingir R$7-8M em receita mantendo margem >40%"], "key_findings": ["Produtização de serviços com markup padronizado é pré-requisito para escalar sem comprometer margem de 40%", "Modelo de receita recorrente (assinaturas) reduz volatilidade e aumenta valuation independente do fundador", "Legal Design e automação são diferenciais competitivos críticos contra commoditização do setor"], "main_findings": ["FORÇA: Expertise técnica consolidada em Direito Digital e LGPD com alta reputação no mercado de tecnologia", "FRAQUEZA: Dependência crítica do sócio fundador e ausência de estrutura comercial ativa (crescimento apenas orgânico)", "OPORTUNIDADE: Ambiente regulatório aquecido (LGPD, regulamentação de IA) gera demanda crescente por especialização", "AMEAÇA: Softwares CLM e consultorias de TI substituindo serviços jurídicos básicos, pressionando margens"], "important_notes": ["Board 100% jurídico e operacional limita visão estratégica - considerar conselheiro externo de negócios", "Concorrentes investindo em IA proprietária - atraso tecnológico pode ser irreversível em 18 meses", "Escassez de talentos sêniores em Direito Digital dificulta crescimento sem plano de carreira estruturado"], "central_challenge": "Transformar um escritório boutique dependente do fundador em uma empresa jurídica escalável, com estrutura comercial ativa, processos padronizados e marca institucional forte, mantendo margem >40%.", "executive_summary": "A Assis e Mendes possui expertise consolidada em Direito Digital/LGPD em mercado aquecido (CAGR 8.5%), mas enfrenta gargalos críticos: dependência do fundador, ausência de vendas estruturadas e precificação não padronizada. A transformação exige profissionalizar gestão, automatizar operações e construir marca institucional. O ambiente regulatório (IA, LGPD) oferece janela de crescimento, mas concorrentes investem pesado em tecnologia. Ação imediata é imperativa.", "strategic_priorities": ["Implantar controle de horas e precificação padronizada por serviço/advogado", "Estruturar área comercial outbound com metodologia e metas claras", "Criar plano de sucessão e fortalecer marca institucional vs. pessoal"], "overall_recommendation": "Priorize os próximos 90 dias para implantar gestão operacional e iniciar estruturação comercial. A janela de oportunidade regulatória é favorável, mas a inação permitirá que concorrentes capturem o mercado. Comece pelo controle interno antes de acelerar crescimento."}'::jsonb, '{"sam": "R$ 2.5B - 4.0B", "som": "R$ 15M - 30M", "tam": "R$ 45B - 60B", "cagr": "+8.5% a.a. (baseado em: CAGR setor Advocacia Digital 2023-2025 - macro_context)", "summary": "Mercado de Direito Digital em forte expansão. Assis e Mendes bem posicionado em nicho lucrativo. Potencial de triplicar receita (R$15-30M) com estruturação comercial e redução de dependência do fundador.", "assumptions": ["Mercado jurídico BR ~R$150B; Direito Digital/LGPD = 30-40% do empresarial (Análise Setorial 2025)", "SAM: Empresas tech SP + médias/grandes c/ demanda LGPD = ~6% do TAM (IBGE/Receita Federal)", "SOM: Market share boutique especializada 0.6-0.75% do SAM (benchmark escritórios nicho)"], "confidence_level": 62, "calculation_notes": "TAM baseado em mercado jurídico empresarial BR com foco digital. SAM filtrado por geografia (SP) e segmento (tech+LGPD). SOM considera posição de boutique especializada vs grandes bancas.", "data_sources_used": {"direct_data": ["Receita declarada: R$ 3-5M/ano", "CAGR setor: +8.5% (macro_context)"], "proxy_calculations": ["Concorrentes (Opice Blum, Patricia Peck): estimados R$ 30-80M cada", "11-50 funcionários × R$ 150-250k receita/funcionário = R$ 1.6-12.5M (validado)"], "benchmark_extrapolations": ["Mercado jurídico BR total: ~R$ 150B (CESA/FGV)", "Direito Digital = 3-4% do total, crescendo acima da média"]}, "estimation_method": "proxy_concorrentes"}'::jsonb, '{"summary": "Assis e Mendes possui expertise técnica comparável aos líderes do mercado de Direito Digital, mas opera em desvantagem estrutural. Enquanto Opice Blum e Patricia Peck construíram marcas institucionais independentes de seus fundadores, o escritório ainda depende fortemente da reputação pessoal de Adriano Mendes. Concorrentes diretos já implementaram áreas comerciais ativas, sistemas de precificação baseados em dados e governança profissionalizada. O gap mais crítico está na ausência de processos comerciais outbound — rivais captam clientes proativamente enquanto Assis e Mendes cresce apenas organicamente. A boa notícia: o posicionamento em nicho lucrativo (LGPD + Tech) e a margem-alvo de 40% são competitivos. Com estruturação comercial, automação de gestão e transição para marca institucional, há potencial real de escalar para R$15-30M mantendo lucratividade.", "best_practices": ["Opice Blum: Investimento pesado em IA proprietária para análise contratual, reduzindo custos operacionais em 30%", "Patricia Peck: Marca institucional forte com produção massiva de conteúdo educativo e presença em mídia nacional", "LBCA: Estrutura de partnership clara com plano de carreira transparente e metas trimestrais por advogado"], "performance_gaps": ["Ausência de equipe comercial estruturada vs. concorrentes com SDRs e hunters dedicados para prospecção ativa B2B", "Dependência crítica do sócio fundador enquanto rivais já operam com governança distribuída e marcas institucionais", "Falta de padronização de markup e controle de horas vs. concorrentes com sistemas de gestão jurídica integrados"], "competitors_analyzed": ["Opice Blum Advogados", "Patricia Peck Pinheiro Advogados", "Lee, Brock, Camargo Advogados (LBCA)", "Boutiques de Direito Digital em SP"]}'::jsonb, '{"raise": ["Automação com IA para análise contratual, due diligence e compliance LGPD", "Transparência radical: dashboards em tempo real de casos, custos e entregas", "Especialização vertical em regulação de IA e compliance para fintechs/SaaS"], "create": ["Assinaturas jurídicas mensais com escopo definido e preço fixo (Legal as a Service)", "Academia Assis e Mendes: certificações em LGPD e IA para clientes corporativos", "Motor comercial outbound com SDRs especializados em prospecção tech B2B"], "reduce": ["Revisões manuais repetitivas em contratos e pareceres padronizáveis", "Tempo de sócios em tarefas operacionais e administrativas do dia a dia", "Customização excessiva de serviços que poderiam ser produtizados"], "summary": "A estratégia transforma a Assis e Mendes de um escritório tradicional de advocacia boutique em uma plataforma jurídica escalável. Ao eliminar a opacidade na precificação e a dependência do fundador, reduzir trabalho manual repetitivo, elevar a automação e transparência, e criar modelos de receita recorrente (assinaturas) e uma academia de capacitação, o escritório escapa da guerra de preços do oceano vermelho. A diferenciação radical vem da combinação única: hiperespecialização em tech/IA + previsibilidade de custos + entrega visual (Legal Design) + relacionamento consultivo contínuo. Isso permite manter margens acima de 40% enquanto escala com qualidade, transformando a marca em ativo independente dos sócios.", "eliminate": ["Modelo de cobrança por hora opaco e imprevisível para o cliente", "Dependência de networking pessoal do sócio fundador como única fonte de vendas", "Entregáveis jurídicos densos e inacessíveis (juridiquês tradicional)"], "new_value_curve": "De boutique dependente do fundador para plataforma jurídica tech-first com receita recorrente, IA embarcada e marca institucional forte."}'::jsonb, '{"summary": "Estruturar outbound comercial para reduzir dependência orgânica, produtizar serviços com markup padronizado e criar loops de retenção via valor recorrente e expansão de escopo.", "leap_loop": {"name": "LEAP Loop", "type": "acquisition", "steps": ["Land: Prospects chegam via conteúdo especializado (LGPD, IA), eventos tech, indicações de clientes e parcerias com consultorias de TI/compliance.", "Engage: Webinars gratuitos sobre regulamentação de IA, newsletters com alertas jurídicos e diagnósticos rápidos de conformidade LGPD.", "Activate: Oferecer ''Raio-X LGPD'' gratuito de 30min, convertendo em proposta de adequação ou retainer mensal com entrega clara.", "Propagate: Programa de indicação com desconto para clientes, cases de sucesso públicos e co-marketing com empresas de tecnologia parceiras."], "metrics": ["CAC (Custo de Aquisição por Cliente)", "Taxa de Conversão Lead → Proposta → Cliente", "Coeficiente Viral (indicações por cliente)", "MQLs gerados por canal (orgânico vs outbound)"], "bottleneck": "Ausência de estrutura comercial ativa (outbound) e dependência exclusiva de crescimento orgânico e indicações do sócio fundador."}, "scale_loop": {"name": "SCALE Loop", "type": "monetization", "steps": ["Satisfy: Entregas com Legal Design, relatórios visuais de status, SLAs claros e comunicação proativa sobre riscos e oportunidades.", "Convert: Modelo híbrido: retainer mensal para compliance + success fee em contencioso + pacotes produtizados (ex: ''Kit LGPD Startup'').", "Loop Back: Revisões trimestrais de compliance, alertas regulatórios personalizados e renovação automática de contratos com reajuste.", "Expand: Upsell para contencioso estratégico, cross-sell de novas áreas (IA Compliance, M&A tech) e expansão para filiais do cliente."], "metrics": ["LTV (Lifetime Value por cliente)", "Taxa de Retenção Anual", "Receita de Expansão (upsell/cross-sell)", "Lucratividade por conta e por advogado"], "bottleneck": "Falta de padronização de markup e controle de horas, dificultando precificação rentável e escalabilidade sem perda de margem."}}'::jsonb, '{"realist": {"name": "Cenário Realista", "description": "SELIC estável em 10.75%, IPCA em 4.8%. Crescimento do setor jurídico digital mantém CAGR de 8.5%, mas clientes pressionam por eficiência (mais por menos). Reforma tributária impacta ISS, exigindo repricing. Concorrentes investem em IA proprietária; CLMs ameaçam serviços básicos. Escassez de talentos sêniores persiste. Faturamento cresce para R$5.5M, mas margem de 40% exige automação rigorosa e controle de horas.", "probability": 60, "required_actions": ["Implementar sistema de timesheet integrado com dashboard de lucratividade por cliente/advogado", "Adotar ferramentas de IA generativa para análise contratual, liberando júniores para tarefas de maior valor", "Definir markup padrão por tipo de serviço e revisar precificação trimestral", "Estruturar plano de carreira com trilhas claras para reter talentos e reduzir turnover"]}, "summary": "O cenário mais provável (60%) exige foco imediato em eficiência operacional: automação, controle de horas e precificação padronizada são críticos para sustentar margem de 40% sob pressão competitiva. A dependência do fundador é o maior risco estrutural; mitigá-la via sucessão e fortalecimento de marca institucional deve ser prioridade estratégica. O ambiente regulatório (LGPD, IA) oferece oportunidade de crescimento, mas exige investimento antecipado em especialização. Reserva de caixa e diversificação de receita protegem contra cenário pessimista de retração.", "optimistic": {"name": "Cenário Otimista", "description": "SELIC recua para 9% até 2026, aquecendo investimentos em tech. Regulamentação da IA (PL 2338/23) aprovada gera onda de demanda por compliance. ANPD intensifica fiscalização, multiplicando casos de contencioso LGPD. Clientes tech captam rodadas e expandem contratos. Assis e Mendes atinge R$7M com margem de 45%, consolidando-se como referência em IA Compliance e absorvendo talentos de concorrentes menores.", "probability": 20, "required_actions": ["Criar vertical dedicada a IA Compliance e certificar equipe antes da regulamentação", "Estruturar área comercial outbound para capturar demanda aquecida de LGPD/IA", "Acelerar contratação de 3-5 advogados sêniores aproveitando janela de captação de talentos", "Lançar pacotes de retainer premium para clientes tech em expansão"]}, "pessimistic": {"name": "Cenário Pessimista", "description": "SELIC sobe para 12.5% por pressão inflacionária; dólar atinge R$6.50. Clientes tech cortam jurídico, priorizando CLMs e consultorias de TI para compliance. Grandes bancas adquirem boutiques digitais, intensificando competição. Reforma tributária onera sociedades de advogados. Escassez de talentos agrava-se. Faturamento recua para R$3.2M; margem comprime para 30%. Dependência do fundador vira vulnerabilidade crítica.", "probability": 20, "required_actions": ["Reduzir custos fixos em 15% e renegociar contratos de fornecedores", "Pivotar para contencioso de recuperação de crédito (demanda anticíclica)", "Acelerar transição de liderança: delegar 50% das contas-chave para sócios operacionais"]}, "mitigation_tactics": ["Diversificar receita entre consultivo (LGPD/IA), contencioso e retainers recorrentes para reduzir volatilidade", "Investir em automação (IA + Legal Design) para manter margem de 40% mesmo sob pressão de preços", "Criar programa de sucessão estruturado para reduzir dependência do sócio fundador em 24 meses", "Estabelecer reserva de caixa equivalente a 6 meses de custo fixo para atravessar cenários adversos"], "early_warning_signals": ["SELIC acima de 11.5% por 2 trimestres consecutivos indica contração de investimentos tech", "Aumento de 20%+ em processos administrativos da ANPD sinaliza demanda aquecida de contencioso LGPD", "Perda de 2+ clientes-âncora para CLMs ou consultorias de TI indica commoditização acelerada", "Turnover de advogados sêniores acima de 15% a.a. sinaliza falha em retenção e risco operacional"]}'::jsonb, '{"summary": "O BSC alinha a transformação da Assis e Mendes em plataforma jurídica escalável: finanças focam em receita recorrente e markup controlado; clientes priorizam experiência diferenciada e aquisição ativa; processos eliminam ineficiências via automação e métricas granulares; aprendizado desenvolve talentos e institucionaliza conhecimento, reduzindo dependência do fundador e fortalecendo a marca como ativo independente.", "customer": ["Alcançar NPS >70 com entregas em Legal Design e SLA de resposta <4h", "Conquistar 15 novos clientes tech via outbound estruturado até Q4"], "financial": ["Atingir 30% de receita recorrente (assinaturas) até Q4, mantendo margem >40%", "Elevar faturamento para R$6M com markup padronizado de 2.5x sobre custo/hora"], "learning_growth": ["Lançar Academia A&M com trilhas de carreira e certificação interna até Q2", "Reduzir dependência do fundador: 80% das entregas sem revisão do sócio"], "internal_processes": ["Automatizar 60% das tarefas repetitivas com IA e reduzir retrabalho em 50%", "Implantar dashboard de lucratividade por cliente/advogado com revisão mensal"]}'::jsonb, '{"score": "8.2/10", "summary": "A análise multicriterial indica que a Alternativa 1 (Consolidação Interna) oferece o melhor equilíbrio entre ROI, mitigação de riscos e velocidade de resultados. O cenário macroeconômico de juros altos e competição crescente exige que o escritório primeiro ''arrume a casa'' antes de acelerar. A expansão comercial (Alternativa 2) é viável apenas após controles operacionais estarem maduros (6+ meses). A diversificação em IA (Alternativa 3) é oportunidade de médio prazo, mas requer investimento prévio em capacitação e representa maior risco de execução. Próximos passos imediatos: (1) Selecionar e contratar software de gestão até 30 dias; (2) Agendar assessment de board até 45 dias; (3) Definir OKRs do Q1 com base nas métricas listadas.", "criteria": ["ROI e Preservação de Margem (≥40%)", "Risco de Execução e Dependência do Fundador", "Tempo para Geração de Resultados Tangíveis"], "alternatives": ["Crescimento Estruturado com Foco em Eficiência Operacional (Consolidação Interna)", "Expansão Comercial Agressiva com Estruturação de Área de Vendas (Outbound Ativo)", "Diversificação de Portfólio e Hiperespecialização em Nichos Emergentes (IA + Regulação)"], "review_cycle": {"frequency": "Trimestral (Reunião de Board com pauta estruturada de OKRs)", "extraordinary_triggers": ["Publicação de regulamentação de IA (PL 2338/23) ou nova resolução ANPD com impacto direto em clientes", "Perda de cliente que represente >10% do faturamento anual", "Variação >15% na margem de lucratividade em qualquer trimestre", "Saída de advogado sênior ou sócio", "Proposta de aquisição ou fusão recebida"]}, "score_comparison": "+18% acima da segunda opção (Expansão Comercial: 6.9/10) e +31% acima da terceira (Diversificação: 6.3/10)", "monitoring_metrics": ["Margem de Lucratividade por Cliente e por Advogado (%)", "Taxa de Utilização (Horas Faturáveis / Horas Trabalhadas)", "Índice de Retrabalho (% de entregas com revisão não planejada)", "CAC - Custo de Aquisição de Cliente (R$ por novo cliente)", "NPS - Net Promoter Score de Clientes (trimestral)", "Receita por Advogado (R$/mês)", "Concentração de Receita no Fundador (% de clientes atendidos exclusivamente por ele)"], "recommended_option": "Crescimento Estruturado com Foco em Eficiência Operacional (Consolidação Interna)", "final_recommendation": "Priorizar eficiência operacional antes de escalar. Controle de horas, markup padronizado e redução de dependência do fundador são pré-requisitos para crescimento sustentável com margem ≥40%.", "priority_recommendations": [{"title": "Implementação de Sistema de Gestão e Controle Operacional", "budget": "R$ 60.000 - R$ 100.000", "priority": 1, "timeline": "3-6 meses", "description": "Implantar software de timesheet integrado com precificação (ex: Astrea, ADVBOX ou Themis). Padronizar markup mínimo de 3.5x sobre custo/hora. Criar dashboards de lucratividade por cliente, por advogado e por tipo de serviço. Automatizar relatórios de horas trabalhadas vs. faturadas e índice de retrabalho. Esta é a base para sustentar margem de 40% durante o crescimento e reduzir dependência de controles manuais do fundador."}, {"title": "Programa de Sucessão e Fortalecimento de Marca Institucional", "budget": "R$ 120.000 - R$ 180.000", "priority": 2, "timeline": "6-12 meses", "description": "Realizar assessment de competências do board atual (perfil DISC ou similar) para mapear gaps entre perfis existentes e funções necessárias (comercial, operações, financeiro). Desenvolver plano de transição de 18 meses para reduzir dependência do fundador: transferir relacionamentos-chave, criar porta-vozes alternativos, investir em branding institucional (casos de sucesso, certificações, prêmios). Definir critérios claros para promoção a sócio e criar plano de carreira com 5 níveis documentados."}, {"title": "Estruturação de Máquina de Vendas B2B (Outbound Controlado)", "budget": "R$ 80.000 - R$ 140.000", "priority": 3, "timeline": "6-9 meses", "description": "Contratar 1 SDR (Sales Development Representative) especializado em serviços B2B para prospecção ativa. Definir ICP (Ideal Customer Profile): empresas de tecnologia com 50-500 funcionários, faturamento R$ 10M-100M, sem departamento jurídico interno robusto. Criar playbook de vendas com scripts, cadências de e-mail e critérios de qualificação (BANT). Meta inicial: 10 reuniões qualificadas/mês, conversão de 20% em propostas. Investir em CRM (Pipedrive ou HubSpot) integrado ao sistema de gestão."}]}'::jsonb, 'completed', NULL, 122757, true, false, false, '5GO3V1BD', '2025-11-27 11:29:21.204481+00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-27 11:26:51.569776+00'::timestamptz, '2025-11-28 05:44:03.770068+00'::timestamptz, '2025-11-27 11:28:54.022706+00'::timestamptz, NULL)
